766:model Server {
1225:model Job {
1255:model WalletTransaction {
1269:model AuditLog {
1592:model Node {
1726:model Invoice {
3467:model GamePlan {
4518:model ChatConversation {
4555:model ChatMessage {
402:model CustomerNote {
1269:model AuditLog {
1726:model Invoice {
2292:model HostingTask {
2665:model WorkTask {
2705:model WorkTaskComment {
2717:model WorkTaskAttachment {
4329:model InsightsAlert {
4518:model ChatConversation {
4555:model ChatMessage {
4575:model ChatAttachment {
4651:model AbuseAlert {
4680:model NodeAlert {
6398:model AgencyQuote {
6417:model AgencyQuoteLineItem {
6858:model NxCloudTask {
7508:model SeoAuditRun {
7526:model SeoAuditPage {
7749:model ModVerifyTask {

model Plan {
  id              String        @id @default(cuid())
  slug            String        @unique
  name            String
  cpuCores        Int
  ramMB           Int
  diskGB          Int
  bandwidthTB     Float         @default(1)
  priceCents      Int
  /// LOW introductory MONTHLY price (cents) charged for the FIRST term only; the
  /// plan then RENEWS at the regular `priceCents` (classic hosting promo — e.g.
  /// "$3.99/mo first term, renews at $6.49/mo"). NULL = no intro (the plan bills
  /// `priceCents` from day one). Reused through the existing first-term-discount
  /// plumbing: the order stamps the implied first-term rate on
  /// `Server.termPromoPercent`, and every renewal path (lib/renewal-charge.ts)
  /// reads `priceCents` and knows nothing about this column, so renewal === regular
  /// by construction. Only honoured when strictly below `priceCents`.
  introPriceCents Int?
  /// How many of the first term's months are billed at `introPriceCents` before the
  /// remainder of that term reverts to the regular rate. NULL = the WHOLE first term
  /// is at the intro price (the common "$X first month, then $Y/mo" case is
  /// `introTermMonths = 1`). Ignored when `introPriceCents` is null.
  introTermMonths Int?
  storageTier     String        @default("nvme") // "nvme" | "hdd"
  active          Boolean       @default(true)
  sortOrder       Int           @default(0)
  createdAt       DateTime      @default(now())
  servers         Server[]
  gamePlans       GamePlan[]
  // NxCloud tiers that clone/size their VM from this Plan. A backing Plan for an
  // NxCloud tier is kept `active = false` so it never shows in the VPS wizard.
  nxcloudPlans    NxCloudPlan[]
}

enum ImageCategory {
  PLAIN_OS
  CONTROL_PANEL
  APPLICATION
}

/// An installable image shown in the deploy wizard. Plain OS clones `baseVmid`
/// directly; control panels / apps clone `baseVmid` then run `setupScript`
/// (cloud-init runcmd) to install the panel/app on first boot.
model OsTemplate {
  id              String        @id @default(cuid())
  slug            String        @unique
  name            String // display name, e.g. "Ubuntu"
  category        ImageCategory @default(PLAIN_OS)
  family          String        @default("linux") // ubuntu | debian | almalinux | rocky | cpanel | ...
  version         String        @default("") // "24.04", "13", ""
  logo            String        @default("") // icon slug for the UI
  vmid            Int // legacy/base template VMID to clone
  baseVmid        Int? // explicit base OS template for panels/apps (falls back to vmid)
  setupScript     String? // shell installed via cloud-init runcmd (panels/apps)
  minRamMB        Int           @default(1024)
  minDiskGB       Int           @default(10)
  licenseRequired Boolean       @default(false) // e.g. cPanel/Plesk need a paid license
  featured        Boolean       @default(false)
  sortOrder       Int           @default(0)
  active          Boolean       @default(true)
  servers         Server[]
}

/// Backup frequency & retention tier sold as a recurring add-on (lib/backup-tiers.ts).
/// MVP sells FREE (included, keep 2) and PLUS (paid, keep 7); PRO/PREMIUM are
/// defined for forward-compatibility but not offered in the funnel yet.
enum BackupTier {
  FREE
  PLUS
  PRO
  PREMIUM
}

model Server {
  id                            String                  @id @default(cuid())
  uptimeDays                    ServerUptimeDaily[]
  name                          String
  label                         String? // customer-facing nickname (rename)
  // Set when this order arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy, captured by PartnerSourceCapture). Null for every direct
  // Nxeon order. Gates the webhook notify in worker/index.ts on provision success.
  partnerSource                 String?
  // Globally unique across the ENTIRE fleet (VPS, game server, NxCloud alike) —
  // not just per-account. Before this constraint, every checkout path that left
  // the field blank silently handed out the same literal default ("web-01" for
  // VPS; "<family>-<rand>" for game servers, which could still collide), and
  // nothing stopped a customer from typing an already-used name either. A
  // hostname-keyed support/ops lookup (scripts/recover-errored-server.mjs) then
  // had no way to tell two same-named customers apart and grabbed the wrong
  // one's row — surfacing one customer's SSH port/status while working a
  // different customer's ticket (2026-09-24 incident, hsw901013@gmail.com).
  // Always write this through lib/hostname.ts's resolveUniqueHostname(), which
  // normalizes (trim+lowercase, matching HostingHostnameClaim's convention) and
  // auto-suffixes on collision instead of failing checkout or lying to the next
  // lookup. See scripts/find-duplicate-hostnames.ts / dedupe-hostnames.ts for
  // resolving pre-existing duplicates before this constraint can be applied
  // (prod currently has one: 7 servers literally named "web-01").
  hostname                      String                  @unique
  // Every hostname this server was EVER known as, oldest first, populated ONLY
  // by an admin-initiated rename of an EXISTING server (currently just
  // scripts/dedupe-hostnames.ts — ordinary checkout/admin-create paths write
  // `hostname` once at creation and never touch it again, so they never
  // append here). Exists because Invoice/WalletTransaction rows have no FK to
  // Server — every charge site instead embeds the hostname AT THE TIME OF
  // CHARGE in the record's `description` (see lib/server-spend.ts's own doc
  // comment for the full list of call sites and lib/actions-billing.ts's
  // `regenerateMissingInvoices`). A rename after those records were written
  // leaves them holding a hostname the server no longer has, so any
  // description-substring match keyed off the CURRENT hostname alone silently
  // stops finding them. Found live 2026-09-25: a real dedupe run on
  // 2026-09-24 renamed 6 duplicate "web-01" servers, which blanked their
  // "Total Spent" column on /admin/servers to "—" even though every one of
  // them has real, unbroken PAID invoice history. `resolveServerLifetimeSpendCents`
  // and `regenerateMissingInvoices` both match against `hostname` OR any
  // entry here so a rename can never again sever an existing record from the
  // server that earned it.
  previousHostnames             String[]                @default([])
  vmid                          Int?                    @unique
  status                        ServerStatus            @default(PENDING)
  ipAddress                     String?                 @unique
  sshPort                       Int?                    @unique
  // GUEST SSH PORT OVERRIDE (2026-09-30) — for a DEDICATED-IP server only.
  // connectionTarget() (lib/sftp.ts) has always assumed a dedicated-IP guest's
  // sshd listens on port 22 and ignored `sshPort` entirely for that case (that
  // field is the NAT-mapped external port for non-dedicated servers, a
  // different concept, and globally @unique — not safe to repurpose). A
  // customer who reconfigures their own guest's sshd to a non-standard port
  // (e.g. 2222) silently breaks every platform SSH feature — panel Files,
  // firewall sync, backups — with no way to tell it the new port. Found live
  // on a real HIGH-priority ticket (web-01-pvm4, 2026-09-30): customer moved
  // to port 2222 + key-only auth, firewall sync retried 3x and failed, Files
  // timed out; `nc` confirmed :22 closed and :2222 open, and the server's own
  // management key authenticated fine once dialed at :2222 directly. NULL
  // (the default, and every dedicated-IP server before this) means "assume
  // port 22" — connectionTarget() falls back with `?? 22`, so this column
  // changes behavior for nobody until explicitly set.
  guestSshPort                  Int?
  rootPassword                  String?
  rootPasswordEnc               String?
  // MANAGEMENT SSH KEY (2026-09-26) — a per-server ed25519 keypair, generated at
  // provision time (or backfilled via scripts/backfill-ssh-management-keys.ts for
  // servers that already existed), whose PUBLIC half is pushed into the guest's
  // authorized_keys. lib/ssh-exec.ts's withServerSsh tries this key BEFORE the
  // root password, so a customer who disables password auth (PasswordAuthentication
  // no) does not break Firewall Sync / SFTP / the database & website tools / staff
  // support access — all of which previously had no fallback and failed outright
  // with ssh2's "All configured authentication methods failed" (real incident,
  // ticket cmuifib3r0yvkhladt4m9ggtp). PER-SERVER, not one shared platform key —
  // a single leaked key only ever exposes the one server it belongs to, matching
  // the blast-radius profile `rootPasswordEnc` already has today, rather than
  // introducing one skeleton key for the whole fleet.
  // `sshManagementKeyEnc` is the OpenSSH-format PRIVATE key, encrypted at rest via
  // lib/crypto-box.ts (same AUTH_SECRET-derived AES-256-GCM box as rootPasswordEnc)
  // — decryptable, not hashed, because withServerSsh must present it on every
  // connection. `sshManagementPublicKey` is the plain authorized_keys LINE (public
  // keys are not secret) — shown to the customer in the dashboard's Root access
  // card so they can verify it themselves without filing a ticket. Both null on
  // any server not yet backfilled; withServerSsh falls back to the password in
  // that case, identical to today's behavior.
  sshManagementKeyEnc           String?
  sshManagementPublicKey        String?
  isFree                        Boolean                 @default(false)
  autoRenew                     Boolean                 @default(true)
  gameVariant                   String? // game-server type/loader (e.g. paper, carbon, bepinex) — see lib/game-config
  gameConfig                    Json? // per-game settings values (validated against the family schema)
  // Minecraft-only: `<subdomain>.play.nxeon.cloud`, resolved via a per-server DNS
  // SRV record (worker/game-subdomain.ts) instead of the free tier's shared
  // mc-router — see lib/game-subdomain.ts for the shared name-validation rules.
  // Null until the customer sets one; unique across THIS column only — cross-
  // checked against FreeMinecraftServer.subdomain at the application layer since
  // Postgres can't enforce a unique constraint across two different tables.
  subdomain                     String?                 @unique
  suspendedNote                 String?
  // WHY a server is suspended: "UNPAID" | "ABUSE" | "ADMIN". Null = never suspended.
  //
  // `suspendedNote` used to be the only signal, and nothing consumed it, so every
  // suspension looked identical to the billing engine. Two live consequences:
  // (1) `terminateOverdue` selected on `status: "SUSPENDED"` alone, while the
  //     renewal sweep EXCLUDES suspended servers — so an admin suspending a
  //     paid-up customer pending an investigation meant they were never charged,
  //     never warned, their term lapsed, and 13 days later their VM and all its
  //     data were destroyed with a "prolonged non-payment" notice they had never
  //     been given a chance to act on.
  // (2) `renewNow` auto-unsuspended ANY suspended server on payment, so a spammer
  //     suspended for outbound abuse could pay and put themselves straight back
  //     on the network.
  // Both now scope strictly to UNPAID.
  suspendReason                 String?
  // Human-readable reason a PROVISION failed terminally, set by the worker on the
  // ERROR path (worker/index.ts). Surfaced on the server detail page's ERROR
  // banner so the customer sees WHAT went wrong instead of a bare red status dot.
  // Cleared when a retry re-enqueues provisioning. Null = never failed (or the
  // failure predates this column).
  provisionError                String?
  // Best-effort, human-readable label for whichever real provisioning phase is
  // running RIGHT NOW (e.g. "Cloning your server…", "Waiting for the game server
  // to start…") — written by worker/index.ts's provision() between real,
  // observable checkpoints (clone / config / start / guest-agent boot / SSH
  // reachable / game port open). Read by lib/provisioning-step.ts and shown by
  // <ProvisioningOverlay/> in place of its cosmetic time-based cycling text.
  // Null = no real signal available yet (falls back to the cosmetic text) or the
  // server isn't mid-provision. Never cleared explicitly — it's simply ignored
  // once status leaves PENDING/PROVISIONING.
  provisioningStep              String?
  expiresAt                     DateTime?
  // ---- Dunning (failed auto-charge retry state) ----
  // dunningStage counts CARD ATTEMPTS THAT HAVE FAILED for the current unpaid
  // period: 0 = nothing owed / paid, 1..N = that many failures. Reset to 0 the
  // moment a renewal succeeds. `dunningNextAt` gates the next retry so a
  // 5-minute billing sweep cannot burn every retry in a quarter of an hour, and
  // `dunningPayUrl` is a hosted Checkout link emailed to the customer so they can
  // clear the balance themselves (also how 3-D Secure challenges are satisfied).
  dunningStage                  Int                     @default(0)
  dunningNextAt                 DateTime?
  dunningPayUrl                 String?
  // Platform-fault grace (2026-10-01, additive). Set when the renewal could not
  // be collected for a reason that is OURS, not the customer's — today: the saved
  // card was recorded in a way Stripe can never charge again (see
  // lib/stripe-charge-errors.ts). `suspendDueAt` never suspends before this
  // instant, whatever the calendar/dunning ladder says, and the worker runs a
  // "re-add your card" reminder ladder (day 0 / 1 / 3 / final) inside it instead
  // of the decline ladder. Also settable by an admin ("Extend grace" on the
  // card-health page). Null = no grace in effect. Cleared by commitRenewal.
  billingGraceUntil             DateTime?
  // Sent-marker for the pre-renewal "no card on file" reminder (worker/billing.ts
  // renewalReminderSweep). Set to `now` when a card-less owner is reminded that a
  // paid server is about to renew, and reset to null when that period actually
  // renews (commitRenewal), so each cycle can remind at most once. Null = not yet
  // reminded this cycle.
  renewalReminderSentAt         DateTime?
  createdAt                     DateTime                @default(now())
  updatedAt                     DateTime                @updatedAt
  userId                        String
  user                          User                    @relation(fields: [userId], references: [id])
  nodeId                        String?
  node                          Node?                   @relation(fields: [nodeId], references: [id])
  bwInBytes                     BigInt                  @default(0)
  bwOutBytes                    BigInt                  @default(0)
  abuseBwMark                   BigInt? // last bwOutBytes sample, for outbound-rate abuse detection
  abuseBwMarkAt                 DateTime? // when abuseBwMark was taken
  bwWindowStart                 DateTime                @default(now())
  termMonths                    Int                     @default(1) // 1=monthly, 12=annual, 24=biennial, 36=triennial
  /// PERCENT OFF the term-discounted monthly rate that the months currently sitting
  /// between `now` and `expiresAt` were ACTUALLY sold at. This is the rate basis
  /// every proration must price against (lib/proration.ts).
  ///
  /// WHY IT EXISTS (2026-07-26). `prorateDeltaCents` defaulted its rate basis to
  /// `currentPromo(now)` — whatever seasonal promo happened to be running at the
  /// instant a resize was priced. Promos rotate by calendar date from a 15% Launch
  /// Sale to 45% for Cyber Monday, so a customer could upgrade during Cyber Monday
  /// (delta priced at 55% of the honest rate, small charge) and downgrade during
  /// the Launch Sale (delta priced at 85%, large credit) and pocket the 30-point
  /// spread x plan delta x every remaining month — repeatable every promo cycle,
  /// self-service, with the platform's own marketing calendar as the schedule.
  /// lib/promotions.ts is explicit that a promo is a FIRST-TERM intro discount that
  /// renewals never receive, so pricing a mid-term change off today's promo was
  /// wrong even before it was exploitable.
  ///
  /// WHY A PERCENT AND NOT A CENTS RATE. Proration is a DIFFERENCE between two
  /// plans' rates. A stored $/mo figure prices only the plan the server is on and
  /// says nothing about the plan it is moving to, so the other half of the
  /// subtraction would still need a basis invented for it — which is the bug. A
  /// percent is a rate BASIS that applies to any plan price, so both halves of the
  /// delta come from this one persisted number and the round trip is symmetric by
  /// construction rather than by convention. It also survives a plan change with no
  /// write at all: the customer keeps the rate they bought at, so up-then-down is
  /// exactly zero.
  ///
  ///   0   = full price. What BOTH renewal paths bill (worker/billing.ts sweep and
  ///         lib/actions.ts renewNow charge `vpsTermPriceCents` with no promo), and
  ///         what a flat-priced game plan is sold at.
  ///   1-99= a genuine intro/seasonal discount, or a blend of paid and gifted
  ///         months (see prorateBlendPercent in lib/proration.ts).
  ///   100 = gifted. Nothing was paid for these months, so nothing may prorate out
  ///         of them — an admin extension/free grant records this.
  ///   NULL= unknown. Only on rows that predate this column; resolved by an
  ///         EXPLICIT conservative fallback (`resolveTermPromoPercent`), never by
  ///         falling through to today's promo, because that IS the bug above.
  ///
  /// FLOAT, not Int, even though every promo in the catalogue is a whole number.
  /// Blending a renewal into a part-used term lands on halves: 36 months at 45% off
  /// plus 36 renewed at full price is exactly 22.5% off, and rounding that to 23
  /// quietly shaves $7.20 off a $1,071.36 credit. A first term still stores the
  /// promo's exact integer, so the column reads the same for the common case.
  termPromoPercent              Float?
  /// PERCENT the ANNUAL (12-month) commitment discount was set to when THIS server's
  /// term was sold — a snapshot of `annual_discount_percent` (lib/annual-discount.ts)
  /// frozen at the moment of sale, exactly like `termPromoPercent` freezes the seasonal
  /// rate.
  ///
  /// WHY IT EXISTS. The annual discount became an admin-configurable setting, read LIVE
  /// by proration (lib/proration.ts, via `vpsEffectiveMonthly`). Both halves of a resize
  /// round trip therefore priced against whatever the setting held at the instant each
  /// half ran: an admin nudging `annual_discount_percent` between a customer's upgrade
  /// and their downgrade made the credit and the charge disagree, so an annual server's
  /// up-then-down no longer netted to zero. Freezing the rate the server was SOLD at and
  /// reading THAT from both proration directions makes the round trip symmetric by
  /// construction, the same way `termPromoPercent` does for the promo rate.
  ///
  ///   NULL = pre-existing row (predates this column) OR a non-annual/flat-priced server
  ///          that never had an annual discount. Proration falls back to the LIVE setting
  ///          for these — identical maths for every non-annual term, and the best
  ///          available basis for a legacy annual row.
  annualDiscountPct             Float?
  /// GRANDFATHER PROGRAM (2026-09-17). The plan/game-plan's per-month
  /// `priceCents` AT THE MOMENT THIS SERVER WAS CREATED — set on every order
  /// going forward, permanently, so a customer's renewal rate is locked to
  /// whatever the catalog charged on their signup day for the rest of their

model Job {
  id         String    @id @default(cuid())
  type       JobType
  status     JobStatus @default(QUEUED)
  payload    Json?
  error      String?
  progress   Int       @default(0) // 0..100 live task progress (backups/restores)
  step       String? // human-readable current step, e.g. "Creating archive… 42%"
  attempts   Int       @default(0)
  serverId   String?
  server     Server?   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  createdAt  DateTime  @default(now())
  updatedAt  DateTime  @updatedAt
  /// Set by the worker's atomic claim on the job's FIRST run (a retry keeps the
  /// original). `startedAt - createdAt` is the queue wait a customer actually
  /// experienced — the latency metric lib/job-metrics.ts reports. Null for
  /// rows that predate 2026-10-01.
  startedAt  DateTime?
  /// Set when the job reaches a terminal status (DONE/FAILED). `finishedAt -
  /// startedAt` is the run time, inclusive of retries.
  finishedAt DateTime?

  // The claim loop's hot query is `status = QUEUED ORDER BY createdAt`; the
  // metrics helper slices by (type, finishedAt). Both additive.
  @@index([status, createdAt])
  @@index([type, finishedAt])
}

/// `stripeSessionId` is UNIQUE: it is the idempotency key that makes crediting a
/// Checkout session safe against concurrent confirm-redirect + webhook delivery.
model WalletTransaction {
  stripeSessionId       String?  @unique
  // Same role as stripeSessionId but for OFF-SESSION renewal charges, which have
  // no Checkout session. The UNIQUE constraint — not a read-then-write check — is
  // what makes crediting an auto-charge idempotent when a sweep retries.
  stripePaymentIntentId String?  @unique
  id                    String   @id @default(cuid())
  userId                String
  user                  User     @relation(fields: [userId], references: [id])
  amountCents           Int
  description           String
  createdAt             DateTime @default(now())
}

model AuditLog {
  id        String   @id @default(cuid())
  userId    String?
  user      User?    @relation(fields: [userId], references: [id])
  action    String
  detail    String?
  createdAt DateTime @default(now())
  /// The caller's IP, for the Activity screen's "IP address" column. Null on
  /// anything the system did to itself — a cron renewal has no client.
  ip        String?
  /// Coarse grouping the Activity screen filters and counts by: server |
  /// billing | security | team | files | database | schedule | other.
  /// Derived at write time so the counts are a plain GROUP BY rather than a
  /// scan that re-classifies every row on every page load.
  category  String?
  /// The organisation the action belongs to, for the Team screen's per-org
  /// activity log. Null for a personal account with no organisation.
  orgId     String?
  /// What the action was performed ON — "Palworld Server", "MySQL Database".
  /// The Activity screen prints it under the action name; `detail` carries the
  /// sentence beside it. Split so the two can be styled apart without parsing.
  target    String?
model Invoice {
  id                 String              @id @default(cuid())
  number             Int                 @unique @default(autoincrement())
  userId             String
  user               User                @relation(fields: [userId], references: [id], onDelete: Cascade)
  amountCents        Int
  taxCents           Int                 @default(0)
  // The VAT/GST rate (percent) actually applied to this invoice's net, and the
  // destination country it was charged for. Recorded at creation from the customer's
  // billing country (lib/tax.ts) so the document states the rate and jurisdiction the
  // tax was collected under — required once tax is genuinely charged. 0 / null on a
  // no-tax invoice (unknown country, reverse charge, or a wallet top-up, which is
  // never a taxable sale).
  taxRatePercent     Float               @default(0)
  taxCountry         String?
  status             InvoiceStatus       @default(OPEN)
  // How much of this invoice has already been refunded. Refunds used to be bound
  // to nothing: `refundPayment` took only (userId, amount) and picked its Stripe
  // target as "most recent top-up, any amount" — so refunding a $24 March invoice
  // issued $24 against the customer's $200 July top-up, the invoice stayed PAID,
  // and the next admin refunded it again. Tracking it here lets the action refuse
  // to exceed the original and mark the invoice REFUNDED.
  refundedCents      Int                 @default(0)
  description        String
  lineItems          Json // [{ description, qty, unitCents, amountCents }]
  periodStart        DateTime?
  periodEnd          DateTime?
  paidAt             DateTime?
  // Snapshot of the card used to pay this invoice, captured at the PAID transition
  // so the record survives the customer later swapping or removing their card.
  // Nullable + additive: invoices issued before this existed fall back to the
  // user's current card fields at render time.
  paidBrand          String? // card brand snapshot at time paid (e.g. "visa")
  paidLast4          String? // card last4 snapshot at time paid
  createdAt          DateTime            @default(now())
  // KOL/agency partner commission ledger rows for this invoice: at most ONE
  // original accrual (reversalKey "") plus one REFUND row per refund/chargeback
  // event that reversed part of it (see PartnerCommission). The FK lives on
  // PartnerCommission, so this back-relation adds no column to the invoices table.
  partnerCommissions PartnerCommission[]
  // How much of `amountCents` (net, pre-tax) is the dedicated-IP surcharge on
  // THIS invoice. Populated at invoice-creation time by every charge path that
  // can bill a dedicated IP (lib/order.ts placeOrder, lib/game-order.ts
  // placeGameOrder, worker/billing.ts commitRenewal) from the same `ipCents` /
  // dedicated-IP figure already computed for that charge — never inferred by
  // parsing `lineItems` or `description` after the fact. Exists ONLY so
  // lib/partner-commission.ts can exclude it from a partner's commission base
  // (the dedicated-IP add-on earns a partner 0% — see the owner's spec): commission
  // math needs a real typed number here, not a string match against a line-item
  // description that could read "Dedicated IP" today and something else tomorrow.
  // 0 for every invoice that never carried a dedicated IP (the overwhelming
  // majority) and for every invoice created before this field existed — a
  // pre-existing commission row is never retroactively recomputed.
  dedicatedIpCents   Int                 @default(0)
}

// ---- Growth: coupons / promo codes ----
enum CouponKind {
  PERCENT // value = percent 1-100 (discount on order/topup)
  FIXED_CENTS // value = cents off
  CREDIT_CENTS // value = cents of wallet credit granted on redemption
  // value = the EXACT total price the first term charges, in cents, regardless
  // of which plan is bought — "$2.98 flat" rather than "X% off" or "$X off".
  // Added 2026-09-22 for the 7-day-trial promo: PERCENT/FIXED_CENTS can only
  // express a discount RELATIVE to the plan's price, which can't produce a
model GamePlan {
  id              String   @id @default(cuid())
  gameFamily      String // minecraft, valheim, rust, palworld, cs2, terraria, ...
  name            String // e.g. "Minecraft — 4 GB / 20 slots"
  ramMB           Int
  cpuCores        Int      @default(2)
  diskGB          Int
  slots           Int? // player slots (nullable)
  priceCents      Int // retail price the customer pays (per term) — the REGULAR/renewal rate
  /// GRANDFATHER PROGRAM (2026-09-17): mirrors Plan.introPriceCents/introTermMonths
  /// exactly — a lower first-term price that renews at the regular `priceCents`
  /// above. Read by the same generic lib/intro-pricing.ts helpers VPS already
