227	    }
228	  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
229	  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
230	  /** A dedicated-IP add-on purchased for an already-provisioned server (VPS or
231	   *  game). `chargeCents` is the FULL proration to debit on confirm, same
232	   *  convention as `resize`/`diskExpand`. */
233	  | { kind: "dedicatedIp"; userId: string; serverId: string; chargeCents: number }
234	  /** A shared-hosting order funded by card: the wallet was topped by the card leg,
235	   *  and `intent` is what `placeHostingOrder` re-places (debiting the wallet). */
236	  | { kind: "hostOrder"; userId: string; intent: HostOrderCheckoutIntent }
237	  /** A business-email order funded by card — the email analogue of `hostOrder`. */
238	  | { kind: "emailOrder"; userId: string; intent: EmailOrderCheckoutIntent }
239	  /** A domain registration funded by card. `domainOrderId` points at the
240	   *  `DomainOrderIntent` row `placeDomainCardOrder` reads for the actual
241	   *  registrant contact + price; `sold` is a metadata-only mirror of that row's
242	   *  price, present so a malformed/missing price never turns this into
243	   *  `unreadable` (the row, not the metadata, is what fulfilment charges). */
244	  | { kind: "domainOrder"; userId: string; domainOrderId: string; sold: DomainOrderPrice | null }
245	  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
246	  | { kind: "topup"; userId: string | null }
247	  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
248	  | { kind: "unpaid" }
249	  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
250	  | { kind: "unreadable"; userId: string | null; detail: string };
