252	/**
253	 * Classify a retrieved session. Pure — no clock, no network, no database — so the
254	 * routing decision is unit-testable and identical for the redirect and the webhook.
255	 */
256	export function classifyCheckoutSession(
257	  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status">,
258	): CheckoutPurpose {
259	  const md = session.metadata ?? null;
260	  const userId = parseId(md?.nxeonUserId);
261	  if (!userId || session.payment_status !== "paid") return { kind: "unpaid" };
262	
263	  const orderRaw = md?.nxeonOrder;
264	  if (orderRaw) {
265	    let intent: unknown;
266	    try {
267	      intent = JSON.parse(orderRaw);
268	    } catch {
269	      return { kind: "unreadable", userId, detail: "nxeonOrder is not valid JSON" };
270	    }
271	    if (!intent || typeof intent !== "object") {
272	      return { kind: "unreadable", userId, detail: "nxeonOrder is not an object" };
273	    }
274	    return {
275	      kind: "order",
276	      userId,
277	      intent: intent as OrderIntent,
278	      sold: parseOrderPrice(session.metadata?.nxeonOrderPrice),
279	      campaign: sanitizeCampaign(md?.nxeonPromoCampaign),
280	      promoReservationToken: parseId(md?.nxeonPromoReservation),
281	      couponReservationToken: parseId(md?.nxeonCouponReservation),
282	    };
283	  }
284	
285	  const gameRaw = md?.nxeonGameOrder;
286	  if (gameRaw) {
287	    let slim: Record<string, unknown>;
288	    try {
289	      slim = JSON.parse(gameRaw) as Record<string, unknown>;
290	    } catch {
291	      return { kind: "unreadable", userId, detail: "nxeonGameOrder is not valid JSON" };
292	    }
293	    if (!slim || typeof slim !== "object") {
294	      return { kind: "unreadable", userId, detail: "nxeonGameOrder is not an object" };
295	    }
296	    const gamePlanId = parseId(slim.gamePlanId);
297	    if (!gamePlanId) {
298	      return { kind: "unreadable", userId, detail: "nxeonGameOrder is missing gamePlanId" };
299	    }
300	    // The gameplay config rides in its own optional key; a missing/garbled blob is
301	    // simply dropped (placeGameOrder fills defaults), never treated as unreadable —
302	    // it is not money and cannot change the settled charge.
303	    let config: Record<string, unknown> | null = null;
304	    const rawCfg = md?.nxeonGameConfig;
305	    if (typeof rawCfg === "string" && rawCfg !== "") {
306	      try {
307	        const p = JSON.parse(rawCfg);
308	        if (p && typeof p === "object") config = p as Record<string, unknown>;
309	      } catch {
310	        config = null;
311	      }
312	    }
313	    const intent: GameOrderIntent = {
314	      gamePlanId,
315	      termMonths: typeof slim.termMonths === "number" ? slim.termMonths : 1,
316	      serverName: typeof slim.serverName === "string" ? slim.serverName : undefined,
317	      hostname: typeof slim.hostname === "string" ? slim.hostname : undefined,
318	      variant: typeof slim.variant === "string" ? slim.variant : undefined,
319	      subdomain: typeof slim.subdomain === "string" ? slim.subdomain : undefined,
320	      dedicatedIp: !!slim.dedicatedIp,
321	      region: typeof slim.region === "string" && slim.region ? slim.region : undefined,
322	      provider: slim.provider === "OVH" || slim.provider === "HETZNER" ? slim.provider : undefined,
323	      regionSource: slim.regionSource === "geo" || slim.regionSource === "default" || slim.regionSource === "explicit" ? slim.regionSource : undefined,
324	      config,
325	    };
326	    return {
327	      kind: "gameOrder",
328	      userId,
329	      intent,
330	      sold: parseGameOrderPrice(md?.nxeonGameOrderPrice),
331	      couponReservationToken: parseId(md?.nxeonCouponReservation),
332	    };
333	  }
334	
335	  const resizeRaw = md?.nxeonResize;
336	  if (resizeRaw) {
337	    let p: Record<string, unknown>;
338	    try {
339	      p = JSON.parse(resizeRaw) as Record<string, unknown>;
340	    } catch {
341	      return { kind: "unreadable", userId, detail: "nxeonResize is not valid JSON" };
342	    }
343	    const serverId = parseId(p?.serverId);
344	    const planId = parseId(p?.planId);
345	    const chargeCents = parseChargeCents(p?.chargeCents);
346	    if (!serverId || !planId || chargeCents === null) {
347	      return { kind: "unreadable", userId, detail: "nxeonResize is missing serverId/planId/chargeCents" };
348	    }
349	    return { kind: "resize", userId, serverId, planId, chargeCents };
350	  }
351	
352	  const expandRaw = md?.nxeonDiskExpand;
353	  if (expandRaw) {
354	    let p: Record<string, unknown>;
355	    try {
356	      p = JSON.parse(expandRaw) as Record<string, unknown>;
357	    } catch {
358	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is not valid JSON" };
359	    }
360	    const serverId = parseId(p?.serverId);
361	    const addGB = parseChargeCents(p?.addGB);
362	    const chargeCents = parseChargeCents(p?.chargeCents);
363	    if (!serverId || addGB === null || chargeCents === null) {
364	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is missing serverId/addGB/chargeCents" };
365	    }
366	    return { kind: "diskExpand", userId, serverId, addGB, chargeCents };
367	  }
368	
369	  const dedicatedIpRaw = md?.nxeonDedicatedIp;
370	  if (dedicatedIpRaw) {
371	    let p: Record<string, unknown>;
372	    try {
373	      p = JSON.parse(dedicatedIpRaw) as Record<string, unknown>;
374	    } catch {
375	      return { kind: "unreadable", userId, detail: "nxeonDedicatedIp is not valid JSON" };
376	    }
377	    const serverId = parseId(p?.serverId);
378	    const chargeCents = parseChargeCents(p?.chargeCents);
379	    if (!serverId || chargeCents === null) {
380	      return { kind: "unreadable", userId, detail: "nxeonDedicatedIp is missing serverId/chargeCents" };
381	    }
382	    return { kind: "dedicatedIp", userId, serverId, chargeCents };
383	  }
384	
385	  // Shared-hosting order funded by card. The full order inputs ride in nxeonHostOrder;
386	  // `planId` and `idempotencyKey` are the two fields fulfilment cannot proceed without
387	  // (the key governs the `hostorder:<key>` placement claim), so a payload missing
388	  // either is `unreadable`, never a silent top-up.
389	  const hostRaw = md?.nxeonHostOrder;
390	  if (hostRaw) {
391	    let p: Record<string, unknown>;
392	    try {
393	      p = JSON.parse(hostRaw) as Record<string, unknown>;
394	    } catch {
395	      return { kind: "unreadable", userId, detail: "nxeonHostOrder is not valid JSON" };
396	    }
397	    const planId = parseId(p?.planId);
398	    const idempotencyKey = parseId(p?.idempotencyKey);
399	    if (!planId || !idempotencyKey) {
400	      return { kind: "unreadable", userId, detail: "nxeonHostOrder is missing planId/idempotencyKey" };
401	    }
402	    const intent: HostOrderCheckoutIntent = {
403	      planId,
404	      idempotencyKey,
405	      domain: typeof p.domain === "string" ? p.domain : undefined,
406	      subdomainLabel: typeof p.subdomainLabel === "string" ? p.subdomainLabel : undefined,
407	      extraDiskGB: typeof p.extraDiskGB === "number" ? p.extraDiskGB : undefined,
408	      termMonths: typeof p.termMonths === "number" ? p.termMonths : undefined,
409	      appSlug: typeof p.appSlug === "string" ? p.appSlug : undefined,
410	    };
411	    return { kind: "hostOrder", userId, intent };
412	  }
413	
414	  // Business-email order funded by card. domainName + emailPlanId are load-bearing.
415	  const emailRaw = md?.nxeonEmailOrder;
416	  if (emailRaw) {
417	    let p: Record<string, unknown>;
418	    try {
419	      p = JSON.parse(emailRaw) as Record<string, unknown>;
420	    } catch {
421	      return { kind: "unreadable", userId, detail: "nxeonEmailOrder is not valid JSON" };
422	    }
423	    const domainName = parseId(p?.domainName);
424	    const emailPlanId = parseId(p?.emailPlanId);
425	    if (!domainName || !emailPlanId) {
426	      return { kind: "unreadable", userId, detail: "nxeonEmailOrder is missing domainName/emailPlanId" };
427	    }
428	    const intent: EmailOrderCheckoutIntent = {
429	      domainName,
430	      emailPlanId,
431	      termMonths: typeof p.termMonths === "number" ? p.termMonths : undefined,
432	    };
433	    return { kind: "emailOrder", userId, intent };
434	  }
435	
436	  // Domain registration funded by card. `domainOrderId` is the one thing that
437	  // must parse — without it fulfilment has nothing to look up and this must
438	  // never fall through to a silent top-up. The price mirror is best-effort: a
439	  // bad/missing `nxeonDomainOrderPrice` still classifies as a domainOrder with
440	  // `sold: null`, because the DomainOrderIntent row (not this metadata) is the
441	  // value `placeDomainCardOrder` actually charges.
442	  const domainRaw = md?.nxeonDomainOrder;
443	  if (domainRaw) {
444	    let p: Record<string, unknown>;
445	    try {
446	      p = JSON.parse(domainRaw) as Record<string, unknown>;
447	    } catch {
448	      return { kind: "unreadable", userId, detail: "nxeonDomainOrder is not valid JSON" };
449	    }
450	    const domainOrderId = parseId(p?.domainOrderId);
451	    if (!domainOrderId) {
452	      return { kind: "unreadable", userId, detail: "nxeonDomainOrder is missing domainOrderId" };
453	    }
454	    let sold: DomainOrderPrice | null = null;
455	    const priceRaw = md?.nxeonDomainOrderPrice;
456	    if (priceRaw) {
457	      try {
458	        const sp = JSON.parse(priceRaw) as Record<string, unknown>;
459	        const priceCents = parseChargeCents(sp?.priceCents);
460	        const costCents = parseChargeCents(sp?.costCents);
461	        if (priceCents !== null && costCents !== null) sold = { priceCents, costCents };
462	      } catch {
463	        sold = null;
464	      }
465	    }
466	    return { kind: "domainOrder", userId, domainOrderId, sold };
467	  }
468	
469	  return { kind: "topup", userId };
470	}
