472	/**
473	 * Retrieve a Checkout session ONCE. Throws when Stripe cannot be read — the caller
474	 * must never be able to mistake a transport failure for "this session is a top-up".
475	 */
476	export async function retrieveCheckoutSession(sessionId: string): Promise<Stripe.Checkout.Session> {
477	  if (!stripeConfigured()) throw new Error("Stripe is not configured");
478	  return stripe().checkout.sessions.retrieve(sessionId);
479	}
480	
481	/** Retrieve + classify in one step. Throws on a Stripe read failure, never lies. */
482	export async function getCheckoutPurpose(sessionId: string): Promise<CheckoutPurpose> {
483	  return classifyCheckoutSession(await retrieveCheckoutSession(sessionId));
484	}
