486	/**
487	 * True when this session's card payment is the FUNDING LEG of a purchase — a VPS
488	 * order, an upgrade, a disk expansion — rather than a wallet top-up the customer
489	 * bought for its own sake.
490	 *
491	 * The wallet is the settlement bus for every card-paid purchase: the card amount
492	 * is credited in, then the purchase debits the full total back out. That credit is
493	 * plumbing, not a product, and it must not be documented as one.
494	 *
495	 * REAL INCIDENT (2026-07-26 rehearsal, H3): every paid session got a PAID "Wallet
496	 * top-up" invoice here AND a PAID invoice from whatever it funded, so one $82.53
497	 * annual purchase produced `Wallet top-up $82.53` + `Starter VPS — Annual $82.53`
498	 * and the invoices page reported $165.06 paid lifetime — a customer reconciling
499	 * against their card statement saw twice their spend. Each document was internally
500	 * consistent; there were simply two of them for one payment. worker/billing.ts
501	 * already states the rule for the renewal path: "No invoice for the card leg …
502	 * a second document for the card portion would double-count the same revenue."
503	 *
504	 * Reads the same three metadata keys `lib/fulfil-checkout.ts` dispatches on, so
505	 * "did this session fund a purchase" has one answer, not two.
506	 */
507	export function isPurchaseLegSession(metadata: Stripe.Metadata | null | undefined): boolean {
508	  return !!(
509	    metadata?.nxeonOrder ||
510	    metadata?.nxeonGameOrder ||
511	    metadata?.nxeonResize ||
512	    metadata?.nxeonDiskExpand ||
513	    metadata?.nxeonDedicatedIp ||
514	    metadata?.nxeonHostOrder ||
515	    metadata?.nxeonEmailOrder ||
516	    metadata?.nxeonDomainOrder
517	  );
518	}
519	
520	/**
521	 * Credit a user's wallet for a completed Checkout session, idempotently.
522	 * Called from both the success-redirect confirm route (works without HTTPS)
523	 * and the webhook (belt-and-suspenders once HTTPS is available).
524	 * Returns true if a credit was applied this call.
525	 *
526	 * Takes the ALREADY-RETRIEVED session rather than an id: `fulfilCheckoutSession`
527	 * fetches it once and both the credit and the fulfilment routing read that single
528	 * object, so the two can never disagree about what this payment was (and a Stripe
529	 * read failure surfaces in one place, loudly, instead of four times as `null`).
530	 */
531	export async function creditCheckoutSession(session: Stripe.Checkout.Session): Promise<boolean> {
532	  const userId = session.metadata?.nxeonUserId;
533	  // USD cents to credit. For an ordinary (USD) session this is `amount_total`
534	  // exactly as before; a local-payment-method session is charged in SGD/INR, so
535	  // its credit comes from the USD amount it was priced for (see walletCreditCents).
536	  const cents = walletCreditCents(session);
537	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
538	
539	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
540	  // session id inside the description.
541	  const legacy = await db.walletTransaction.findFirst({
542	    where: { stripeSessionId: null, description: { contains: session.id } },
543	  });
544	  if (legacy) return false;
545	
546	  // Is this credit a product the customer bought, or the funding leg of something
547	  // else they bought? Only the first is a "Wallet top-up" and only the first gets
548	  // a billing document — see isPurchaseLegSession for the incident.
549	  const purchaseLeg = isPurchaseLegSession(session.metadata);
550	
551	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
552	  // read-then-write check. The confirm-redirect and the webhook can arrive
553	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
554	  // only the database can safely decide the winner. P2002 == already credited.
555	  const ops: Prisma.PrismaPromise<unknown>[] = [
556	    db.walletTransaction.create({
557	      data: {
558	        userId,
559	        amountCents: cents,
560	        description: `Stripe payment (${session.id})`,
561	        stripeSessionId: session.id,
562	      },
563	    }),
564	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
565	    db.notification.create({
566	      data: {
567	        userId,
568	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
569	        href: "/dashboard/billing",
570	      },
571	    }),
572	  ];
573	  // Index of the invoice-create inside `ops`, or -1 when no invoice is issued
574	  // (a purchase leg). Used to recover the new invoice's id for the receipt email.
575	  let invoiceOpIndex = -1;
576	  if (!purchaseLeg) {
577	    // PAID invoice for the top-up. Created in the SAME guarded transaction as
578	    // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
579	    // the credit idempotent also prevents a duplicate invoice on replay.
580	    //
581	    // A purchase leg is deliberately left undocumented HERE: the order, resize or
582	    // disk-expansion it funds issues the one invoice for the whole purchase, and
583	    // that document — not this one — is what the customer's card statement shows.
584	    // If the fulfilment then fails the money stays in the wallet as an ordinary
585	    // credit (ledger row + notification), and the invoice is issued by whatever it
586	    // is eventually spent on; inventing a top-up document at that point would
587	    // double-count the same dollars all over again the moment they deploy.
588	    // Remember WHERE in the batch this lands, so the created row's id can be read
589	    // back out of the transaction result. The receipt email promises the customer
590	    // an attached invoice, and it can only keep that promise if it knows the id.
591	    invoiceOpIndex = ops.length;
592	    ops.push(
593	      db.invoice.create({
594	        data: invoiceCreateData({
595	          userId,
596	          description: "Wallet top-up",
597	          status: "PAID",
598	          lineItems: [
599	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
600	          ],
601	        }),
602	      }),
603	    );
604	  }
605	  let invoiceId: string | undefined;
606	  try {
607	    const results = await db.$transaction(ops);
608	    if (invoiceOpIndex >= 0) {
609	      const created = results[invoiceOpIndex] as { id?: string } | undefined;
610	      invoiceId = created?.id;
611	    }
612	  } catch (e) {
613	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
614	    throw e;
615	  }
616	  // A funded wallet is the referred user's first paid action — reward both sides.
617	  try {
618	    const { maybeRewardReferral } = await import("./actions-growth");
619	    await maybeRewardReferral(userId);
620	  } catch { /* best-effort */ }
621	  try {
622	    // On a purchase leg, skip this generic receipt entirely: the order this
623	    // credit is funding (VPS/hosting/email/game) issues its OWN specific,
624	    // itemised invoice_new email moments later (the same one fixed today to
625	    // correctly say "paid" rather than "due"), and it names the actual plan/
626	    // domain/hostname the money bought. Sending BOTH meant every purchase-
627	    // funding payment produced two emails: a generic, invoice-less "Payment
628	    // received — your Nxeon order" (real customer feedback: "this email is
629	    // weak") immediately followed by the real invoice — pure noise. A genuine
630	    // standalone top-up (not funding a specific purchase) still gets this
631	    // receipt, since nothing else will ever tell the customer their wallet
632	    // balance grew.
633	    if (!purchaseLeg) {
634	      const u = await db.user.findUnique({ where: { id: userId } });
635	      if (u) {
636	        const { sendMail, emails } = await import("./mailer");
637	        const tpl = emails.receipt(
638	          `$${(cents / 100).toFixed(2)}`,
639	          "wallet top-up",
640	          !!invoiceId,
641	        );
642	        // `kind` + `userId` hands this to the preference policy in lib/prefs.ts.
643	        // A receipt is ACCOUNT tier — suppressible by email if the customer
644	        // turned account email off.
645	        await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html, userId, kind: "receipt", invoiceId });
646	      }
647	    }
648	  } catch { /* best-effort */ }
649	  return true;
650	}
651

      }
      // Same `?purchase=1` stamp the VPS/game branches get via reportPurchase —
      // this was previously missing here, so a card-paid hosting order landed on
      // the account page with NO signal to <ProvisioningOverlay/> that a purchase
      // just completed (the SANDBOX-instant-complete case would then never show a
      // success card at all). See also the wallet-only path in
      // HostingDeployWizard.tsx's place(), which had the identical gap.
      const hostUser = await db.user.findUnique({ where: { id: hostOrder.userId } });
      const redirect = await reportPurchase(`${base}/dashboard/hosting/${res.accountId}`, session, hostUser?.email, hostOrder.userId, "hosting");
      return { redirect, fulfilled: true, kind: "hostOrder" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(hostOrder.userId);
      try {
        await recordDeployFunnelError({ product: "hosting", step: "Payment", stepIndex: 7, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: hostOrder.userId });
      } catch {
        /* analytics must never disturb fulfilment */
      }
      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "hostOrder", error: msg };
    }
  }

  // Business-email order funded by card — the email analogue of the branch above. The
  // card leg was credited to the wallet; `placeEmailCardOrder` re-verifies the session
  // and runs `orderEmailHostingCore`, which DEBITS the wallet and creates the
  // subscription (its domain dupe guard is the placement idempotency).
  const emailOrder = purpose.kind === "emailOrder" ? purpose : null;
  if (emailOrder) {
    if (!(await claim(sessionId, "emailOrder"))) {
      return { redirect: `${base}/dashboard/email`, fulfilled: false, kind: "emailOrder" };
    }
    try {
      const res = await placeEmailCardOrder(sessionId);
      if ("skip" in res) throw new Error("session did not classify as an email order");
      if (res.error || !res.ok) throw new Error(res.error || "email order failed");
      await settle(sessionId, "DONE");
      if (provider === "stripe") {
        try {
          await saveCardFromPaymentSession(session, emailOrder.userId);
        } catch {
          /* best-effort: fulfilment already succeeded */
        }
      }
      return { redirect: `${base}/dashboard/email?paid=1`, fulfilled: true, kind: "emailOrder" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(emailOrder.userId);
      return { redirect: `${base}/dashboard/email?paid=1`, fulfilled: false, kind: "emailOrder", error: msg };
    }
  }

  // Domain registration funded by card — the domain analogue of the branches
  // above. `placeDomainCardOrder` re-verifies the session itself and runs the
  // exact same `registerDomainCore` the wallet path uses (lib/actions-domains.ts),
  // against the FROZEN price + contact stashed in `DomainOrderIntent` at
  // checkout-session-creation time — never a fresh registrar re-quote here.
  // Its three outcomes ("active"/"recovered" from registerDomainCore's own
  // registered-verdict, "refunded", "needs-review") all still count as this
  // Stripe session being resolved — the card cleared and the money's fate is
  // decided either way — so all three claim + settle, and only "active" is
  // `fulfilled: true` with the success redirect.
  const domainOrder = purpose.kind === "domainOrder" ? purpose : null;
  if (domainOrder) {
    if (!(await claim(sessionId, "domainOrder"))) {
      return { redirect: `${base}/dashboard/domains`, fulfilled: false, kind: "domainOrder" };
    }
    try {
      const res = await placeDomainCardOrder(sessionId);
      if ("skip" in res) throw new Error("session did not classify as a domain order");
      if ("error" in res) throw new Error(res.error);
      if (res.kind === "active") {
        await settle(sessionId, "DONE", res.domainId);
        if (provider === "stripe") {
          try {
