605	export async function applyOrderRegion(intent: OrderIntent, userId: string): Promise<void> {
606	  if (intent.nodeId) return;
607	  const [plan, os] = await Promise.all([
608	    db.plan.findUnique({ where: { id: intent.planId }, select: { ramMB: true } }),
609	    db.osTemplate.findUnique({ where: { id: intent.osTemplateId }, select: { vmid: true, baseVmid: true } }),
610	  ]);
