  CUSTOM_PLAN_DEFAULT_INTRO_PERCENT,
  CUSTOM_PLAN_DEFAULT_RATES,
  CUSTOM_PLAN_NEEDS_SALES_REASON,
  CUSTOM_PLAN_SORT_ORDER,
  computeCustomGamePlanPriceCents,
  computeCustomIntroPriceCents,
  computeCustomPlanPriceCents,
  customPlanIntroTerms,
  customPlanName,
  customPlanSlug,
  gameCustomFloor,
  parseGameFamilyRatesOverride,
  validateCustomPlanSpec,
} from "./custom-plan-pricing";

export { CUSTOM_PLAN_NEEDS_SALES_REASON, CUSTOM_PLAN_SORT_ORDER } from "./custom-plan-pricing";

export class CustomPlanError extends Error {}

/**
 * The spec is valid and priced, but no node can take it right now, so the wizard
 * can't auto-deploy it. Its own subclass so the "use server" layer
 * (lib/actions-custom-plan.ts) can tell this apart from a bad spec and send the
 * customer to the sales-request path instead of a dead-end error. The message is
 * what the customer reads. It says the build needs a person, not that the host is
 * full (see CUSTOM_PLAN_NEEDS_SALES_REASON in lib/custom-plan-pricing.ts).
 */
export class CustomPlanCapacityError extends CustomPlanError {}


/**
 * Sort-order convention already established by the ONE pre-existing manual
 * precedent (a "Custom 4 vCPU / 8 GB" Plan row, `sortOrder: 999, active: false`,
 * created before this feature existed for a one-off customer accommodation).
 * `sortOrder < CATALOG_SORT_ORDER_CEILING` is the live premade VPS ladder;
 * 900-903 are NxCloud's backing plans (also `active: false` — see prisma/schema.prisma's
 * comment on `Plan.nxcloudPlans`); `CUSTOM_PLAN_SORT_ORDER` (999) is reserved for
 * one-off custom rows. Both ranges keep `customPlanFloor` below from ever picking
 * up an NxCloud sizing plan or (worse) a PREVIOUS custom order's own Plan row as
 * "Max".
 */
const CATALOG_SORT_ORDER_CEILING = 900;

/**
 * The floor every custom spec must clear: the current top-priced ACTIVE premade
 * VPS plan (today, Max). Read live from the DB rather than hardcoded, so a future
 * catalog change (a new tier added above Max) is picked up automatically with no
 * code change here.
 */
function topCatalogVpsPlan() {
  return db.plan.findFirst({
    where: { active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
    orderBy: { priceCents: "desc" },
  });
}

export async function customPlanFloor(): Promise<CustomPlanFloor> {
  const top = await topCatalogVpsPlan();
  if (!top) throw new CustomPlanError("No base plan is configured yet — please contact support.");
  return {
    cpuCores: top.cpuCores,
    ramMB: top.ramMB,
    diskGB: top.diskGB,
    priceCents: top.priceCents,
    bandwidthTB: top.bandwidthTB,
  };
}

/** Admin-tunable percent off a custom build's FIRST term (lib/settings.ts
 *  `custom_plan_intro_percent`, default 30). Read through `getSettingInt`,
 *  which is really `Number()`, so a decimal such as "30.5" also works.
 *  Clamping to 0..90 happens in `customPlanIntroTerms`. */
export async function customPlanIntroPercent(): Promise<number> {
  return getSettingInt("custom_plan_intro_percent", CUSTOM_PLAN_DEFAULT_INTRO_PERCENT);
}

/**
 * The intro terms for a custom VPS build: the admin percent, with the
 * anti-undercut floor set to Max's own first-term price (its intro, else its
 * regular price). `null` when the setting is 0. See the INTRO comment in
 * lib/custom-plan-pricing.ts.
 */
export async function customPlanIntro(): Promise<CustomPlanIntro | null> {
  const [top, pct] = await Promise.all([topCatalogVpsPlan(), customPlanIntroPercent()]);
  if (!top) return null;
  return customPlanIntroTerms(planIntroMonthlyCents(top) ?? top.priceCents, pct);
}

/** Admin-tunable platform-wide ceiling (lib/settings.ts custom_plan_max_*). */
export async function customPlanCeiling(): Promise<CustomPlanCeiling> {
  const [maxCpuCores, maxRamGB, maxDiskGB] = await Promise.all([
    getSettingInt("custom_plan_max_cpu_cores", CUSTOM_PLAN_DEFAULT_CEILING.maxCpuCores),
    getSettingInt("custom_plan_max_ram_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxRamMB / 1024),
    getSettingInt("custom_plan_max_disk_gb", CUSTOM_PLAN_DEFAULT_CEILING.maxDiskGB),
  ]);
  return { maxCpuCores, maxRamMB: maxRamGB * 1024, maxDiskGB };
}

/** Admin-tunable per-unit rates. Disk reuses `extraDiskPerGbCents()` — the SAME
 *  $/GB the extra-disk upsell already charges on a premade plan — see the
 *  derivation comment on CUSTOM_PLAN_DEFAULT_RATES for why. */
export async function customPlanRates(): Promise<CustomPlanRates> {
  const [perVcpuCents, perRamGbCents, perDiskGbCents] = await Promise.all([
    getSettingInt("custom_plan_per_vcpu_cents", CUSTOM_PLAN_DEFAULT_RATES.perVcpuCents),
    getSettingInt("custom_plan_per_ram_gb_cents", CUSTOM_PLAN_DEFAULT_RATES.perRamGbCents),
    extraDiskPerGbCents(),
  ]);
  return { perVcpuCents, perRamGbCents, perDiskGbCents };
}

/**
 * Genre-average fallback for a game family that has real `GamePlan` tiers but not
 * enough of them (exactly one, so a $/RAM-GB slope has no second data point to derive
 * from — see lib/custom-plan-pricing.ts's derivation comment). NOT hit by anything in
 * the live catalog today (every family with any tiers has at least 2 — see that same
 * comment), but a new family could plausibly launch with just one tier seeded before a
 * second ships, and this keeps that case priced (clearly flagged as an estimate)
 * instead of silently falling through to `CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS`'s
 * `undefined` and gating the family for a reason that isn't actually "we have zero
 * data" — we have a real anchor tier, just not a real slope.
 *
 * Averages the derived (non-estimated) rates of every OTHER family that shares at
 * least one genre tag (lib/games.ts GAME_GENRES) with this one; a family with no genre
 * tag, or no genre-mates in the table, falls back to the average of the WHOLE table —
 * still grounded in real derived data, just not narrowed by genre. Never fabricated
 * from nothing: this only ever runs for a family that already has one real tier
 * anchoring its base price, and only picks the SLOPE from other real games' data.
 */
export function estimatedGameFamilyRamRateCents(
  family: string,
  ramRatesCents: Record<string, number>,
): { cents: number; estimated: true; basis: string } {
  const genres = GAME_GENRES[family as GameFamily];
  const allRates = Object.entries(ramRatesCents).filter(([f]) => f !== family);
  const genreMates = genres?.length
    ? allRates.filter(([f]) => GAME_GENRES[f as GameFamily]?.some((g) => genres.includes(g)))
    : [];
  const pool = genreMates.length ? genreMates : allRates;
  const avg = pool.reduce((s, [, c]) => s + c, 0) / (pool.length || 1);
  return {
    cents: Math.round(avg),
    estimated: true,
    basis: genreMates.length
      ? `genre average (${genreMates.length} family/families sharing ${genres!.join("/")})`
      : "platform-wide average across all derived game families",
  };
}

/**
 * The admin-tunable GAME rate SETTINGS, loaded once: the shared per-vCPU rate
 * (`custom_plan_game_per_vcpu_cents`), the per-family RAM-GB override table
 * (`custom_plan_game_ram_rates_json`, merged over CUSTOM_GAME_PLAN_DEFAULT_RAM_GB_CENTS
 * — see lib/custom-plan-pricing.ts), and disk (`extraDiskPerGbCents()`, shared with
 * VPS). Split out from `customGamePlanRates` below so a caller resolving MANY
 * families in one request (the deploy wizard's page loader builds a `CustomPlanConfig`
 * per game family) reads these 2 settings ONCE rather than once per family.
 */
export async function loadGameRateSettings(): Promise<{
  perVcpuCents: number;
  ramRatesCents: Record<string, number>;
  perDiskGbCents: number;
}> {
  const [perVcpuCents, ramRatesJson, perDiskGbCents] = await Promise.all([
    getSettingInt("custom_plan_game_per_vcpu_cents", CUSTOM_GAME_PLAN_DEFAULT_PER_VCPU_CENTS),
    getSetting("custom_plan_game_ram_rates_json", ""),
    extraDiskPerGbCents(),
  ]);
  return { perVcpuCents, ramRatesCents: parseGameFamilyRatesOverride(ramRatesJson), perDiskGbCents };
}

/**
 * Pure: resolve ONE family's rates from already-loaded settings (`loadGameRateSettings`).
 * Always resolves to SOME rate once a family has at least one real tier to anchor
 * from — the "we truly have nothing" case (zero tiers at all) is caught earlier, by
 * checking for a top tier before this is ever called.
 */
export function resolveGameFamilyRates(
  gameFamily: string,
  settings: { perVcpuCents: number; ramRatesCents: Record<string, number>; perDiskGbCents: number },
): { rates: CustomPlanRates; estimated: boolean; basis?: string } {
  const direct = settings.ramRatesCents[gameFamily];
  if (direct !== undefined) {
    return {
      rates: { perVcpuCents: settings.perVcpuCents, perRamGbCents: direct, perDiskGbCents: settings.perDiskGbCents },
      estimated: false,
    };
  }
  const est = estimatedGameFamilyRamRateCents(gameFamily, settings.ramRatesCents);
  return {
    rates: { perVcpuCents: settings.perVcpuCents, perRamGbCents: est.cents, perDiskGbCents: settings.perDiskGbCents },
    estimated: true,
    basis: est.basis,
  };
}

/** `loadGameRateSettings` + `resolveGameFamilyRates` for a single family — the
 *  convenient one-shot form for a caller (`customGamePlanQuote` below) that only
 *  ever needs one family per call. */
export async function customGamePlanRates(
  gameFamily: string,
): Promise<{ rates: CustomPlanRates; estimated: boolean; basis?: string }> {
  return resolveGameFamilyRates(gameFamily, await loadGameRateSettings());
}

export type CustomPlanQuote =
  | {
      ok: true;
      floor: CustomPlanFloor;
      ceiling: CustomPlanCeiling;
      rates: CustomPlanRates;
      /** Regular monthly price: what every renewal bills. */
      priceCents: number;
      /** First-term monthly price (`introPriceCents` on the row this spec
       *  becomes), or null when this build has no intro. */
      introPriceCents: number | null;
      intro: CustomPlanIntro | null;
    }
  | { ok: false; reason: string; floor: CustomPlanFloor; ceiling: CustomPlanCeiling };

/** Validate + price a custom spec without creating anything. Never throws — a bad
 *  spec comes back `{ ok: false, reason }` so the wizard can show it inline. */
export async function customPlanQuote(spec: CustomPlanSpec): Promise<CustomPlanQuote> {
  const [floor, ceiling, rates, intro] = await Promise.all([
    customPlanFloor(),
    customPlanCeiling(),
    customPlanRates(),
    customPlanIntro(),
  ]);
  const v = validateCustomPlanSpec(spec, floor, ceiling);
  if (!v.ok) return { ok: false, reason: v.reason, floor, ceiling };
  const priceCents = computeCustomPlanPriceCents(spec, floor, rates);
  const introPriceCents = computeCustomIntroPriceCents(priceCents, intro);
  return { ok: true, floor, ceiling, rates, priceCents, introPriceCents, intro };
}

/**
 * The game analogue of `customPlanQuote` — same "never throws, {ok:false, reason}
 * on a bad spec" contract, but family-aware throughout: floor is
 * `gameCustomFloor` (widened per-family), rates are this family's own derived
 * rate, and price is `computeCustomGamePlanPriceCents` (extends the family's own
 * top tier, not the flat VPS Max price). This is what the deploy wizard's
 * "Build a custom X server" panel calls for BOTH its instant slider preview
 * bounds/rate display AND its debounced "authoritative" price/capacity check —
 * before this existed, the game builder silently reused the VPS-only
 * `quoteCustomPlanAction`, so a customer saw the WRONG (flat VPS) price while
 * sliding and only got the correct family-rate price after clicking through to
 * `confirmCustomGamePlanAction` — a real quote-vs-charge mismatch in the UI even
 * though what actually got charged was already correct. Fixed alongside the
 * create-path fix rather than left for later, since it is the same bug class
 * this whole change exists to close.
 *
 * `createCustomGamePlan` below calls this too (mirroring how `createCustomPlan`
 * calls `customPlanQuote`) so there is exactly one place this math lives.
 */
export async function customGamePlanQuote(
  gameFamily: string,
  spec: CustomPlanSpec,
): Promise<CustomPlanQuote> {
  const [topTier, vpsFloor, ceiling, introPct] = await Promise.all([
    db.gamePlan.findFirst({
      where: { gameFamily, active: true, sortOrder: { lt: CATALOG_SORT_ORDER_CEILING } },
      orderBy: { priceCents: "desc" },
    }),
    customPlanFloor(),
    customPlanCeiling(),
    customPlanIntroPercent(),
  ]);
  if (!topTier) {
    return {
      ok: false,
      reason: "Custom-sized servers for this game aren't available yet — there's no pricing catalog to build a custom quote from. Please contact support.",
      floor: vpsFloor,
      ceiling,
    };
  }
  const anchor: CustomGamePlanAnchor = {
    cpuCores: topTier.cpuCores,
    ramMB: topTier.ramMB,
    diskGB: topTier.diskGB,
    priceCents: topTier.priceCents,
  };
  const floor = gameCustomFloor(vpsFloor, anchor);
  const v = validateCustomPlanSpec(spec, floor, ceiling);
  if (!v.ok) return { ok: false, reason: v.reason, floor, ceiling };

  const gameRates = await customGamePlanRates(gameFamily);
  if (gameRates.estimated) {
    // Should never fire against the live catalog as of 2026-09-29 — see
    // estimatedGameFamilyRamRateCents's own comment. Logged here (not just in
    // createCustomGamePlan) so an admin notices the moment a QUOTE, not only a
    // real order, starts leaning on a genre-average guess.
    console.warn(`[custom-plan] ${gameFamily} quoted with an ESTIMATED RAM rate (${gameRates.basis})`);
  }
  const priceCents = computeCustomGamePlanPriceCents(spec, anchor, gameRates.rates, vpsFloor.priceCents);
  // Anti-undercut floor: THIS family's own top tier's first-term price (the same
  // row the regular price extends), its intro if it has one, else its regular price.
  const intro = customPlanIntroTerms(planIntroMonthlyCents(topTier) ?? topTier.priceCents, introPct);
  const introPriceCents = computeCustomIntroPriceCents(priceCents, intro);
  return { ok: true, floor, ceiling, rates: gameRates.rates, priceCents, introPriceCents, intro };
}

/**
 * The REAL, pre-checkout capacity check — reuses the exact oversell guards
 * lib/order.ts placeOrder / lib/game-order.ts placeGameOrder already run for
 * every premade-plan order (capacityCheckRamMB mirrors capacityCheck;
 * diskCapacityCheck is the identical function). A custom spec can ask for more
 * RAM than ANY catalog plan, so it must be screened the same way — this is not
 * a second, weaker guard, it's the same one with a raw RAM/disk number instead
 * of a `Plan` row backing it.
 */
export async function customPlanCapacityCheck(spec: CustomPlanSpec): Promise<{ ok: boolean; reason?: string }> {
  // `reason` is the customer-facing sales wording for EVERY failure (RAM, no
  // schedulable node, disk pool). The underlying guards' own reasons ("The host
  // is at capacity...", "This node's storage pool is nearly full...") are written
  // for a premade plan at checkout and are exactly the copy the owner flagged.
  // The gate itself is unchanged: a failing spec still can't be bought.
  const ramOk = await capacityCheckRamMB(spec.ramMB);
  if (!ramOk.ok) return { ok: false, reason: CUSTOM_PLAN_NEEDS_SALES_REASON };
  // Which node WOULD take this — same scheduler VPS/game orders use — so the disk
  // check below runs against a real candidate node's pool, not "any node".
  const node = await scheduleNode(spec.ramMB);
  if (!node) return { ok: false, reason: CUSTOM_PLAN_NEEDS_SALES_REASON };
  const disk = await diskCapacityCheck(node.id, spec.diskGB);
  return disk.ok ? disk : { ok: false, reason: CUSTOM_PLAN_NEEDS_SALES_REASON };
}

/** 6-char alnum suffix — matches the one pre-existing manual precedent's slug
 *  shape ("custom-4c8g-hmcebh"). */
function randSuffix(n = 6): string {
  return Math.random().toString(36).slice(2, 2 + n);
}

export type CreatedCustomPlan = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  /** First-term monthly price, or null. See lib/custom-plan-pricing.ts's INTRO comment. */
  introPriceCents: number | null;
  storageTier: string;
};

/**
 * Create ONE real `Plan` row for an exact spec+price — the same manual-accommodation
 * pattern already proven in production once (see the sort-order doc comment above),
 * now automated. Shared by `createCustomPlan` (VPS) and `createCustomGamePlan`
 * (game) below — the retry-on-slug-collision loop and row shape are identical, only
 * how `priceCents` gets computed differs between the two callers.
 *
 * Created INACTIVE with `sortOrder: 999` so it NEVER appears in any catalog query
 * (every page that lists plans filters `active: true` — see
 * app/dashboard/deploy/page.tsx) — it exists solely to be the ONE plan this ONE
 * order's Server row points at. From here on, every downstream money path
 * (lib/order.ts orderQuote/placeOrder, lib/resize.ts, lib/renewal-charge.ts,
 * lib/capacity.ts, admin displays) reads straight off the `Plan` relation exactly
 * like it does for a premade plan — no special-casing needed anywhere else.
 */
async function createCustomPlanRow(
  spec: CustomPlanSpec,
  priceCents: number,
  bandwidthTB: number,
  /** First-term price for a VPS row. Null for a game order's BASE plan: only
   *  the GamePlan tier is sold there (lib/game-order.ts reads the tier's intro,
   *  never the base plan's). */
  introPriceCents: number | null,
): Promise<CreatedCustomPlan> {
  let lastErr: unknown;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const plan = await db.plan.create({
        data: {
          slug: customPlanSlug(spec, randSuffix()),
          name: customPlanName(spec),
          cpuCores: spec.cpuCores,
          ramMB: spec.ramMB,
          diskGB: spec.diskGB,
          bandwidthTB,
          priceCents,
          // Same shape as every catalog plan's intro price: a lower FIRST term,
          // renewing at `priceCents`. null introTermMonths = the whole first
          // term, whatever its length. lib/order.ts orderQuote applies it.
          introPriceCents,
          introTermMonths: null,
          storageTier: "nvme",
          active: false,
          sortOrder: CUSTOM_PLAN_SORT_ORDER,
        },
      });
      return {
        id: plan.id,
        name: plan.name,
        cpuCores: plan.cpuCores,
        ramMB: plan.ramMB,
        diskGB: plan.diskGB,
        bandwidthTB: plan.bandwidthTB,
        priceCents: plan.priceCents,
        introPriceCents: plan.introPriceCents ?? null,
        storageTier: plan.storageTier,
      };
    } catch (e) {
      lastErr = e; // near-impossible slug collision (6-char random suffix) — retry once or twice
    }
  }
  throw lastErr instanceof Error ? lastErr : new CustomPlanError("Could not create the custom plan — please try again.");
}

/**
 * Re-validates guardrails AND capacity from scratch (a client-supplied price/spec is
 * never trusted for money — mirrors every other quote→place split in this codebase)
 * before writing anything, then hands off to `createCustomPlanRow`.
 */
export async function createCustomPlan(spec: CustomPlanSpec): Promise<CreatedCustomPlan> {
  const quote = await customPlanQuote(spec);
  if (!quote.ok) throw new CustomPlanError(quote.reason);
  const cap = await customPlanCapacityCheck(spec);
  if (!cap.ok) throw new CustomPlanCapacityError(cap.reason ?? CUSTOM_PLAN_NEEDS_SALES_REASON);
  return createCustomPlanRow(spec, quote.priceCents, quote.floor.bandwidthTB, quote.introPriceCents);
}

export type CreatedCustomGamePlan = {
  plan: CreatedCustomPlan;
  gamePlanId: string;
  name: string;
  priceCents: number;
  /** The TIER's first-term price, or null. This is the one gameOrderQuote reads. */
  introPriceCents: number | null;
  slots: number | null;
};

/**
 * Game analogue of `createCustomPlan`: also creates the `GamePlan` tier that rides on
 * top of the freshly-created base `Plan`, exactly like every premade game tier
 * already does (`GamePlan.basePlanId`) — see prisma/seed-gameplans.ts.
 *
 * REAL per-family pricing (2026-09-29, replacing the stop-gap throw that blocked
 * every custom game order — see docs/DOCUMENTATION.md). Unlike `createCustomPlan`,
 * the price here is NOT floor.priceCents + flat-VPS-rate * extra: it's this game
 * family's own top real `GamePlan` tier's price, extended by that family's own
 * per-vCPU/per-RAM-GB rate (lib/custom-plan-pricing.ts's
 * `computeCustomGamePlanPriceCents` — read its derivation comment for the full
 * methodology) — so a custom build is a genuine continuation of THIS game's own
 * pricing curve, not the platform's generic VPS curve wearing a game's name. The
 * floor a spec must clear is similarly widened per-family (`gameCustomFloor`) so a
 * "custom" order can never be smaller, on any dimension, than this family's own
 * biggest premade tier.
 *
 * Still gated (throws) for a family with ZERO live tiers to anchor from at all —
 * see `customGamePlanRates`'s doc and lib/custom-plan-pricing.ts's derivation
 * comment for exactly which families that is and why (as of 2026-09-29:
 * `schedule1` and the four `plutonium*` variants — none of which can be bought as a
 * premade tier either today, so this changes nothing about their sellability).
 */
export async function createCustomGamePlan(opts: {
  spec: CustomPlanSpec;
  gameFamily: string;
  players?: number | null;
}): Promise<CreatedCustomGamePlan> {
  // Same quote→place split every other money path in this codebase uses (see
  // createCustomPlan/customPlanQuote above) — one function computes the price,
  // both the read-only quote (customGamePlanQuote, called by the wizard while a
  // customer is still moving sliders) and this real write path call it, so they
  // can never independently drift from each other.
  const quote = await customGamePlanQuote(opts.gameFamily, opts.spec);
  if (!quote.ok) throw new CustomPlanError(quote.reason);
  const cap = await customPlanCapacityCheck(opts.spec);
  if (!cap.ok) throw new CustomPlanCapacityError(cap.reason ?? CUSTOM_PLAN_NEEDS_SALES_REASON);

  const plan = await createCustomPlanRow(opts.spec, quote.priceCents, quote.floor.bandwidthTB, null);
  const gp = await db.gamePlan.create({
    data: {
      gameFamily: opts.gameFamily,
      name: `${customPlanName(opts.spec)} (${opts.gameFamily})`,
      ramMB: plan.ramMB,
      cpuCores: plan.cpuCores,
      diskGB: plan.diskGB,
      slots: opts.players ?? null,
      priceCents: plan.priceCents,
      // Per-term units, like priceCents. termMonths is 1, so this is monthly.
      introPriceCents: quote.introPriceCents,
      introTermMonths: null,
      termMonths: 1,
      basePlanId: plan.id,
      active: false,
      sortOrder: CUSTOM_PLAN_SORT_ORDER,
    },
  });
  return {
    plan,
    gamePlanId: gp.id,
    name: gp.name,
    priceCents: gp.priceCents,
    introPriceCents: gp.introPriceCents ?? null,
    slots: gp.slots,
  };
}

