export function renewalCharge(
  server: PricedServer,
  prices: RenewalPrices,
): RenewalCharge {
  const isGame = !!server.gamePlan;
  const months = isGame ? Math.max(1, Math.round(server.termMonths)) : vpsTerm(server.termMonths).months;
  const annualPct = server.annualDiscountPct ?? prices.annualDiscountPct;
  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
  const extraDiskCents = extraDiskMonthlyCents * months;
  const backupMonthlyCents = isGame ? 0 : backupTierMonthlyCents(server.backupTier, prices.backupPlusCents);
  const backupCents = backupMonthlyCents * months;
  const grandfatheredPriceCents = server.grandfatheredRenewalCents ?? null;
  const gameMonthlyCents = isGame
    ? Math.round((grandfatheredPriceCents ?? server.gamePlan!.priceCents) / Math.max(1, server.gamePlan!.termMonths))
    : 0;
  const gameTotalCents = !isGame
    ? 0
    : server.annualDiscountPct == null
      ? (grandfatheredPriceCents ?? server.gamePlan!.priceCents)
      : termPriceCents(gameMonthlyCents, months, annualPct);
  const dedicatedIpBillable = !!server.dedicatedIp && server.wantsDedicatedIp;
  const ipCents = dedicatedIpBillable ? prices.ipMonthlyCents * months : 0;
  const preRetentionNetCents = isGame
    ? gameTotalCents + ipCents
    : vpsTermPriceCents(grandfatheredPriceCents ?? server.plan.priceCents, months, annualPct) +
      ipCents +
      extraDiskCents +
      backupCents;
  const pendingDiscountPercent = Math.max(0, Math.min(100, server.pendingRenewalDiscountPercent ?? 0));
  const retentionDiscountCents =
    pendingDiscountPercent > 0 ? Math.round((preRetentionNetCents * pendingDiscountPercent) / 100) : 0;
  const afterRetentionCents = preRetentionNetCents - retentionDiscountCents;
  const partnerDiscountPercent = Math.max(0, Math.min(100, prices.partnerDiscountPercent ?? 0));
  const partnerDiscountCents = partnerDiscountCentsFor(afterRetentionCents, partnerDiscountPercent);
  const netCents = afterRetentionCents - partnerDiscountCents;
  const taxRatePercent =
    Number.isFinite(prices.taxRatePercent) && (prices.taxRatePercent ?? 0) > 0 ? prices.taxRatePercent! : 0;
  const taxCents = Math.round((netCents * taxRatePercent) / 100);
  return {
    months,
    netCents,
    taxCents,
    taxRatePercent,
    totalCents: netCents + taxCents,
    extraDiskCents,
    extraDiskMonthlyCents,
    ipCents,
    partnerDiscountCents,
    partnerDiscountPercent,
    backupCents,
    backupMonthlyCents,
    retentionDiscountCents,
    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
  };
}

