export type TaxContext = {
  /** The rate actually applied to the net, in percent. */
  ratePercent: number;
  /** The destination country the rate was resolved for ("" when unknown). */
  country: string;
  /** True when a valid EU cross-border VAT id zero-rated this as a reverse charge. */
  reverseCharged: boolean;
};

/**
 * Resolve the VAT/GST rate to CHARGE for a customer, from their billing country and
 * (optional) VAT id. Pure decision logic — the seller country and the global
 * fallback rate are passed in so this stays testable and callers resolve settings
 * once.
 *
 *   1. Unknown country                       → the global `tax_percent` fallback.
 *   2. Valid VAT id, EU country ≠ seller EU  → 0% (standard B2B reverse charge).
 *   3. Known country in the rate table       → that country's standard rate.
 *   4. Known country, no table entry         → the global `tax_percent` fallback.
 *
 * "When in doubt, charge the destination-country consumer rate" — a malformed VAT id
 * never reaches case 2 (isValidVatIdFormat gates it), so it lands on case 3.
 */
export function resolveCountryTaxRate(opts: {
  country: string | null | undefined;
  vatId?: string | null;
  sellerCountry: string;
  fallbackPercent: number;
}): TaxContext {
  const country = normalizeCountry(opts.country);
  const fallback = Number.isFinite(opts.fallbackPercent) && opts.fallbackPercent > 0 ? opts.fallbackPercent : 0;
  if (!country) return { ratePercent: fallback, country: "", reverseCharged: false };

  // B2B reverse charge: a VAT-registered business in a DIFFERENT EU country pays 0%
  // and self-accounts for the VAT. Same-country B2B is still charged local VAT.
  const seller = normalizeCountry(opts.sellerCountry);
  if (
    EU_COUNTRIES.has(country) &&
    country !== seller &&
    isValidVatIdFormat(opts.vatId, country)
  ) {
    return { ratePercent: 0, country, reverseCharged: true };
  }

  const table = COUNTRY_VAT_RATES[country];
  if (typeof table === "number") return { ratePercent: table, country, reverseCharged: false };
  return { ratePercent: fallback, country, reverseCharged: false };
}

/**
 * Resolve the tax context for a specific customer (reads seller country + the global
 * fallback rate from Settings once). The single async entry point every charge site
 * uses so the rate is derived identically everywhere.
 */
export async function taxContextForUser(
  user: { billingCountry?: string | null; vatId?: string | null },
): Promise<TaxContext> {
  const [seller, fallback] = await Promise.all([sellerCountry(), taxRate()]);
  return resolveCountryTaxRate({
    country: user.billingCountry ?? null,
    vatId: user.vatId ?? null,
    sellerCountry: seller,
    fallbackPercent: fallback,
  });
}

/** The tax in cents to ADD to a net service charge at a resolved rate. Integer cents. */
export function taxCentsFor(netCents: number, ctx: Pick<TaxContext, "ratePercent">): number {
  return applyTax(netCents, ctx.ratePercent).tax;
}
