    if (!taken) return candidate;
    candidate = `${base}-${randHostnameSuffix(4)}`;
  }
  // Last resort after 6 straight collisions (astronomically unlikely) — a
  // millisecond-timestamp tail that cannot repeat within this process.
  return `${base}-${Date.now().toString(36)}`;
}
