// ---------------------------------------------------------------------------
// CUSTOM OFFERS (2026-10-06) — a staff-built, priced quote for one customer
// (VPS, game server or dedicated server) that the customer reviews and
// accepts/pays from the portal. Replaces the hand-run flow (top up wallet by
// hand, hand-insert Plan + Server + PROVISION job, hand-debit wallet, hand-write
// the invoice) with one auditable money path: lib/offers.ts (draft/send/cancel),
// lib/offer-pricing.ts (pure pricing + snapshot + transitions),
// lib/offer-fulfil.ts (the single idempotent fulfilment). ADDITIVE ONLY: no
// existing model gains a column or relation (FK-less string ids, like
// NodeAlert), so `prisma db push` adds three tables and two enums and touches
// nothing else.
// ---------------------------------------------------------------------------
enum OfferKind {
  VPS
  GAME
  DEDICATED
}

enum OfferStatus {
  DRAFT
  SENT
  VIEWED
  ACCEPTED // customer opened payment; card leg pending (wallet-only offers go straight to PAID)
  PAID
  EXPIRED
  CANCELLED
  DECLINED
}

model Offer {
  id                  String      @id @default(cuid())
  /// Human reference ("Offer #12"), shown in chat, emails and the admin list.
  number              Int         @unique @default(autoincrement())
  /// The customer account the offer is FOR. Always set: an offer can only be
  /// accepted by this account (lib/offers.ts getOfferForViewer).
  userId              String
  /// The live-chat thread it was sent from, if any (null when sent from the
  /// admin customer page).
  conversationId      String?
  kind                OfferKind
  status              OfferStatus @default(DRAFT)
  title               String

  // ---- Spec (editable while DRAFT; frozen into `terms` at send) ----
  cpuCores            Int         @default(0)
  ramMB               Int         @default(0)
  diskGB              Int         @default(0)
  storageTier         String      @default("nvme") // nvme | hdd
  bandwidthTB         Float       @default(0)
  /// VPS image. Null = platform default (Ubuntu 24.04) resolved at fulfilment.
  osTemplateId        String?
  /// GAME only: family/variant + the catalog GamePlan the price was based on.
  gameFamily          String?
  gameVariant         String?
  gamePlanBasisId     String?
  slots               Int?
  /// VPS only: the catalog Plan the price was compared against (display only).
  basePlanId          String?
  /// Staff-pinned node (honoured exactly at fulfilment) or a region preference.
  nodeId              String?
  region              String?
  /// Extras as typed flags. cpuPriority / cpuPinning are NOT automated (need
  /// host access) — fulfilment opens an OfferTask for each, never drops them.
  cpuPriority         Boolean     @default(false)
  cpuPinning          Boolean     @default(false)
  /// Billed at the platform dedicated-IP rate (own invoice line, like a catalog order).
  dedicatedIp         Boolean     @default(false)
  /// Preferred hostname (resolved unique at fulfilment).
  hostname            String?
  /// Customer-visible notes (shown on the offer).
  notes               String      @default("")
  /// Staff-only note (never shown to the customer).
  internalNote        String      @default("")

  // ---- Pricing (USD cents) ----
  /// Total for the WHOLE first term of the base service (excl. setup fee + IP).
  firstTermCents      Int         @default(0)
  /// Per-month price every renewal bills (stored as Server.grandfatheredRenewalCents).
  renewalMonthlyCents Int         @default(0)
  termMonths          Int         @default(1) // 1 | 12
  setupFeeCents       Int         @default(0)
  discountLabel       String?
  discountPercent     Float?
  currency            String      @default("USD")

  // ---- Snapshot (what the customer is shown and what fulfilment bills) ----
  /// Frozen JSON of every field above + computed totals, written ONCE at send.
  /// Fulfilment reads ONLY this, never the live columns, so an edit after send
  /// can't change what the customer accepted.
  terms               Json?
  /// sha256 of `terms`, stamped on accept and re-checked at fulfilment.
  termsHash           String?

  // ---- Lifecycle ----
  expiresAt           DateTime?
  sentAt              DateTime?
  viewedAt            DateTime?
  acceptedAt          DateTime?
  paidAt              DateTime?
  cancelledAt         DateTime?
  declinedAt          DateTime?
  createdById         String
  sentById            String?
  cancelledById       String?
  cancelReason        String?
  /// Last Stripe Checkout session opened for the card leg (reused while open).
  checkoutSessionId   String?
  /// Set when a PAID-but-unfulfilled attempt failed; money stays in the wallet.
  fulfilError         String?

  // ---- Result ----
  serverId            String?     @unique
  invoiceId           String?     @unique
  planId              String?
  gamePlanId          String?

  createdAt           DateTime    @default(now())
  updatedAt           DateTime    @updatedAt
  events              OfferEvent[]
  tasks               OfferTask[]

  @@index([userId, createdAt])
  @@index([status, expiresAt])
  @@index([conversationId])
}

/// Append-only audit trail for one offer (created/sent/viewed/accepted/paid/...).
model OfferEvent {
  id        String   @id @default(cuid())
  offerId   String
  offer     Offer    @relation(fields: [offerId], references: [id], onDelete: Cascade)
  action    String
  actorId   String?
  detail    String?
  createdAt DateTime @default(now())

  @@index([offerId, createdAt])
}

/// A manual follow-up fulfilment could not do automatically (CPU pinning/priority,
/// dedicated-server build, a paid offer that failed to fulfil). Shown on
/// /admin/offers until a staff member marks it done.
model OfferTask {
  id        String    @id @default(cuid())
  offerId   String
  offer     Offer     @relation(fields: [offerId], references: [id], onDelete: Cascade)
  serverId  String?
  kind      String // CPU_PRIORITY | CPU_PINNING | DEDICATED_BUILD | FULFIL_FAILED | NOTE
  title     String
  detail    String    @default("")
  status    String    @default("OPEN") // OPEN | DONE
  doneById  String?
  doneAt    DateTime?
  createdAt DateTime  @default(now())

  @@index([status, createdAt])
  @@index([offerId])
}
EOF
