        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span className="flex flex-wrap items-center gap-2">
            <span className="text-[13px] font-extrabold text-tx">Dedicated IPv4</span>
          </span>
          <span className="text-[11.5px] leading-relaxed text-tx-dim">
            Your own public IP instead of shared NAT — every port reachable directly, no forwarding.
          </span>
        </div>
        <span className="num flex-none text-[12.5px] font-bold text-tx">
          {fmtMoney(monthlyCents)}
          <span className="text-[10px] font-normal text-tx-faint">/mo</span>
        </span>
      </div>

      {error && (
        <div className="mt-3 rounded-[10px] border border-red-500/30 bg-red-500/10 px-3 py-2 text-[12px] text-red-300">
          {error}
