      <div className="mt-3 flex flex-col gap-2.5 border-t border-rim-soft pt-3">
        {prorate > 0 && walletBalanceCents > 0 && (
          <label className="flex items-center justify-between gap-3 text-[12px] text-tx-dim">
            <span className="flex items-center gap-2">
              <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
              Apply my balance ({fmtMoney(walletBalanceCents)})
            </span>
            <span className="text-tx-faint">{useWallet ? "applied" : "off"}</span>
          </label>
