  if (!int(i.renewalMonthlyCents) || i.renewalMonthlyCents < 100) e.push("Renewal price must be at least $1.00/mo.");
  if (i.renewalMonthlyCents > 10_000_00) e.push("Renewal price is over $10,000/mo — check the number.");
  if (!int(i.firstTermCents) || i.firstTermCents < 0) e.push("First-term price must be $0.00 or more.");
  else if (isOfferTerm(i.termMonths) && i.firstTermCents > i.renewalMonthlyCents * i.termMonths) {
    e.push("First-term price can't be higher than the regular price for the term.");
  }
  if (!int(i.setupFeeCents) || i.setupFeeCents < 0 || i.setupFeeCents > 10_000_00) e.push("Setup fee must be $0–$10,000.");
  if (i.discountPercent != null && !(i.discountPercent >= 0 && i.discountPercent <= 100)) e.push("Discount must be 0–100%.");
  if ((i.discountLabel ?? "").length > 80) e.push("Discount label is too long.");
  if (!int(i.expiresInDays) || i.expiresInDays < 1 || i.expiresInDays > OFFER_MAX_EXPIRY_DAYS) {
    e.push(`Expiry must be 1–${OFFER_MAX_EXPIRY_DAYS} days.`);
  }
  if ((i.notes ?? "").length > 2000) e.push("Customer notes are too long (2000 max).");
  if ((i.internalNote ?? "").length > 2000) e.push("Internal note is too long (2000 max).");
  const h = (i.hostname ?? "").trim();
  if (h && !/^[a-z0-9]([a-z0-9-]{1,38}[a-z0-9])$/i.test(h)) e.push("Hostname: 3–40 letters, digits or hyphens.");
  if (i.slots != null && (!int(i.slots) || i.slots < 1 || i.slots > 1000)) e.push("Player slots must be 1–1000.");
  return e;
}

/** Deterministic JSON (sorted keys) — the input to the terms hash. */
export function stableStringify(v: unknown): string {
  if (v === null || typeof v !== "object") return JSON.stringify(v);
  if (Array.isArray(v)) return `[${v.map(stableStringify).join(",")}]`;
  const o = v as Record<string, unknown>;
  return `{${Object.keys(o)
    .sort()
    .filter((k) => o[k] !== undefined)
    .map((k) => `${JSON.stringify(k)}:${stableStringify(o[k])}`)
    .join(",")}}`;
}

/** Parse a stored snapshot defensively. Null = untrustworthy: never bill from it. */
export function parseOfferTerms(raw: unknown): OfferTerms | null {
  if (!raw || typeof raw !== "object") return null;
  const t = raw as OfferTerms;
  if (t.v !== 1 || !t.pricing || !t.spec || !t.extras) return null;
  if (!["VPS", "GAME", "DEDICATED"].includes(t.kind)) return null;
  const p = t.pricing;
  const ints = [p.termMonths, p.firstTermCents, p.renewalMonthlyCents, p.setupFeeCents, p.ipMonthlyCents];
  if (!ints.every((n) => Number.isInteger(n) && n >= 0)) return null;
  if (!isOfferTerm(p.termMonths)) return null;
  if (p.firstTermCents > p.renewalMonthlyCents * p.termMonths) return null;
  return t;
}

/* ------------------------------------------------------------------ *
 * Status machine
 * ------------------------------------------------------------------ */

export const OFFER_TRANSITIONS: Record<OfferStatusT, OfferStatusT[]> = {
  DRAFT: ["SENT", "CANCELLED"],
  SENT: ["VIEWED", "ACCEPTED", "PAID", "EXPIRED", "CANCELLED", "DECLINED"],
  VIEWED: ["ACCEPTED", "PAID", "EXPIRED", "CANCELLED", "DECLINED"],
  ACCEPTED: ["PAID", "EXPIRED", "CANCELLED", "DECLINED"],
  PAID: [],
  EXPIRED: [],
  CANCELLED: [],
  DECLINED: [],
};

export function canTransition(from: OfferStatusT, to: OfferStatusT): boolean {
  return OFFER_TRANSITIONS[from]?.includes(to) ?? false;
}

/** Statuses fulfilment may move to PAID from (the CAS in lib/offer-fulfil.ts uses exactly these). */
export const OFFER_PAYABLE_FROM: OfferStatusT[] = ["SENT", "VIEWED", "ACCEPTED"];

/**
 * The status to SHOW / act on, with expiry applied lazily (no cron needed for
 * correctness). SENT/VIEWED expire at `expiresAt`; an ACCEPTED offer (payment in
 * flight) gets OFFER_PAYMENT_GRACE_MS more.
 */
export function effectiveOfferStatus(
  o: { status: OfferStatusT; expiresAt: Date | string | null },
  now: Date = new Date(),
): OfferStatusT {
  if (!o.expiresAt) return o.status;
  const exp = new Date(o.expiresAt).getTime();
  if ((o.status === "SENT" || o.status === "VIEWED") && now.getTime() >= exp) return "EXPIRED";
  if (o.status === "ACCEPTED" && now.getTime() >= exp + OFFER_PAYMENT_GRACE_MS) return "EXPIRED";
  return o.status;
}

/** May the customer START paying now (press Accept & Pay)? Strictly before expiry. */
export function canStartPayment(o: { status: OfferStatusT; expiresAt: Date | string | null }, now = new Date()): boolean {
  if (!OFFER_PAYABLE_FROM.includes(o.status)) return false;
  if (!o.expiresAt) return false;
  return now.getTime() < new Date(o.expiresAt).getTime();
}

/**
 * May a payment that has ALREADY cleared be fulfilled? Wallet path = same as
 * starting. Card path = accepted before expiry and within the grace window.
 */
export function canFulfilPayment(
  o: { status: OfferStatusT; expiresAt: Date | string | null; acceptedAt: Date | string | null },
  via: "wallet" | "card",
  now = new Date(),
): boolean {
  if (via === "wallet") return canStartPayment(o, now);
  if (!OFFER_PAYABLE_FROM.includes(o.status) || !o.expiresAt) return false;
  const exp = new Date(o.expiresAt).getTime();
  const accepted = o.acceptedAt ? new Date(o.acceptedAt).getTime() : null;
  if (accepted === null || accepted >= exp) return false;
  return now.getTime() < exp + OFFER_PAYMENT_GRACE_MS;
}

/* ------------------------------------------------------------------ *
 * Display + invoice
 * ------------------------------------------------------------------ */

export function money(cents: number): string {
  const neg = cents < 0;
  const v = Math.abs(cents) / 100;
  return `${neg ? "-" : ""}$${v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

export function termLabel(months: number): string {
  return months === 12 ? "Annual" : months === 1 ? "Monthly" : `${months} months`;
}

export function kindLabel(kind: OfferKindT): string {
  return kind === "VPS" ? "VPS" : kind === "GAME" ? "Game server" : "Dedicated server";
}

function gb(mb: number): string {
  const g = mb / 1024;
  return Number.isInteger(g) ? `${g}` : g.toFixed(1);
}

/** Human spec lines — the offer page, the chat card and the invoice sub-lines all use these. */
export function offerSpecLines(t: Pick<OfferTerms, "kind" | "spec" | "extras">): string[] {
  const s = t.spec;
  const lines: string[] = [];
  const disk = `${s.diskGB} GB ${s.storageTier === "hdd" ? "HDD" : "NVMe"}`;
  if (t.kind === "DEDICATED") {
    const parts = [s.cpuCores ? `${s.cpuCores} cores` : null, s.ramMB ? `${gb(s.ramMB)} GB RAM` : null, s.diskGB ? disk : null].filter(Boolean);
    if (parts.length) lines.push(parts.join(" · "));
  } else {
    lines.push(`${s.cpuCores} vCPU · ${gb(s.ramMB)} GB RAM · ${disk}`);
  }
  if (s.bandwidthTB > 0) lines.push(`${s.bandwidthTB} TB bandwidth`);
  if (t.kind === "GAME" && (s.gameFamilyName || s.gameFamily)) {
    lines.push(`${s.gameFamilyName ?? s.gameFamily}${s.gameVariant ? ` (${s.gameVariant})` : ""}${s.slots ? ` · ${s.slots} player slots` : ""}`);
  }
  if (t.kind === "VPS" && s.osName) lines.push(s.osName);
  if (s.region) lines.push(`Location: ${s.region}`);
  if (t.extras.cpuPinning) lines.push("Dedicated (pinned) CPU cores");
  if (t.extras.cpuPriority) lines.push("CPU priority scheduling");
  if (t.extras.dedicatedIp && t.kind !== "DEDICATED") lines.push("Dedicated IPv4 address");
  return lines;
}

export type OfferLineItem = { description: string; qty: number; unitCents: number; amountCents: number };

/**
 * Invoice line items for the first payment. First line of each description is the
 * title, following lines are spec sub-lines (lib/invoices.ts invoiceDescriptionLines).
 * Lines always sum to `offerTotals(t).dueNowNetCents`.
 */
export function offerInvoiceLines(t: OfferTerms, hostname?: string | null): OfferLineItem[] {
  const tot = offerTotals(t);
  const p = t.pricing;
  const head = `${t.title}${hostname ? ` (${hostname})` : ""} — ${termLabel(p.termMonths)}`;
  const sub = offerSpecLines({ ...t, extras: { ...t.extras, dedicatedIp: false } });
  const regular = p.renewalMonthlyCents * p.termMonths;
  if (p.firstTermCents < regular) {
    const pct = tot.termPromoPercent;
    sub.push(`${p.discountLabel?.trim() || "Offer discount"}: ${money(p.firstTermCents)} instead of ${money(regular)}${pct > 0 ? ` (${pct}% off)` : ""}`);
  }
  sub.push(`Renews at ${money(p.renewalMonthlyCents)}/mo · Offer #${t.number}`);
  const lines: OfferLineItem[] = [
    { description: [head, ...sub].join("\n"), qty: 1, unitCents: p.firstTermCents, amountCents: p.firstTermCents },
  ];
  if (p.setupFeeCents > 0) {
    lines.push({ description: "One-time setup fee", qty: 1, unitCents: p.setupFeeCents, amountCents: p.setupFeeCents });
  }
  if (tot.ipTermCents > 0) {
    lines.push({
      description: `Dedicated IP — ${termLabel(p.termMonths)}\n${money(p.ipMonthlyCents)}/mo, renews with the server`,
      qty: 1,
      unitCents: tot.ipTermCents,
      amountCents: tot.ipTermCents,
    });
  }
  return lines;
}

/* ------------------------------------------------------------------ *
 * Staff-only economics
 * ------------------------------------------------------------------ */

export type OfferMargin = {
  /** This offer's share of the node's monthly cost, pro-rata by RAM. */
  costShareCents: number;
  marginCents: number;
  marginPercent: number;
};

/**
 * Margin vs the node's real monthly cost, apportioned by RAM (the resource every
 * node is capacity-planned on — Node.capacityRamMB). Null when the node has no
 * recorded cost. Staff-only: never part of OfferTerms.
 */
export function offerMargin(
  renewalMonthlyCents: number,
  ramMB: number,
  node: { monthlyCostCents: number | null; capacityRamMB: number } | null,
): OfferMargin | null {
  if (!node || !node.monthlyCostCents || node.capacityRamMB <= 0 || ramMB <= 0) return null;
  const costShareCents = Math.round((node.monthlyCostCents * ramMB) / node.capacityRamMB);
  const marginCents = renewalMonthlyCents - costShareCents;
  const marginPercent = renewalMonthlyCents > 0 ? Math.round((marginCents / renewalMonthlyCents) * 1000) / 10 : 0;
  return { costShareCents, marginCents, marginPercent };
}

/** The chat card payload (ChatMessage.cardsJson is a JSON array of typed cards). */
export function offerChatCard(offerId: string): { type: "offer"; key: string; offerId: string } {
  return { type: "offer", key: `offer:${offerId}`, offerId };
}

