// CUSTOM OFFERS — the ONE fulfilment path. Plain server module (not "use server"):
// called by the customer's wallet-funded accept (lib/actions-offers.ts) and by the
// Stripe card leg (lib/fulfil-checkout.ts, webhook AND return redirect), never
// exported to the network directly.
//
// IDEMPOTENCY / RACES — what makes "never double-provision, never double-charge" true:
//  1. The status CAS `Offer: SENT|VIEWED|ACCEPTED -> PAID` runs INSIDE the same
//     transaction as the wallet debit, the Plan/Server/Invoice/Job writes. Under
//     Postgres READ COMMITTED a second concurrent caller blocks on the row lock,
//     re-evaluates the WHERE after the first commits, matches 0 rows and throws
//     before debiting anything. Any later caller sees PAID and returns `already`.
//  2. The card leg is credited into the wallet exactly once by
//     creditCheckoutSession (UNIQUE WalletTransaction.stripeSessionId) and the
//     FulfilledSession claim (UNIQUE) lets only one of webhook/redirect call here.
//     Even if both did, (1) still holds.
//  3. Anything that fails (expired, cancelled, wallet spent elsewhere, no capacity)
//     rolls the whole transaction back: no debit, no rows. On the card path the
//     money is already in the wallet as a normal credit — never lost — and the
//     customer + staff are told (fulfilError, notification, OfferTask).
//  4. Billing is computed ONLY from the frozen `terms` snapshot, whose sha256 must
//     still match `termsHash`; the live editable columns are never read for money.
import { createHash } from "node:crypto";
import { Prisma, type User } from "@prisma/client";
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { addMonths } from "./billing-terms";
import { invoiceCreateData, invoiceBranding, formatInvoiceNumber } from "./invoices";
import { taxContextForUser } from "./tax";
import { capacityCheckRamMB, diskCapacityCheck } from "./capacity";
import { placeInRegion } from "./region-placement";
import { resolveUniqueHostname, isHostnameConflict } from "./hostname";
import { schemaFor, isValidVariant, isSelectableVariant, validateConfig } from "./game-config";
import { hardMinDiskGB } from "./game-image-footprint";
import { CUSTOM_PLAN_SORT_ORDER } from "./custom-plan-pricing";
import {
  type OfferTerms,
  type OfferStatusT,
  OFFER_PAYABLE_FROM,
  canFulfilPayment,
  offerInvoiceLines,
  offerTotals,
  parseOfferTerms,
  stableStringify,
  taxOn,
  kindLabel,
  money,
} from "./offer-pricing";

export class OfferError extends Error {}

export function hashOfferTerms(terms: OfferTerms): string {
  return createHash("sha256").update(stableStringify(terms)).digest("hex");
}

/** Families an offer can't provision without a customer-supplied secret at checkout. */
export const OFFER_UNSUPPORTED_GAME_FAMILIES = new Set(["fivem"]);

export type OfferPlacement = {
  nodeId: string | null;
  nodeName: string | null;
  osTemplateId: string | null;
  gameVariant: string | null;
  gameConfig: Record<string, string | number | boolean> | null;
};

/**
 * Resolve everything a VPS/GAME offer needs to become a server WITHOUT writing
 * anything: image, game variant/config, node (staff-pinned or region placement)
 * and the capacity guards every catalog order runs. Called before the customer is
 * charged (accept) and again inside fulfilment. DEDICATED resolves to nothing.
 */
export async function resolveOfferPlacement(terms: OfferTerms, userId: string): Promise<OfferPlacement> {
  const none: OfferPlacement = { nodeId: null, nodeName: null, osTemplateId: null, gameVariant: null, gameConfig: null };
  if (terms.kind === "DEDICATED") return none;
  const s = terms.spec;

  // Image.
  let osTemplateId: string | null = null;
  let templateVmid: number | null = null;
  if (terms.kind === "VPS") {
    const os = s.osTemplateId
      ? await db.osTemplate.findFirst({ where: { id: s.osTemplateId, active: true } })
      : await db.osTemplate.findFirst({ where: { slug: "ubuntu-24-04", active: true } });
    if (!os) throw new OfferError("The operating system on this offer is no longer available — please contact us so we can update it.");
    if (s.ramMB < os.minRamMB || s.diskGB < os.minDiskGB) throw new OfferError("This offer's size is below the image's minimum — please contact us.");
    osTemplateId = os.id;
    templateVmid = os.baseVmid ?? os.vmid;
  }

  let gameVariant: string | null = null;
  let gameConfig: Record<string, string | number | boolean> | null = null;
  if (terms.kind === "GAME") {
    const family = s.gameFamily ?? "";
    if (OFFER_UNSUPPORTED_GAME_FAMILIES.has(family)) throw new OfferError("This game needs details we collect at checkout — please order it from the deploy page.");
    let os = null;
    if (s.gamePlanBasisId) {
      const gp = await db.gamePlan.findUnique({ where: { id: s.gamePlanBasisId }, select: { osTemplateId: true } });
      if (gp?.osTemplateId) os = await db.osTemplate.findFirst({ where: { id: gp.osTemplateId, active: true } });
    }
    if (!os) {
      os = await db.osTemplate.findFirst({
        where: { family, category: "APPLICATION", active: true },
        orderBy: { sortOrder: "asc" },
      });
    }
    if (!os) throw new OfferError("No game image is configured for this game yet.");
    osTemplateId = os.id;
    templateVmid = os.baseVmid ?? os.vmid;
    const floor = hardMinDiskGB(family, s.ramMB);
    if (floor !== null && s.diskGB < floor) throw new OfferError(`This game needs at least ${floor} GB of disk.`);
    const schema = schemaFor(family);
    if (schema) {
      const variant = (s.gameVariant ?? "").trim() || schema.orderDefaults?.variant || schema.defaultVariant;
      if (!isValidVariant(family, variant) || !isSelectableVariant(family, variant)) {
        throw new OfferError("The server type on this offer isn't available — please contact us.");
      }
      const cfg: Record<string, unknown> = { ...(schema.orderDefaults?.values ?? {}) };
      const res = validateConfig(family, cfg);
      if (!res.ok) throw new OfferError(res.error);
      gameVariant = variant;
      gameConfig = res.values;
    }
  }

  // Node.
  let nodeId: string | null = null;
  let nodeName: string | null = null;
  if (s.nodeId) {
    // Staff pinned a node: honour it exactly (no silent move elsewhere). Its disk
    // pool is still checked; the global RAM guard is skipped because staff chose
    // this node deliberately (that is the point of pinning).
    const n = await db.node.findFirst({ where: { id: s.nodeId, enabled: true } });
    if (!n) throw new OfferError("The server location on this offer isn't available right now — please contact us.");
    nodeId = n.id;
    nodeName = n.name;
  } else {
    const ram = await capacityCheckRamMB(s.ramMB);
    if (!ram.ok) throw new OfferError("We need to confirm capacity for this build — please contact us and we'll sort it out.");
    const placement = await placeInRegion({ ramMB: s.ramMB, templateVmid, region: s.region, userId });
    if (!placement.ok) throw new OfferError(placement.message);
    nodeId = placement.node?.id ?? null;
    nodeName = placement.node?.name ?? null;
  }
  const disk = await diskCapacityCheck(nodeId, s.diskGB);
  if (!disk.ok) throw new OfferError("We need to confirm storage for this build — please contact us and we'll sort it out.");

  return { nodeId, nodeName, osTemplateId, gameVariant, gameConfig };
}

/** Amount due now for a specific customer: snapshot net + their VAT/GST. */
export async function offerAmountDue(
  terms: OfferTerms,
  user: Pick<User, "billingCountry" | "vatId">,
): Promise<{ netCents: number; taxCents: number; taxRatePercent: number; taxCountry: string; grossCents: number; ipTermCents: number }> {
  const tot = offerTotals(terms);
  const ctx = await taxContextForUser(user);
  const taxCents = taxOn(tot.dueNowNetCents, ctx.ratePercent);
  return {
    netCents: tot.dueNowNetCents,
    taxCents,
    taxRatePercent: taxCents > 0 ? ctx.ratePercent : 0,
    taxCountry: ctx.country,
    grossCents: tot.dueNowNetCents + taxCents,
    ipTermCents: tot.ipTermCents,
  };
}

export type FulfilOfferResult =
  | { ok: true; already: boolean; serverId: string | null; invoiceId: string | null }
  | { ok: false; error: string };

/** Load + verify the frozen terms. Throws OfferError when they can't be trusted. */
export function trustedTerms(offer: { id: string; terms: unknown; termsHash: string | null }): OfferTerms {
  const terms = parseOfferTerms(offer.terms);
  if (!terms || terms.offerId !== offer.id) throw new OfferError("This offer's terms are unreadable — please contact us.");
  if (!offer.termsHash || hashOfferTerms(terms) !== offer.termsHash) {
    throw new OfferError("This offer's terms changed after it was sent — please contact us.");
  }
  return terms;
}

async function event(offerId: string, action: string, actorId: string | null, detail?: string) {
  await db.offerEvent.create({ data: { offerId, action, actorId, detail: detail?.slice(0, 1000) } }).catch(() => {});
}

/**
 * Record a fulfilment failure loudly: on the offer, in its audit trail, as an open
 * staff task, and (for the card path, where money has moved) to the customer.
 */
async function recordFailure(offerId: string, userId: string, via: "wallet" | "card", msg: string) {
  await db.offer.update({ where: { id: offerId }, data: { fulfilError: msg.slice(0, 500) } }).catch(() => {});
  await event(offerId, "fulfil_failed", userId, `${via}: ${msg}`);
  if (via === "card") {
    await db.offerTask
      .create({
        data: {
          offerId,
          kind: "FULFIL_FAILED",
          title: "Paid offer could not be fulfilled",
          detail: `The card payment cleared and is sitting in the customer's wallet, but the offer could not be placed: ${msg}`.slice(0, 1000),
        },
      })
      .catch(() => {});
    await db.notification
      .create({
        data: {
          userId,
          title: "Payment received — we're finishing your offer by hand",
          body: "Your payment is safe in your Nxeon wallet. Our team has been alerted and will complete your order or follow up with you.",
          href: `/dashboard/offers/${offerId}`,
        },
      })
      .catch(() => {});
  }
}

/**
 * Turn a paid (or wallet-covered) offer into real things, exactly once.
 *
 *  via "wallet": the customer's balance covers the gross; nothing has moved yet.
 *  via "card":   the card leg was just credited into the wallet; `sold` carries the
 *                gross/tax the checkout was opened for (never re-priced afterwards).
 */
export async function fulfilOffer(opts: {
  offerId: string;
  userId: string;
  via: "wallet" | "card";
  sold?: { grossCents: number; taxCents: number } | null;
  stripeSessionId?: string | null;
  now?: Date;
}): Promise<FulfilOfferResult> {
  const now = opts.now ?? new Date();
  const offer = await db.offer.findUnique({ where: { id: opts.offerId } });
  if (!offer || offer.userId !== opts.userId) return { ok: false, error: "Offer not found." };
  if (offer.status === "PAID") return { ok: true, already: true, serverId: offer.serverId, invoiceId: offer.invoiceId };

  const fail = async (msg: string): Promise<FulfilOfferResult> => {
    await recordFailure(offer.id, offer.userId, opts.via, msg);
    return { ok: false, error: msg };
  };

  if (!canFulfilPayment({ status: offer.status as OfferStatusT, expiresAt: offer.expiresAt, acceptedAt: offer.acceptedAt }, opts.via, now)) {
    const why =
      offer.status === "CANCELLED" ? "This offer was withdrawn." :
      offer.status === "DECLINED" ? "This offer was declined." :
      "This offer has expired.";
    return fail(why);
  }

  let terms: OfferTerms;
  try {
    terms = trustedTerms(offer);
  } catch (e) {
    return fail((e as Error).message);
  }

  const user = await db.user.findUnique({ where: { id: offer.userId } });
  if (!user) return fail("Customer account not found.");

  const due = await offerAmountDue(terms, user);
  // Card path: settle exactly what the checkout was opened for. The NET must still
  // be the snapshot's net (the only thing that can legitimately differ is tax, if
  // the customer changed billing country mid-checkout — we keep what they paid).
  let grossCents = due.grossCents;
  let taxCents = due.taxCents;
  if (opts.via === "card" && opts.sold) {
    if (opts.sold.grossCents - opts.sold.taxCents !== due.netCents) {
      return fail("The amount paid doesn't match the offer — our team will reconcile it.");
    }
    grossCents = opts.sold.grossCents;
    taxCents = opts.sold.taxCents;
  }
  const taxRatePercent = due.netCents > 0 && taxCents > 0 ? Math.round((taxCents / due.netCents) * 1e6) / 1e4 : 0;

  let placement: OfferPlacement;
  try {
    placement = await resolveOfferPlacement(terms, user.id);
  } catch (e) {
    return fail(e instanceof OfferError ? e.message : String((e as Error)?.message ?? e));
  }

  const isServer = terms.kind !== "DEDICATED";
  const hostname = isServer
    ? await resolveUniqueHostname(terms.spec.hostname ?? "", terms.kind === "GAME" ? terms.spec.gameFamily || "game" : "vps")
    : null;
  const tot = offerTotals(terms);
  const lines = offerInvoiceLines(terms, hostname);
  const months = terms.pricing.termMonths;

  let result: { serverId: string | null; invoiceId: string; invoiceNumber: number; amountCents: number; description: string };
  try {
    result = await db.$transaction(async (tx) => {
      // (1) THE claim — see the file header. Nothing below runs unless this flips.
      const claimed = await tx.offer.updateMany({
        where: { id: offer.id, status: { in: OFFER_PAYABLE_FROM }, termsHash: offer.termsHash },
        data: { status: "PAID", paidAt: now, fulfilError: null, acceptedAt: offer.acceptedAt ?? now },
      });
      if (claimed.count !== 1) throw new OfferError("ALREADY_HANDLED");

      // (2) Money: one debit of the gross, one ledger row.
      await debitWallet(tx, user.id, grossCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -grossCents,
          description: `Offer #${terms.number}: ${terms.title}${hostname ? ` (${hostname})` : ""}`.slice(0, 250),
        },
      });

      // (3) Billing document — itemised, multi-line, created PAID inside the debit tx.
      const description = `${terms.title}${hostname ? ` (${hostname})` : ""} — ${kindLabel(terms.kind)} offer #${terms.number}`;
      const invoice = await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description,
          status: "PAID",
          taxCents,
          taxRatePercent,
          taxCountry: due.taxCountry || null,
          dedicatedIpCents: tot.ipTermCents,
          period: { start: now, end: addMonths(now, months) },
          lineItems: lines,
        }),
      });

      let serverId: string | null = null;
      let planId: string | null = null;
      let gamePlanId: string | null = null;
      if (isServer) {
        const s = terms.spec;
        const suffix = Math.random().toString(36).slice(2, 8);
        const plan = await tx.plan.create({
          data: {
            slug: `offer-${terms.number}-${suffix}`.slice(0, 30),
            name: `${terms.title} (offer #${terms.number})`.slice(0, 120),
            cpuCores: s.cpuCores,
            ramMB: s.ramMB,
            diskGB: s.diskGB,
            bandwidthTB: s.bandwidthTB,
            // Plan.priceCents = the per-month regular rate, so proration on a later
            // resize prices against what the customer actually renews at.
            priceCents: terms.pricing.renewalMonthlyCents,
            introPriceCents: null,
            introTermMonths: null,
            storageTier: s.storageTier,
            active: false,
            sortOrder: CUSTOM_PLAN_SORT_ORDER,
          },
        });
        planId = plan.id;
        if (terms.kind === "GAME") {
          const gp = await tx.gamePlan.create({
            data: {
              gameFamily: s.gameFamily!,
              name: `${terms.title} (offer #${terms.number})`.slice(0, 120),
              ramMB: s.ramMB,
              cpuCores: s.cpuCores,
              diskGB: s.diskGB,
              slots: s.slots,
              priceCents: terms.pricing.renewalMonthlyCents,
              termMonths: 1,
              basePlanId: plan.id,
              osTemplateId: placement.osTemplateId,
              active: false,
              sortOrder: CUSTOM_PLAN_SORT_ORDER,
            },
          });
          gamePlanId = gp.id;
        }
        const server = await tx.server.create({
          data: {
            name: hostname!,
            hostname: hostname!,
            label: terms.kind === "GAME" ? terms.title.slice(0, 60) : null,
            userId: user.id,
            planId: plan.id,
            gamePlanId,
            osTemplateId: placement.osTemplateId!,
            nodeId: placement.nodeId,
            gameVariant: placement.gameVariant,
            gameConfig: placement.gameConfig && Object.keys(placement.gameConfig).length > 0 ? placement.gameConfig : Prisma.JsonNull,
            termMonths: months,
            // Rate basis for proration: the % off R x term this first term sold at.
            termPromoPercent: tot.termPromoPercent,
            // Freeze 0 so renewalCharge renews at exactly R x term (no annual discount on top).
            annualDiscountPct: 0,
            // THE renewal price — renewalCharge reads this instead of the plan price.
            grandfatheredRenewalCents: terms.pricing.renewalMonthlyCents,
            // Plan-portion cash actually collected for the term (excl. setup fee + IP).
            refundableTermCents: terms.pricing.firstTermCents,
            wantsDedicatedIp: terms.extras.dedicatedIp,
            autoRenew: true,
            expiresAt: addMonths(now, months),
          } as Prisma.ServerUncheckedCreateInput,
        });
        serverId = server.id;
        await tx.job.create({ data: { type: "PROVISION", serverId: server.id } });
        if (terms.extras.cpuPinning) {
          await tx.offerTask.create({
            data: {
              offerId: offer.id,
              serverId: server.id,
              kind: "CPU_PINNING",
              title: `Pin ${s.cpuCores} CPU cores for ${hostname}`,
              detail: `Offer #${terms.number} sold dedicated (pinned) cores. Once provisioned, set the VM's CPU affinity on ${placement.nodeName ?? "its node"} (Proxmox: qm set <vmid> --affinity <cores>) and record which cores here.`,
            },
          });
        }
        if (terms.extras.cpuPriority) {
          await tx.offerTask.create({
            data: {
              offerId: offer.id,
              serverId: server.id,
              kind: "CPU_PRIORITY",
              title: `Raise CPU priority for ${hostname}`,
              detail: `Offer #${terms.number} sold CPU priority. Once provisioned, raise the VM's CPU weight on ${placement.nodeName ?? "its node"} (Proxmox: qm set <vmid> --cpuunits <weight>, default 100).`,
            },
          });
        }
      } else {
        await tx.offerTask.create({
          data: {
            offerId: offer.id,
            kind: "DEDICATED_BUILD",
            title: `Build dedicated server for offer #${terms.number}`,
            detail:
              `Paid ${money(grossCents)} (invoice created). Nothing is auto-provisioned for dedicated servers: order/allocate the hardware, ` +
              `hand the customer their access, and invoice renewals (${money(terms.pricing.renewalMonthlyCents)}/mo) by hand.`,
          },
        });
      }

      await tx.offer.update({
        where: { id: offer.id },
        data: { serverId, invoiceId: invoice.id, planId, gamePlanId },
      });
      await tx.offerEvent.create({
        data: {
          offerId: offer.id,
          action: "paid",
          actorId: user.id,
          detail: `${opts.via}${opts.stripeSessionId ? ` ${opts.stripeSessionId}` : ""} gross=${grossCents} tax=${taxCents} invoice=${invoice.id}${serverId ? ` server=${serverId}` : ""}`,
        },
      });
      return { serverId, invoiceId: invoice.id, invoiceNumber: invoice.number, amountCents: invoice.amountCents, description };
    });
  } catch (e) {
    if (e instanceof OfferError && e.message === "ALREADY_HANDLED") {
      const fresh = await db.offer.findUnique({ where: { id: offer.id } });
      if (fresh?.status === "PAID") return { ok: true, already: true, serverId: fresh.serverId, invoiceId: fresh.invoiceId };
      return fail("This offer is no longer open.");
    }
    if (e instanceof InsufficientBalanceError) {
      return fail(
        opts.via === "card"
          ? "Your wallet balance changed during checkout, so the payment didn't cover the full amount. It's safe in your wallet — press Accept & pay again to finish."
          : "Your wallet balance doesn't cover this offer.",
      );
    }
    if (isHostnameConflict(e)) return fail("That server name was just taken — please try again.");
    return fail(String((e as Error)?.message ?? e));
  }

  // ---- Post-commit, best-effort: money has moved; nothing below may fail it. ----
  await db.auditLog
    .create({
      data: {
        userId: user.id,
        action: "offer.paid",
        category: "billing",
        detail: `offer #${terms.number} ${offer.id} kind=${terms.kind} via=${opts.via} gross=${grossCents} invoice=${result.invoiceId}${result.serverId ? ` server=${result.serverId} node=${placement.nodeName ?? "auto"}` : ""}`,
      },
    })
    .catch(() => {});
  await db.notification
    .create({
      data: {
        userId: user.id,
        title: isServer ? `Offer #${terms.number} paid — your server is being set up` : `Offer #${terms.number} paid — our team is preparing your server`,
        href: result.serverId ? `/dashboard/servers/${result.serverId}` : `/dashboard/offers/${offer.id}`,
      },
    })
    .catch(() => {});
  if (offer.conversationId) {
    await db.chatMessage
      .create({
        data: {
          conversationId: offer.conversationId,
          sender: "agent",
          body: `Offer #${terms.number} is paid — thank you! ${isServer ? "Your server is being set up now." : "Our team will be in touch to hand over your dedicated server."}`,
          cardsJson: JSON.stringify([{ type: "offer", key: `offer:${offer.id}:paid`, offerId: offer.id }]),
        },
      })
      .catch(() => {});
    await db.chatConversation
      .update({ where: { id: offer.conversationId }, data: { unreadForAgent: true, unreadForUser: true, lastMessageAt: new Date() } })
      .catch(() => {});
  }
  try {
    const { sendMail, emails } = await import("./mailer");
    const branding = await invoiceBranding();
    const tpl = emails.invoiceNew(
      {
        invoiceNumber: formatInvoiceNumber(result.invoiceNumber, branding.numberPrefix),
        amount: money(result.amountCents),
        dueDate: now.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
        description: result.description,
      },
      true,
    );
    await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, template: tpl.template, invoiceId: result.invoiceId, userId: user.id, kind: "invoice" });
  } catch {
    /* invoice email is best-effort */
  }
  return { ok: true, already: false, serverId: result.serverId, invoiceId: result.invoiceId };
}

