// CUSTOM OFFERS — DB-backed lifecycle (draft / send / cancel / decline / view) and
// the read models for staff and customers. Plain server module: the "use server"
// wrappers in lib/actions-offers.ts own the session/RBAC checks and call these.
// Pricing math is in lib/offer-pricing.ts (pure); fulfilment in lib/offer-fulfil.ts.
import type { Offer, User } from "@prisma/client";
import { db } from "./db";
import { dedicatedIpMonthlyCents } from "./dedicated-ip";
import { GAME_DISPLAY, type GameFamily } from "./games";
import { hashOfferTerms, OfferError, OFFER_UNSUPPORTED_GAME_FAMILIES } from "./offer-fulfil";
import {
  type OfferInput,
  type OfferStatusT,
  type OfferTerms,
  type OfferTotals,
  canTransition,
  effectiveOfferStatus,
  offerChatCard,
  offerSpecLines,
  offerTotals,
  parseOfferTerms,
  validateOfferInput,
  money,
  termLabel,
} from "./offer-pricing";

export { OfferError };

async function event(offerId: string, action: string, actorId: string | null, detail?: string) {
  await db.offerEvent.create({ data: { offerId, action, actorId, detail: detail?.slice(0, 1000) } });
}

async function audit(actorId: string, action: string, detail: string) {
  await db.auditLog.create({ data: { userId: actorId, action, category: "billing", detail: detail.slice(0, 1000) } }).catch(() => {});
}

function appUrl(): string {
  return (process.env.APP_URL ?? "http://localhost:3000").replace(/\/+$/, "");
}

export function offerUrl(offerId: string): string {
  return `${appUrl()}/dashboard/offers/${offerId}`;
}

function gameName(family: string | null | undefined): string | null {
  if (!family) return null;
  return GAME_DISPLAY[family as GameFamily]?.name ?? family;
}

/** Normalise composer input into the row's editable columns. */
function columnsFromInput(i: OfferInput) {
  const isDed = i.kind === "DEDICATED";
  return {
    kind: i.kind,
    title: i.title.trim(),
    cpuCores: i.cpuCores,
    ramMB: i.ramMB,
    diskGB: i.diskGB,
    storageTier: i.storageTier,
    bandwidthTB: i.bandwidthTB,
    osTemplateId: i.kind === "VPS" ? i.osTemplateId || null : null,
    gameFamily: i.kind === "GAME" ? (i.gameFamily || "").trim() || null : null,
    gameVariant: i.kind === "GAME" ? (i.gameVariant || "").trim() || null : null,
    gamePlanBasisId: i.kind === "GAME" ? i.gamePlanBasisId || null : null,
    slots: i.kind === "GAME" ? i.slots ?? null : null,
    basePlanId: i.kind === "VPS" ? i.basePlanId || null : null,
    nodeId: isDed ? null : i.nodeId || null,
    region: (i.region || "").trim() || null,
    cpuPriority: !isDed && !!i.cpuPriority,
    cpuPinning: !isDed && !!i.cpuPinning,
    dedicatedIp: !isDed && !!i.dedicatedIp,
    hostname: isDed ? null : (i.hostname || "").trim().toLowerCase() || null,
    notes: (i.notes ?? "").trim(),
    internalNote: (i.internalNote ?? "").trim(),
    firstTermCents: i.firstTermCents,
    renewalMonthlyCents: i.renewalMonthlyCents,
    termMonths: i.termMonths,
    setupFeeCents: i.setupFeeCents,
    discountLabel: (i.discountLabel ?? "").trim() || null,
    discountPercent: i.discountPercent ?? null,
  };
}

/** Extra checks that need the DB (referenced ids exist, game supported). */
async function validateRefs(i: OfferInput): Promise<string[]> {
  const e: string[] = [];
  if (i.kind === "VPS" && i.osTemplateId) {
    const os = await db.osTemplate.findFirst({ where: { id: i.osTemplateId, active: true }, select: { id: true } });
    if (!os) e.push("That operating system isn't available.");
  }
  if (i.kind === "GAME" && i.gameFamily) {
    if (OFFER_UNSUPPORTED_GAME_FAMILIES.has(i.gameFamily)) e.push("This game needs details collected at checkout — it can't be sold as an offer.");
    if (!GAME_DISPLAY[i.gameFamily as GameFamily]) e.push("Unknown game.");
  }
  if (i.kind !== "DEDICATED" && i.nodeId) {
    const n = await db.node.findFirst({ where: { id: i.nodeId, enabled: true }, select: { id: true } });
    if (!n) e.push("That node isn't available.");
  }
  return e;
}

/** Resolve who the offer is for. A chat offer needs a SIGNED-IN customer on the thread. */
export async function resolveOfferTarget(target: { conversationId?: string | null; userId?: string | null }): Promise<
  { ok: true; user: User; conversationId: string | null } | { ok: false; error: string }
> {
  if (target.conversationId) {
    const convo = await db.chatConversation.findUnique({ where: { id: target.conversationId } });
    if (!convo) return { ok: false, error: "Conversation not found." };
    if (!convo.userId) {
      return { ok: false, error: "This visitor isn't signed in. Ask them to sign in (or create an account) in the chat first — an offer has to belong to an account to be paid." };
    }
    const user = await db.user.findUnique({ where: { id: convo.userId } });
    if (!user) return { ok: false, error: "Customer account not found." };
    return { ok: true, user, conversationId: convo.id };
  }
  if (target.userId) {
    const user = await db.user.findUnique({ where: { id: target.userId } });
    if (!user) return { ok: false, error: "Customer account not found." };
    return { ok: true, user, conversationId: null };
  }
  return { ok: false, error: "No customer selected." };
}

export async function createOfferDraft(
  staff: Pick<User, "id">,
  input: OfferInput,
  target: { conversationId?: string | null; userId?: string | null },
): Promise<{ ok: true; offer: Offer } | { ok: false; errors: string[] }> {
  const errors = [...validateOfferInput(input), ...(await validateRefs(input))];
  if (errors.length) return { ok: false, errors };
  const t = await resolveOfferTarget(target);
  if (!t.ok) return { ok: false, errors: [t.error] };
  if (t.user.role !== "CUSTOMER" && t.user.id === staff.id) return { ok: false, errors: ["You can't send an offer to yourself."] };
  const offer = await db.offer.create({
    data: {
      ...columnsFromInput(input),
      userId: t.user.id,
      conversationId: t.conversationId,
      createdById: staff.id,
      expiresAt: new Date(Date.now() + input.expiresInDays * 86_400_000),
    },
  });
  await event(offer.id, "created", staff.id, `for ${t.user.email}`);
  await audit(staff.id, "offer.create", `offer #${offer.number} ${offer.id} for ${t.user.email} kind=${offer.kind}`);
  return { ok: true, offer };
}

/** Build the frozen terms from the row (+ live names/rates resolved ONCE, now). */
export async function buildTermsForSend(offer: Offer, now: Date): Promise<OfferTerms> {
  const [os, ipMonthly] = await Promise.all([
    offer.osTemplateId ? db.osTemplate.findUnique({ where: { id: offer.osTemplateId }, select: { name: true } }) : null,
    offer.dedicatedIp ? dedicatedIpMonthlyCents() : Promise.resolve(0),
  ]);
  let osName = os?.name ?? null;
  if (offer.kind === "VPS" && !osName) osName = "Ubuntu 24.04 LTS";
  return {
    v: 1,
    offerId: offer.id,
    number: offer.number,
    kind: offer.kind,
    title: offer.title,
    spec: {
      cpuCores: offer.cpuCores,
      ramMB: offer.ramMB,
      diskGB: offer.diskGB,
      storageTier: offer.storageTier === "hdd" ? "hdd" : "nvme",
      bandwidthTB: offer.bandwidthTB,
      osTemplateId: offer.osTemplateId,
      osName,
      gameFamily: offer.gameFamily,
      gameFamilyName: gameName(offer.gameFamily),
      gameVariant: offer.gameVariant,
      gamePlanBasisId: offer.gamePlanBasisId,
      slots: offer.slots,
      nodeId: offer.nodeId,
      region: offer.region,
      hostname: offer.hostname,
    },
    extras: { cpuPriority: offer.cpuPriority, cpuPinning: offer.cpuPinning, dedicatedIp: offer.dedicatedIp },
    notes: offer.notes,
    pricing: {
      currency: "USD",
      termMonths: offer.termMonths,
      firstTermCents: offer.firstTermCents,
      renewalMonthlyCents: offer.renewalMonthlyCents,
      setupFeeCents: offer.setupFeeCents,
      discountLabel: offer.discountLabel,
      discountPercent: offer.discountPercent,
      ipMonthlyCents: offer.dedicatedIp ? ipMonthly : 0,
    },
    sentAt: now.toISOString(),
    expiresAt: (offer.expiresAt ?? now).toISOString(),
  };
}

/**
 * DRAFT -> SENT: freeze the terms (snapshot + sha256), post the chat card, optionally
 * email the customer. The CAS on DRAFT makes a double-click send exactly once.
 */
export async function sendOffer(
  staff: Pick<User, "id">,
  offerId: string,
  opts: { emailCustomer: boolean; now?: Date },
): Promise<{ ok: true } | { ok: false; error: string }> {
  const now = opts.now ?? new Date();
  const offer = await db.offer.findUnique({ where: { id: offerId } });
  if (!offer) return { ok: false, error: "Offer not found." };
  if (offer.status !== "DRAFT") return { ok: false, error: "Only a draft can be sent." };
  if (!offer.expiresAt || offer.expiresAt.getTime() <= now.getTime()) return { ok: false, error: "Set an expiry in the future before sending." };
  const terms = await buildTermsForSend(offer, now);
  const termsHash = hashOfferTerms(terms);
  const flipped = await db.offer.updateMany({
    where: { id: offer.id, status: "DRAFT" },
    data: { status: "SENT", sentAt: now, sentById: staff.id, terms: terms as object, termsHash },
  });
  if (flipped.count !== 1) return { ok: false, error: "This offer was already sent." };
  await event(offer.id, "sent", staff.id, `hash=${termsHash.slice(0, 12)} email=${opts.emailCustomer}`);
  const user = await db.user.findUnique({ where: { id: offer.userId } });
  await audit(staff.id, "offer.send", `offer #${offer.number} ${offer.id} to ${user?.email ?? offer.userId} hash=${termsHash.slice(0, 12)}`);

  const tot = offerTotals(terms);
  const summary = offerSummaryLine(terms, tot);
  if (offer.conversationId) {
    const body = `I've put together a custom offer for you: ${terms.title}. ${summary} Review it and accept it here: ${offerUrl(offer.id)}`;
    await db.$transaction([
      db.chatMessage.create({
        data: { conversationId: offer.conversationId, sender: "agent", body, cardsJson: JSON.stringify([offerChatCard(offer.id)]) },
      }),
      db.chatConversation.update({
        where: { id: offer.conversationId },
        data: { status: "OPEN", unreadForUser: true, unreadForAgent: false, assignedToId: staff.id, lastMessageAt: now },
      }),
    ]);
    try {
      const { mirrorChatMessageToDiscord } = await import("./discord-bridge");
      await mirrorChatMessageToDiscord(offer.conversationId, body, "agent");
    } catch {
      /* best-effort */
    }
  }
  await db.notification
    .create({ data: { userId: offer.userId, title: `New offer: ${terms.title}`, body: summary, href: `/dashboard/offers/${offer.id}` } })
    .catch(() => {});
  if (opts.emailCustomer && user) {
    try {
      const { sendMail, emails } = await import("./mailer");
      const tpl = emails.genericNotification({
        heading: `Your custom offer: ${terms.title}`,
        message:
          `We've prepared a custom ${terms.kind === "GAME" ? "game server" : terms.kind === "VPS" ? "VPS" : "dedicated server"} offer for you.<br/><br/>` +
          `${offerSpecLines(terms).map(escapeHtml).join("<br/>")}<br/><br/>` +
          `${escapeHtml(summary)}<br/><br/>This offer is valid until ${new Date(terms.expiresAt).toUTCString()}.`,
        ctaLabel: "Review and accept",
        ctaUrl: offerUrl(offer.id),
      });
      await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, template: "offer_sent", userId: user.id });
      await event(offer.id, "emailed", staff.id, user.email);
    } catch {
      /* email is best-effort; the offer is already live in the portal */
    }
  }
  return { ok: true };
}

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}

export function offerSummaryLine(terms: OfferTerms, tot: OfferTotals = offerTotals(terms)): string {
  const p = terms.pricing;
  const first =
    p.termMonths === 1
      ? `${money(p.firstTermCents)} for the first month`
      : `${money(p.firstTermCents)} for the first ${termLabel(p.termMonths).toLowerCase()} term`;
  const setup = p.setupFeeCents > 0 ? ` + ${money(p.setupFeeCents)} setup` : "";
  const ip = tot.ipTermCents > 0 ? ` + dedicated IP` : "";
  return `${first}${setup}${ip}, then ${money(tot.renewalMonthlyAllInCents)}/mo.`;
}

/** Staff withdraws an offer. Also expires any open card checkout so it can't be paid. */
export async function cancelOffer(
  staff: Pick<User, "id">,
  offerId: string,
  reason: string,
): Promise<{ ok: true } | { ok: false; error: string }> {
  const offer = await db.offer.findUnique({ where: { id: offerId } });
  if (!offer) return { ok: false, error: "Offer not found." };
  if (!canTransition(offer.status as OfferStatusT, "CANCELLED")) return { ok: false, error: `A ${offer.status.toLowerCase()} offer can't be cancelled.` };
  const flipped = await db.offer.updateMany({
    where: { id: offer.id, status: { in: ["DRAFT", "SENT", "VIEWED", "ACCEPTED"] } },
    data: { status: "CANCELLED", cancelledAt: new Date(), cancelledById: staff.id, cancelReason: reason.trim().slice(0, 500) || null },
  });
  if (flipped.count !== 1) return { ok: false, error: "This offer changed while you were cancelling it — reload." };
  if (offer.checkoutSessionId) {
    try {
      const { stripe, stripeConfigured } = await import("./stripe");
      if (stripeConfigured()) {
        const s = await stripe().checkout.sessions.retrieve(offer.checkoutSessionId);
        if (s.status === "open") await stripe().checkout.sessions.expire(offer.checkoutSessionId);
      }
    } catch {
      /* if it was paid in the race, fulfilment refuses and the money stays in the wallet */
    }
  }
  await event(offer.id, "cancelled", staff.id, reason);
  await audit(staff.id, "offer.cancel", `offer #${offer.number} ${offer.id} reason=${reason.slice(0, 200)}`);
  if (offer.conversationId && offer.status !== "DRAFT") {
    await db.chatMessage
      .create({ data: { conversationId: offer.conversationId, sender: "agent", body: `Offer #${offer.number} has been withdrawn.`, cardsJson: JSON.stringify([offerChatCard(offer.id)]) } })
      .catch(() => {});
  }
  return { ok: true };
}

/** Customer declines. */
export async function declineOffer(user: Pick<User, "id">, offerId: string, reason: string): Promise<{ ok: true } | { ok: false; error: string }> {
  const offer = await db.offer.findUnique({ where: { id: offerId } });
  if (!offer || offer.userId !== user.id || offer.status === "DRAFT") return { ok: false, error: "Offer not found." };
  const flipped = await db.offer.updateMany({
    where: { id: offer.id, userId: user.id, status: { in: ["SENT", "VIEWED", "ACCEPTED"] } },
    data: { status: "DECLINED", declinedAt: new Date() },
  });
  if (flipped.count !== 1) return { ok: false, error: "This offer can no longer be declined." };
  await event(offer.id, "declined", user.id, reason.slice(0, 500));
  if (offer.conversationId) {
    await db.chatMessage
      .create({ data: { conversationId: offer.conversationId, sender: "visitor", body: `I've declined offer #${offer.number}.${reason.trim() ? ` ${reason.trim().slice(0, 500)}` : ""}` } })
      .catch(() => {});
    await db.chatConversation.update({ where: { id: offer.conversationId }, data: { unreadForAgent: true, lastMessageAt: new Date() } }).catch(() => {});
  }
  return { ok: true };
}

/** Persist lazy expiry so lists/filters agree with what customers see. */
export async function persistExpiry(offer: Pick<Offer, "id" | "status" | "expiresAt">, now = new Date()): Promise<OfferStatusT> {
  const eff = effectiveOfferStatus({ status: offer.status as OfferStatusT, expiresAt: offer.expiresAt }, now);
  if (eff === "EXPIRED" && offer.status !== "EXPIRED") {
    const r = await db.offer.updateMany({ where: { id: offer.id, status: offer.status }, data: { status: "EXPIRED" } });
    if (r.count === 1) await event(offer.id, "expired", null).catch(() => {});
  }
  return eff;
}

/* ------------------------------------------------------------------ *
 * Read model
 * ------------------------------------------------------------------ */

export type OfferView = {
  id: string;
  number: number;
  kind: Offer["kind"];
  status: OfferStatusT;
  title: string;
  specLines: string[];
  notes: string;
  termMonths: number;
  firstTermCents: number;
  renewalMonthlyCents: number;
  renewalMonthlyAllInCents: number;
  setupFeeCents: number;
  ipTermCents: number;
  dueNowNetCents: number;
  discountLabel: string | null;
  discountPercent: number | null;
  expiresAt: string | null;
  sentAt: string | null;
  paidAt: string | null;
  serverId: string | null;
  invoiceId: string | null;
  fulfilError: string | null;
  /** Staff-only fields; null for a customer viewer. */
  staff: null | {
    userId: string;
    internalNote: string;
    createdById: string;
    cancelReason: string | null;
    conversationId: string | null;
  };
};

/**
 * The offer as a viewer may see it. A customer only ever sees their OWN, SENT-or-
 * later offer, rendered from the frozen terms. Staff see drafts (from the live
 * columns) and the staff block. Returns null on any mismatch (not "forbidden"), so
 * an id probe can't tell an existing offer from a missing one.
 */
export async function getOfferForViewer(
  offerId: string,
  viewer: { user: Pick<User, "id">; staff: boolean },
  opts: { markViewed?: boolean } = {},
): Promise<OfferView | null> {
  if (!offerId || typeof offerId !== "string" || offerId.length > 40) return null;
  const offer = await db.offer.findUnique({ where: { id: offerId } });
  if (!offer) return null;
  if (!viewer.staff) {
    if (offer.userId !== viewer.user.id) return null;
    if (offer.status === "DRAFT") return null;
  }
  let status = await persistExpiry(offer);
  if (!viewer.staff && opts.markViewed && status === "SENT") {
    const r = await db.offer.updateMany({ where: { id: offer.id, status: "SENT" }, data: { status: "VIEWED", viewedAt: new Date() } });
    if (r.count === 1) {
      status = "VIEWED";
      await event(offer.id, "viewed", viewer.user.id).catch(() => {});
    }
  }
  return toView(offer, status, viewer.staff);
}

export function toView(offer: Offer, status: OfferStatusT, staff: boolean): OfferView {
  // Sent offers render from the snapshot — exactly what the customer accepted.
  const snap = parseOfferTerms(offer.terms);
  const terms: Pick<OfferTerms, "kind" | "spec" | "extras" | "pricing" | "title" | "notes"> = snap ?? {
    kind: offer.kind,
    title: offer.title,
    notes: offer.notes,
    spec: {
      cpuCores: offer.cpuCores,
      ramMB: offer.ramMB,
      diskGB: offer.diskGB,
      storageTier: offer.storageTier === "hdd" ? "hdd" : "nvme",
      bandwidthTB: offer.bandwidthTB,
      osTemplateId: offer.osTemplateId,
      osName: null,
      gameFamily: offer.gameFamily,
      gameFamilyName: gameName(offer.gameFamily),
      gameVariant: offer.gameVariant,
      gamePlanBasisId: offer.gamePlanBasisId,
      slots: offer.slots,
      nodeId: offer.nodeId,
      region: offer.region,
      hostname: offer.hostname,
    },
    extras: { cpuPriority: offer.cpuPriority, cpuPinning: offer.cpuPinning, dedicatedIp: offer.dedicatedIp },
    pricing: {
      currency: "USD",
      termMonths: offer.termMonths,
      firstTermCents: offer.firstTermCents,
      renewalMonthlyCents: offer.renewalMonthlyCents,
      setupFeeCents: offer.setupFeeCents,
      discountLabel: offer.discountLabel,
      discountPercent: offer.discountPercent,
      ipMonthlyCents: 0,
    },
  };
  const tot = offerTotals(terms);
  return {
    id: offer.id,
    number: offer.number,
    kind: offer.kind,
    status,
    title: terms.title,
    specLines: offerSpecLines(terms),
    notes: terms.notes,
    termMonths: tot.termMonths,
    firstTermCents: terms.pricing.firstTermCents,
    renewalMonthlyCents: terms.pricing.renewalMonthlyCents,
    renewalMonthlyAllInCents: tot.renewalMonthlyAllInCents,
    setupFeeCents: terms.pricing.setupFeeCents,
    ipTermCents: tot.ipTermCents,
    dueNowNetCents: tot.dueNowNetCents,
    discountLabel: terms.pricing.discountLabel,
    discountPercent: terms.pricing.discountPercent,
    expiresAt: offer.expiresAt?.toISOString() ?? null,
    sentAt: offer.sentAt?.toISOString() ?? null,
    paidAt: offer.paidAt?.toISOString() ?? null,
    serverId: offer.serverId,
    invoiceId: offer.invoiceId,
    fulfilError: offer.fulfilError,
    staff: staff
      ? {
          userId: offer.userId,
          internalNote: offer.internalNote,
          createdById: offer.createdById,
          cancelReason: offer.cancelReason,
          conversationId: offer.conversationId,
        }
      : null,
  };
}

