 * payment and the server it creates auto-renews off the saved card.
 */
export async function createOfferCheckout(
  user: CardUser,
  cardCents: number,
  opts: { offerId: string; number: number; title: string; grossCents: number; taxCents: number },
): Promise<{ checkout: EmbeddedCheckout; sessionId: string } | null> {
  if (!stripeConfigured() || cardCents <= 0) return null;
  const base = process.env.APP_URL ?? "http://localhost:3000";
  const { ensureStripeCustomer } = await import("./stripe-cards");
