    ui_mode: EMBEDDED_UI_MODE,
    return_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
  }, EMBEDDED_REQUEST_OPTS);
  return session.client_secret
    ? { checkout: { clientSecret: session.client_secret, publishableKey: stripePublishableKey() }, sessionId: session.id }
    : null;
}

'''
s = s.replace(anchor, new_fn + anchor, 1)
# 2. purpose union
a2 = "  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */\n  | { kind: \"topup\"; userId: string | null }"
assert a2 in s
s = s.replace(a2, "  /** A staff-built custom offer (lib/offer-fulfil.ts). gross/tax = what the checkout was opened for. */\n  | { kind: \"offer\"; userId: string; offerId: string; grossCents: number; taxCents: number }\n" + a2, 1)
