    if (!offerId || grossCents === null || taxCents === null) {
      return { kind: "unreadable", userId, detail: "nxeonOffer is missing offerId/grossCents/taxCents" };
    }
    return { kind: "offer", userId, offerId, grossCents, taxCents };
  }

'''
