a4 = "    metadata?.nxeonDomainOrder\n  );"
assert a4 in s
s = s.replace(a4, "    metadata?.nxeonDomainOrder ||\n    metadata?.nxeonOffer\n  );", 1)
open(p,'w').write(s)
EOF
