p='lib/fulfil-checkout.ts'
s=open(p).read()
s=s.replace('import { applyDedicatedIpPurchase } from "./dedicated-ip-purchase";','import { applyDedicatedIpPurchase } from "./dedicated-ip-purchase";\nimport { fulfilOffer } from "./offer-fulfil";',1)
s=s.replace('kind: "order" | "gameOrder" | "hostOrder" | "emailOrder" | "domainOrder" | "resize" | "diskExpand" | "dedicatedIp" | "topup" | "none";','kind: "order" | "gameOrder" | "hostOrder" | "emailOrder" | "domainOrder" | "resize" | "diskExpand" | "dedicatedIp" | "offer" | "topup" | "none";',1)
anchor='  const resize = purpose.kind === "resize" ? purpose : null;'
assert anchor in s
branch='''  // CUSTOM OFFER (lib/offer-fulfil.ts). The card leg was credited into the wallet
  // above; fulfilOffer debits the gross the session was opened for back out,
  // inside the same transaction as its own status CAS (Offer -> PAID), so even two
  // callers that both got past this claim could not provision twice. A refusal
  // (expired/withdrawn/wallet spent) leaves the money in the wallet and is recorded
  // on the offer + as a staff task by fulfilOffer itself.
  const offerPay = purpose.kind === "offer" ? purpose : null;
  if (offerPay) {
    const back = `${base}/dashboard/offers/${offerPay.offerId}`;
    if (!(await claim(sessionId, "offer"))) {
      return { redirect: back, fulfilled: false, kind: "offer" };
    }
    try {
      const res = await fulfilOffer({
        offerId: offerPay.offerId,
        userId: offerPay.userId,
        via: "card",
        sold: { grossCents: offerPay.grossCents, taxCents: offerPay.taxCents },
        stripeSessionId: sessionId,
      });
      if (!res.ok) throw new Error(res.error);
      if (res.already) {
        // A DIFFERENT session already paid this offer (the FulfilledSession claim
        // above stops the same session reaching here twice). This payment stays in
        // the wallet as credit; make sure a human sees it.
        await db.offerTask
          .create({
            data: {
              offerId: offerPay.offerId,
              kind: "NOTE",
              title: "Second payment for an already-paid offer",
              detail: `Checkout ${sessionId} was paid after the offer was already fulfilled. The amount is in the customer's wallet as credit — refund it if they want it back.`,
            },
          })
          .catch(() => {});
        await settle(sessionId, "DONE", "duplicate payment credited to wallet");
        return { redirect: `${back}?paid=1`, fulfilled: false, kind: "offer" };
      }
      await settle(sessionId, "DONE", res.serverId ?? res.invoiceId ?? offerPay.offerId);
      if (provider === "stripe") {
        try {
          await saveCardFromPaymentSession(session, offerPay.userId);
        } catch {
          /* best-effort: fulfilment already succeeded */
        }
      }
      const offerUser = await db.user.findUnique({ where: { id: offerPay.userId } });
      const target = res.serverId ? `${base}/dashboard/servers/${res.serverId}` : `${back}?paid=1`;
      const redirect = await reportPurchase(target, session, offerUser?.email, offerPay.userId, "offer");
      return { redirect, fulfilled: true, kind: "offer" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "offer", error: msg };
    }
  }

'''
s=s.replace(anchor, branch+anchor,1)
open(p,'w').write(s)
EOF
