export type AcceptResult = {
  error?: string;
  paid?: { serverId: string | null; invoiceId: string | null };
  checkout?: EmbeddedCheckout;
};

export async function acceptOfferAction(offerId: string, useWallet: boolean = true): Promise<AcceptResult> {
  await assertNotImpersonating();
  const user = await requireUser();
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  const rl = checkRateLimit(`offer-accept:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: "Please wait a moment and try again." };

  const offer = await db.offer.findUnique({ where: { id: String(offerId ?? "") } });
  if (!offer || offer.userId !== user.id || offer.status === "DRAFT") return { error: "Offer not found." };
  const status = await persistExpiry(offer);
  if (status === "PAID") return { paid: { serverId: offer.serverId, invoiceId: offer.invoiceId } };
  if (!canStartPayment({ status: status as OfferStatusT, expiresAt: offer.expiresAt })) {
    return {
      error:
        status === "CANCELLED" ? "This offer was withdrawn." :
        status === "DECLINED" ? "You declined this offer. Ask us in chat if you'd like it re-issued." :
        "This offer has expired. Ask us in chat and we'll re-issue it.",
    };
  }

  let terms;
  try {
    terms = trustedTerms(offer);
    // Capacity/image/node pre-flight BEFORE any money moves.
    await resolveOfferPlacement(terms, user.id);
  } catch (e) {
    const msg = e instanceof OfferError ? e.message : "We couldn't prepare this offer — please contact us.";
    await db.offerEvent.create({ data: { offerId: offer.id, action: "accept_blocked", actorId: user.id, detail: msg } }).catch(() => {});
    return { error: msg };
  }

  const due = await offerAmountDue(terms, user);
  const split = walletSplit({ dueCents: due.grossCents, balanceCents: user.balanceCents, useWallet });

  if (split.cardCents === 0) {
    if (user.balanceCents < due.grossCents) {
      return { error: `This offer is under the card minimum, so it can only be paid from your wallet — top up at least $${(due.grossCents / 100).toFixed(2)} first.` };
    }
    const r = await fulfilOffer({ offerId: offer.id, userId: user.id, via: "wallet" });
    revalidatePath(`/dashboard/offers/${offer.id}`);
    return r.ok ? { paid: { serverId: r.serverId, invoiceId: r.invoiceId } } : { error: r.error };
  }

  // Card leg. Mark ACCEPTED (records the moment the customer committed, which is
  // what the post-expiry payment grace is measured from).
  const now = new Date();
  const flipped = await db.offer.updateMany({
    where: { id: offer.id, userId: user.id, status: { in: ["SENT", "VIEWED", "ACCEPTED"] } },
    data: { status: "ACCEPTED", acceptedAt: offer.acceptedAt ?? now },
  });
  if (flipped.count !== 1) return { error: "This offer changed — please reload the page." };
  if (!offer.acceptedAt) {
    await db.offerEvent.create({ data: { offerId: offer.id, action: "accepted", actorId: user.id, detail: `gross=${due.grossCents} card=${split.cardCents} wallet=${split.walletApplied}` } }).catch(() => {});
  }

  // Reuse a still-open session for the SAME amounts (double-click / reopened tab), so
  // one customer never has two payable sessions for one offer. Otherwise expire it.
  if (offer.checkoutSessionId && stripeConfigured()) {
    try {
      const prev = await stripe().checkout.sessions.retrieve(offer.checkoutSessionId);
      let prevMeta: { grossCents?: number; taxCents?: number } = {};
      try {
        prevMeta = JSON.parse(prev.metadata?.nxeonOffer ?? "{}");
      } catch {
        prevMeta = {};
      }
      const same = prev.status === "open" && prev.amount_total === split.cardCents && prevMeta.grossCents === due.grossCents && prevMeta.taxCents === due.taxCents;
      if (same && prev.client_secret) {
        return { checkout: { clientSecret: prev.client_secret, publishableKey: stripePublishableKey() } };
      }
      if (prev.status === "open") await stripe().checkout.sessions.expire(prev.id);
    } catch {
      /* fall through to a fresh session */
    }
  }

  const created = await createOfferCheckout(user, split.cardCents, {
    offerId: offer.id,
    number: offer.number,
    title: terms.title,
    grossCents: due.grossCents,
    taxCents: due.taxCents,
  });
  if (!created) {
    return { error: `Card payments aren't available right now — top up your wallet with $${(due.grossCents / 100).toFixed(2)} and accept again.` };
  }
  await db.offer.update({ where: { id: offer.id }, data: { checkoutSessionId: created.sessionId } });
  return { checkout: created.checkout };
}

export async function declineOfferAction(offerId: string, reason: string): Promise<{ ok?: true; error?: string }> {
  await assertNotImpersonating();
  const user = await requireUser();
  const r = await declineOffer(user, String(offerId ?? ""), String(reason ?? ""));
  revalidatePath(`/dashboard/offers/${offerId}`);
  return r.ok ? { ok: true } : { error: r.error };
}

