"use server";

// "use server" surface for CUSTOM OFFERS. Every export here is network-reachable,
// so each one does its own session/RBAC check first:
//   staff:    requireGrant("billing") — ADMIN, BILLING, or an EMPLOYEE granted
//             billing. Sending a priced offer is a money decision, so live-chat-only
//             (SUPPORT) staff see the composer refuse with a clear message.
//   customer: requireUser + ownership (lib/offers.ts getOfferForViewer refuses
//             anyone else's offer as "not found"), assertNotImpersonating on the
//             spend path, email-verification gate like every other purchase.
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating, realUser } from "./auth";
import { requireGrant, hasAreaAccess } from "./staff-grants";
import { emailVerificationError } from "./email-verification";
import { checkRateLimit } from "./rate-limit";
import { walletSplit } from "./wallet-split";
import { createOfferCheckout, stripe, stripeConfigured, stripePublishableKey, type EmbeddedCheckout } from "./stripe";
import { dedicatedIpMonthlyCents } from "./dedicated-ip";
import { customPlanQuote, customGamePlanQuote } from "./custom-plan";
import { GAME_DISPLAY, type GameFamily } from "./games";
import { schemaFor } from "./game-config";
import {
  createOfferDraft,
  sendOffer,
  cancelOffer,
  declineOffer,
  getOfferForViewer,
  persistExpiry,
  type OfferView,
} from "./offers";
import {
  fulfilOffer,
  offerAmountDue,
  resolveOfferPlacement,
  trustedTerms,
  OfferError,
  OFFER_UNSUPPORTED_GAME_FAMILIES,
} from "./offer-fulfil";
import {
  type OfferInput,
  type OfferMargin,
  type OfferTotals,
  type OfferStatusT,
  canStartPayment,
  offerMargin,
  offerTotals,
  validateOfferInput,
} from "./offer-pricing";

/* ------------------------------------------------------------------ *
 * Staff: composer data, preview, create/send, cancel, tasks
 * ------------------------------------------------------------------ */

export type ComposerData =
  | { ok: false; error: string }
  | {
      ok: true;
      customer: { id: string; email: string; name: string; balanceCents: number } | null;
      customerError: string | null;
      vpsPlans: { id: string; name: string; cpuCores: number; ramMB: number; diskGB: number; bandwidthTB: number; storageTier: string; priceCents: number }[];
      games: {
        family: string;
        name: string;
        variants: { id: string; label: string }[];
        defaultVariant: string | null;
        plans: { id: string; name: string; cpuCores: number; ramMB: number; diskGB: number; slots: number | null; priceCents: number }[];
      }[];
      osTemplates: { id: string; name: string }[];
      nodes: { id: string; name: string; region: string; monthlyCostCents: number | null; capacityRamMB: number }[];
      regions: string[];
      ipMonthlyCents: number;
    };

export async function getOfferComposerData(target: { conversationId?: string | null; userId?: string | null }): Promise<ComposerData> {
  try {
    await requireGrant("billing");
  } catch {
    return { ok: false, error: "Sending offers needs billing access. Ask an admin to grant it, or hand this chat to someone with billing access." };
  }
  const { resolveOfferTarget } = await import("./offers");
  const t = await resolveOfferTarget(target);
  const [plans, gamePlans, os, nodes, ipMonthlyCents] = await Promise.all([
    db.plan.findMany({ where: { active: true, sortOrder: { lt: 900 } }, orderBy: { priceCents: "asc" } }),
    db.gamePlan.findMany({ where: { active: true, sortOrder: { lt: 900 } }, orderBy: [{ gameFamily: "asc" }, { priceCents: "asc" }] }),
    db.osTemplate.findMany({ where: { active: true, category: "PLAIN_OS" }, orderBy: { sortOrder: "asc" }, select: { id: true, name: true } }),
    db.node.findMany({ where: { enabled: true }, orderBy: { name: "asc" }, select: { id: true, name: true, region: true, monthlyCostCents: true, capacityRamMB: true } }),
    dedicatedIpMonthlyCents(),
  ]);
  const fam = new Map<string, ComposerData extends { ok: true } ? never : never>();
  void fam;
  const games: Extract<ComposerData, { ok: true }>["games"] = [];
  for (const gp of gamePlans) {
    if (OFFER_UNSUPPORTED_GAME_FAMILIES.has(gp.gameFamily)) continue;
    let g = games.find((x) => x.family === gp.gameFamily);
    if (!g) {
      const schema = schemaFor(gp.gameFamily);
      g = {
        family: gp.gameFamily,
        name: GAME_DISPLAY[gp.gameFamily as GameFamily]?.name ?? gp.gameFamily,
        variants: (schema?.variants ?? []).filter((v) => !v.unavailable).map((v) => ({ id: v.id, label: v.label })),
        defaultVariant: schema ? schema.orderDefaults?.variant ?? schema.defaultVariant : null,
        plans: [],
      };
      games.push(g);
    }
    g.plans.push({ id: gp.id, name: gp.name, cpuCores: gp.cpuCores, ramMB: gp.ramMB, diskGB: gp.diskGB, slots: gp.slots, priceCents: gp.priceCents });
  }
  games.sort((a, b) => a.name.localeCompare(b.name));
  return {
    ok: true,
    customer: t.ok ? { id: t.user.id, email: t.user.email, name: t.user.name, balanceCents: t.user.balanceCents } : null,
    customerError: t.ok ? null : t.error,
    vpsPlans: plans.map((p) => ({ id: p.id, name: p.name, cpuCores: p.cpuCores, ramMB: p.ramMB, diskGB: p.diskGB, bandwidthTB: p.bandwidthTB, storageTier: p.storageTier, priceCents: p.priceCents })),
    games,
    osTemplates: os,
    nodes,
    regions: Array.from(new Set(nodes.map((n) => n.region))).sort(),
    ipMonthlyCents,
  };
}

export type OfferPreview = {
  errors: string[];
  totals: OfferTotals;
  /** What the self-serve calculator would charge for this spec (monthly), if it can. */
  catalog: { label: string; monthlyCents: number | null; note: string | null };
  /** Margin vs the pinned node's (or region's cheapest node's) monthly cost. Null = no cost data. */
  margin: (OfferMargin & { nodeName: string }) | null;
};

export async function previewOfferAction(input: OfferInput): Promise<OfferPreview> {
  await requireGrant("billing");
  const errors = validateOfferInput(input);
  const ipMonthly = input.dedicatedIp && input.kind !== "DEDICATED" ? await dedicatedIpMonthlyCents() : 0;
  const totals = offerTotals({
    kind: input.kind,
    extras: { cpuPriority: input.cpuPriority, cpuPinning: input.cpuPinning, dedicatedIp: input.dedicatedIp },
    pricing: {
      currency: "USD",
      termMonths: [1, 12].includes(input.termMonths) ? input.termMonths : 1,
      firstTermCents: Math.max(0, input.firstTermCents | 0),
      renewalMonthlyCents: Math.max(0, input.renewalMonthlyCents | 0),
      setupFeeCents: Math.max(0, input.setupFeeCents | 0),
      discountLabel: null,
      discountPercent: null,
      ipMonthlyCents: ipMonthly,
    },
  });

  let catalog: OfferPreview["catalog"] = { label: "Self-serve price", monthlyCents: null, note: null };
  const spec = { cpuCores: input.cpuCores, ramMB: input.ramMB, diskGB: input.diskGB };
  try {
    if (input.kind === "VPS") {
      const exact = await db.plan.findFirst({
        where: { active: true, sortOrder: { lt: 900 }, cpuCores: spec.cpuCores, ramMB: spec.ramMB, diskGB: spec.diskGB },
      });
      if (exact) catalog = { label: `Catalog: ${exact.name}`, monthlyCents: exact.priceCents, note: null };
      else {
        const q = await customPlanQuote(spec);
        catalog = q.ok
          ? { label: "Custom-builder price", monthlyCents: q.priceCents, note: q.introPriceCents ? `builder intro ${(q.introPriceCents / 100).toFixed(2)}/mo first term` : null }
          : { label: "Custom-builder price", monthlyCents: null, note: q.reason };
      }
    } else if (input.kind === "GAME" && input.gameFamily) {
      const exact = await db.gamePlan.findFirst({
        where: { active: true, sortOrder: { lt: 900 }, gameFamily: input.gameFamily, cpuCores: spec.cpuCores, ramMB: spec.ramMB, diskGB: spec.diskGB },
      });
      if (exact) catalog = { label: `Catalog: ${exact.name}`, monthlyCents: exact.priceCents, note: null };
      else {
        const q = await customGamePlanQuote(input.gameFamily, spec);
        catalog = q.ok
          ? { label: "Custom-builder price", monthlyCents: q.priceCents, note: null }
          : { label: "Custom-builder price", monthlyCents: null, note: q.reason };
      }
    } else {
      catalog = { label: "No self-serve price", monthlyCents: null, note: "Dedicated servers aren't in the catalog." };
    }
  } catch (e) {
    catalog = { label: "Self-serve price", monthlyCents: null, note: String((e as Error)?.message ?? e).slice(0, 160) };
  }

  let margin: OfferPreview["margin"] = null;
  if (input.kind !== "DEDICATED" && input.ramMB > 0) {
    const node = input.nodeId
      ? await db.node.findUnique({ where: { id: input.nodeId }, select: { name: true, monthlyCostCents: true, capacityRamMB: true } })
      : await db.node.findFirst({
          where: { enabled: true, monthlyCostCents: { not: null }, ...(input.region ? { region: input.region } : {}) },
          orderBy: { monthlyCostCents: "asc" },
          select: { name: true, monthlyCostCents: true, capacityRamMB: true },
        });
    const m = offerMargin(input.renewalMonthlyCents, input.ramMB, node);
    if (m && node) margin = { ...m, nodeName: node.name };
  }
  return { errors, totals, catalog, margin };
}

