  if (flipped.count !== 1) return { error: "This offer changed — please reload the page." };
  if (!offer.acceptedAt) {
    await db.offerEvent.create({ data: { offerId: offer.id, action: "accepted", actorId: user.id, detail: `gross=${due.grossCents} card=${split.cardCents} wallet=${split.walletApplied}` } }).catch(() => {});
  }

  // Reuse a still-open session for the SAME amounts (double-click / reopened tab), so
  // one customer never has two payable sessions for one offer. Otherwise expire it.
  if (offer.checkoutSessionId && stripeConfigured()) {
    try {
      const prev = await stripe().checkout.sessions.retrieve(offer.checkoutSessionId);
      let prevMeta: { grossCents?: number; taxCents?: number } = {};
      try {
        prevMeta = JSON.parse(prev.metadata?.nxeonOffer ?? "{}");
      } catch {
        prevMeta = {};
      }
      const same = prev.status === "open" && prev.amount_total === split.cardCents && prevMeta.grossCents === due.grossCents && prevMeta.taxCents === due.taxCents;
      if (same && prev.client_secret) {
        return { checkout: { clientSecret: prev.client_secret, publishableKey: stripePublishableKey() } };
      }
      if (prev.status === "open") await stripe().checkout.sessions.expire(prev.id);
    } catch {
      /* fall through to a fresh session */
    }
  }

  const created = await createOfferCheckout(user, split.cardCents, {
    offerId: offer.id,
    number: offer.number,
    title: terms.title,
    grossCents: due.grossCents,
    taxCents: due.taxCents,
  });
  if (!created) {
    return { error: `Card payments aren't available right now — top up your wallet with $${(due.grossCents / 100).toFixed(2)} and accept again.` };
  }
  await db.offer.update({ where: { id: offer.id }, data: { checkoutSessionId: created.sessionId } });
  return { checkout: created.checkout };
}

export async function declineOfferAction(offerId: string, reason: string): Promise<{ ok?: true; error?: string }> {
  await assertNotImpersonating();
  const user = await requireUser();
  const r = await declineOffer(user, String(offerId ?? ""), String(reason ?? ""));
  revalidatePath(`/dashboard/offers/${offerId}`);
  return r.ok ? { ok: true } : { error: r.error };
}

