"use client";

import { useEffect, useState } from "react";
import { getOfferCardAction } from "@/lib/actions-offers";
import type { OfferView } from "@/lib/offers";

/**
 * A custom offer rendered inside a chat thread (customer widget AND staff desk).
 * The chat stores only `{ type: "offer", offerId }` in ChatMessage.cardsJson; the
 * card fetches the LIVE offer (status/expiry) through getOfferCardAction, which
 * enforces ownership (customer) or billing/liveChat access (admin) server-side and
 * renders from the frozen terms — so what the card shows is what the offer page
 * charges. Same visual family as the chat's plan/action cards (brand border,
 * glass fill, brand→blue CTA) so it reads as one system on both shells.
 */

const STATUS_TONE: Record<string, { label: string; cls: string }> = {
  DRAFT: { label: "Draft", cls: "bg-slate-500/20 text-slate-300" },
  SENT: { label: "Awaiting review", cls: "bg-brand-500/20 text-brand-200" },
  VIEWED: { label: "Viewed", cls: "bg-brand-500/20 text-brand-200" },
  ACCEPTED: { label: "Payment pending", cls: "bg-cyan-400/15 text-cyan-300" },
  PAID: { label: "Paid", cls: "bg-emerald-500/15 text-emerald-300" },
  EXPIRED: { label: "Expired", cls: "bg-slate-500/20 text-slate-400" },
  CANCELLED: { label: "Withdrawn", cls: "bg-slate-500/20 text-slate-400" },
  DECLINED: { label: "Declined", cls: "bg-slate-500/20 text-slate-400" },
};

function usd(cents: number): string {
  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function expiryLabel(iso: string | null): string | null {
  if (!iso) return null;
  const ms = new Date(iso).getTime() - Date.now();
  if (ms <= 0) return "Expired";
  const h = Math.floor(ms / 3_600_000);
  if (h < 24) return `Expires in ${Math.max(1, h)}h`;
  return `Expires in ${Math.floor(h / 24)}d`;
}

export default function OfferCard({ offerId, viewer }: { offerId: string; viewer: "admin" | "customer" }) {
  const [offer, setOffer] = useState<OfferView | null | undefined>(undefined);

  useEffect(() => {
    let alive = true;
    const load = () =>
      getOfferCardAction(offerId, viewer)
        .then((o) => alive && setOffer(o))
        .catch(() => alive && setOffer(null));
    load();
    // Status moves (viewed/paid/withdrawn) while the thread is open — refresh gently.
    const t = setInterval(load, 30_000);
    return () => {
      alive = false;
      clearInterval(t);
    };
  }, [offerId, viewer]);

  if (offer === undefined) {
    return <div className="mt-2 h-28 w-full max-w-[85%] animate-pulse rounded-2xl border border-brand-400/20 bg-white/[0.03]" aria-label="Loading offer" />;
  }
  if (offer === null) {
    return (
      <div className="mt-2 w-full max-w-[85%] rounded-2xl border border-white/10 bg-white/[0.03] p-3 text-xs text-slate-400">
        {viewer === "customer" ? "Sign in to the account this offer was sent to, to view it." : "Offer unavailable."}
      </div>
    );
  }

  const tone = STATUS_TONE[offer.status] ?? STATUS_TONE.SENT;
  const href = viewer === "admin" ? `/admin/offers?offer=${offer.id}` : `/dashboard/offers/${offer.id}`;
  const open = offer.status === "SENT" || offer.status === "VIEWED" || offer.status === "ACCEPTED";
  const regular = offer.renewalMonthlyCents * offer.termMonths;
  const discounted = offer.firstTermCents < regular;
  const exp = open ? expiryLabel(offer.expiresAt) : null;

  return (
    <div className="mt-2 w-full max-w-[85%] rounded-2xl border border-brand-400/30 bg-white/[0.03] p-3.5" data-testid="offer-card">
      <div className="flex items-center gap-2">
        <span className="rounded-full bg-brand-500/90 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
          Offer #{offer.number}
        </span>
        <span className={`rounded-full px-2 py-0.5 text-[10px] font-semibold ${tone.cls}`}>{tone.label}</span>
        <span className="ml-auto text-[10px] uppercase tracking-wide text-slate-500">
          {offer.kind === "GAME" ? "Game server" : offer.kind === "VPS" ? "VPS" : "Dedicated"}
        </span>
      </div>
      <p className="mt-1.5 text-sm font-semibold text-slate-100">{offer.title}</p>
      <ul className="mt-1.5 space-y-1">
        {offer.specLines.map((l, i) => (
          <li key={i} className="flex items-start gap-1.5 text-xs text-slate-300">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="mt-0.5 shrink-0 text-cyan-300" aria-hidden>
              <path d="M20 6 9 17l-5-5" />
            </svg>
            <span>{l}</span>
          </li>
        ))}
      </ul>
      <div className="mt-2.5 rounded-xl border border-white/[0.06] bg-black/20 px-3 py-2">
        <div className="flex items-baseline gap-1.5">
          <span className="text-xl font-bold text-slate-100">{usd(offer.firstTermCents)}</span>
          <span className="text-xs text-slate-400">{offer.termMonths === 1 ? "first month" : "first year"}</span>
          {discounted && <span className="text-xs text-slate-500 line-through">{usd(regular)}</span>}
          {discounted && offer.discountLabel && <span className="ml-auto text-[10px] font-semibold text-cyan-300">{offer.discountLabel}</span>}
        </div>
        <p className="mt-0.5 text-xs text-slate-400">
          then <span className="font-semibold text-slate-200">{usd(offer.renewalMonthlyAllInCents)}/mo</span>
          {offer.setupFeeCents > 0 && <> · {usd(offer.setupFeeCents)} one-time setup</>}
          {offer.ipTermCents > 0 && <> · incl. dedicated IP</>}
        </p>
      </div>
      {exp && <p className="mt-1.5 text-[11px] text-slate-500">{exp}</p>}
      <a
        href={href}
        className="mt-3 flex w-full items-center justify-center gap-1.5 rounded-xl bg-gradient-to-br from-brand-500 to-accent-blue px-3 py-2 text-sm font-semibold text-white transition hover:opacity-90"
      >
        {viewer === "admin" ? "Open in admin" : open ? "Review & accept" : offer.status === "PAID" && offer.serverId ? "View your server" : "View offer"}
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
          <path d="M5 12h14M13 6l6 6-6 6" />
        </svg>
      </a>
    </div>
  );
}

