            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="mt-0.5 shrink-0 text-cyan-300" aria-hidden>
              <path d="M20 6 9 17l-5-5" />
            </svg>
            <span>{l}</span>
          </li>
        ))}
      </ul>
      <div className="mt-2.5 rounded-xl border border-white/[0.06] bg-black/20 px-3 py-2">
        <div className="flex items-baseline gap-1.5">
          <span className="text-xl font-bold text-slate-100">{usd(offer.firstTermCents)}</span>
          <span className="text-xs text-slate-400">{offer.termMonths === 1 ? "first month" : "first year"}</span>
          {discounted && <span className="text-xs text-slate-500 line-through">{usd(regular)}</span>}
          {discounted && offer.discountLabel && <span className="ml-auto text-[10px] font-semibold text-cyan-300">{offer.discountLabel}</span>}
        </div>
        <p className="mt-0.5 text-xs text-slate-400">
          then <span className="font-semibold text-slate-200">{usd(offer.renewalMonthlyAllInCents)}/mo</span>
          {offer.setupFeeCents > 0 && <> · {usd(offer.setupFeeCents)} one-time setup</>}
          {offer.ipTermCents > 0 && <> · incl. dedicated IP</>}
        </p>
      </div>
      {exp && <p className="mt-1.5 text-[11px] text-slate-500">{exp}</p>}
      <a
        href={href}
        className="mt-3 flex w-full items-center justify-center gap-1.5 rounded-xl bg-gradient-to-br from-brand-500 to-accent-blue px-3 py-2 text-sm font-semibold text-white transition hover:opacity-90"
      >
        {viewer === "admin" ? "Open in admin" : open ? "Review & accept" : offer.status === "PAID" && offer.serverId ? "View your server" : "View offer"}
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
          <path d="M5 12h14M13 6l6 6-6 6" />
        </svg>
      </a>
    </div>
  );
}

