"use client";

import { useEffect, useMemo, useRef, useState, useTransition } from "react";
import {
  getOfferComposerData,
  previewOfferAction,
  createOfferAction,
  type ComposerData,
  type OfferPreview,
} from "@/lib/actions-offers";
import {
  type OfferInput,
  type OfferKindT,
  OFFER_DEFAULT_EXPIRY_DAYS,
  firstTermFromDiscount,
  money,
} from "@/lib/offer-pricing";

/**
 * Staff composer for a CUSTOM OFFER. Two entry points share one form:
 *   <OfferComposer conversationId onSent/>   — the live-chat "Send offer" button
 *                                              (rendered by the live-chat desk)
 *   <OfferComposerForm target={{userId}} />  — the admin customer page / /admin/offers
 *
 * The composer never decides a price on its own: it pre-fills from a catalog plan,
 * shows the self-serve/custom-builder price for the same spec next to what staff are
 * offering, and the margin against the node's real monthly cost — then the server
 * (lib/actions-offers.ts) re-validates everything before anything is saved.
 */
export function OfferComposer({ conversationId, onSent }: { conversationId: string; onSent(): void }) {
  return <OfferComposerForm target={{ conversationId }} onSent={onSent} />;
}

type Ok = Extract<ComposerData, { ok: true }>;

const toCents = (s: string): number => {
  const n = Number(String(s).replace(/[$,\s]/g, ""));
  return Number.isFinite(n) ? Math.round(n * 100) : NaN;
};
const toDollars = (c: number): string => (Number.isFinite(c) ? (c / 100).toFixed(2) : "");

export function OfferComposerForm({
  target,
  onSent,
}: {
  target: { conversationId?: string; userId?: string };
  onSent?(info: { offerId: string; number: number }): void;
}) {
  const [data, setData] = useState<ComposerData | null>(null);
  const [kind, setKind] = useState<OfferKindT>("VPS");
  const [basis, setBasis] = useState("");
  const [title, setTitle] = useState("");
  const [cpu, setCpu] = useState("6");
  const [ramGB, setRamGB] = useState("32");
  const [disk, setDisk] = useState("120");
  const [tier, setTier] = useState<"nvme" | "hdd">("nvme");
  const [bw, setBw] = useState("10");
  const [os, setOs] = useState("");
  const [game, setGame] = useState("");
  const [variant, setVariant] = useState("");
  const [slots, setSlots] = useState("");
  const [nodeId, setNodeId] = useState("");
  const [region, setRegion] = useState("");
  const [cpuPriority, setCpuPriority] = useState(false);
  const [cpuPinning, setCpuPinning] = useState(false);
  const [dedicatedIp, setDedicatedIp] = useState(false);
  const [hostname, setHostname] = useState("");
  const [renewal, setRenewal] = useState("");
  const [term, setTerm] = useState(1);
  const [discountPct, setDiscountPct] = useState("");
  const [discountLabel, setDiscountLabel] = useState("");
  const [firstTerm, setFirstTerm] = useState("");
  const [firstTermTouched, setFirstTermTouched] = useState(false);
  const [setupFee, setSetupFee] = useState("0");
  const [expiryDays, setExpiryDays] = useState(String(OFFER_DEFAULT_EXPIRY_DAYS));
  const [notes, setNotes] = useState("");
  const [internalNote, setInternalNote] = useState("");
  const [emailCustomer, setEmailCustomer] = useState(true);
  const [preview, setPreview] = useState<OfferPreview | null>(null);
  const [errors, setErrors] = useState<string[]>([]);
  const [done, setDone] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const seq = useRef(0);

  useEffect(() => {
    getOfferComposerData(target).then(setData).catch(() => setData({ ok: false, error: "Could not load the composer." }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target.conversationId, target.userId]);

  const ok = data && data.ok ? (data as Ok) : null;
  const gameRow = ok?.games.find((g) => g.family === game) ?? null;

  // First-term price follows renewal x term x (1 - discount) until staff type their own.
  useEffect(() => {
    if (firstTermTouched) return;
    const r = toCents(renewal);
    if (!Number.isFinite(r)) return;
    setFirstTerm(toDollars(firstTermFromDiscount(r, term, Number(discountPct) || 0)));
  }, [renewal, term, discountPct, firstTermTouched]);

  const input: OfferInput = useMemo(
    () => ({
      kind,
      title: title.trim(),
      cpuCores: Number(cpu) | 0,
      ramMB: Math.round((Number(ramGB) || 0) * 1024),
      diskGB: Number(disk) | 0,
      storageTier: tier,
      bandwidthTB: Number(bw) || 0,
      osTemplateId: kind === "VPS" ? os || null : null,
      gameFamily: kind === "GAME" ? game || null : null,
      gameVariant: kind === "GAME" ? variant || null : null,
      gamePlanBasisId: kind === "GAME" ? basis || null : null,
      slots: kind === "GAME" && slots ? Number(slots) | 0 : null,
      basePlanId: kind === "VPS" ? basis || null : null,
      nodeId: kind !== "DEDICATED" ? nodeId || null : null,
      region: region || null,
      cpuPriority: kind !== "DEDICATED" && cpuPriority,
      cpuPinning: kind !== "DEDICATED" && cpuPinning,
      dedicatedIp: kind !== "DEDICATED" && dedicatedIp,
      hostname: hostname.trim() || null,
      notes,
      internalNote,
      firstTermCents: toCents(firstTerm),
      renewalMonthlyCents: toCents(renewal),
      termMonths: term,
      setupFeeCents: toCents(setupFee || "0"),
      discountLabel: discountLabel.trim() || null,
      discountPercent: discountPct === "" ? null : Number(discountPct),
      expiresInDays: Number(expiryDays) | 0,
    }),
    [kind, title, cpu, ramGB, disk, tier, bw, os, game, variant, basis, slots, nodeId, region, cpuPriority, cpuPinning, dedicatedIp, hostname, notes, internalNote, firstTerm, renewal, term, setupFee, discountLabel, discountPct, expiryDays],
  );

  // Debounced authoritative preview (server-side catalog compare + margin).
  useEffect(() => {
    if (!ok) return;
    const my = ++seq.current;
    const t = setTimeout(() => {
      previewOfferAction(input)
        .then((p) => my === seq.current && setPreview(p))
        .catch(() => {});
    }, 350);
    return () => clearTimeout(t);
  }, [input, ok]);

  function applyBasis(id: string) {
    setBasis(id);
    if (!ok || !id) return;
    if (kind === "VPS") {
      const p = ok.vpsPlans.find((x) => x.id === id);
      if (!p) return;
      setCpu(String(p.cpuCores));
      setRamGB(String(p.ramMB / 1024));
      setDisk(String(p.diskGB));
      setBw(String(p.bandwidthTB));
      setTier(p.storageTier === "hdd" ? "hdd" : "nvme");
      setRenewal(toDollars(p.priceCents));
      if (!title) setTitle(`Custom ${p.name} VPS`);
    } else if (kind === "GAME" && gameRow) {
      const p = gameRow.plans.find((x) => x.id === id);
      if (!p) return;
      setCpu(String(p.cpuCores));
      setRamGB(String(p.ramMB / 1024));
      setDisk(String(p.diskGB));
      setSlots(p.slots ? String(p.slots) : "");
      setRenewal(toDollars(p.priceCents));
      if (!title) setTitle(`Custom ${gameRow.name} server`);
    }
    setFirstTermTouched(false);
  }

  function submit(send: boolean) {
    setErrors([]);
    setDone(null);
    if (send && !window.confirm(`Send this offer to ${ok?.customer?.email ?? "the customer"}?\n\nOnce sent, its terms are frozen — to change anything, cancel it and send a new one.`)) return;
    start(async () => {
      const r = await createOfferAction(target, input, { send, emailCustomer: send && emailCustomer });
      if (!r.ok) {
        setErrors(r.errors);
        return;
      }
      setDone(send ? `Offer #${r.number} sent.` : `Draft #${r.number} saved.`);
      onSent?.({ offerId: r.offerId, number: r.number });
    });
  }

  if (!data) return <div className="card text-sm text-slate-400">Loading offer composer…</div>;
  if (!data.ok) return <div className="card border-amber-500/30 text-sm text-amber-300">{data.error}</div>;
  const d = data;
  const ipLine = d.ipMonthlyCents > 0 ? `+${money(d.ipMonthlyCents)}/mo (platform rate)` : "platform rate";
  const regularTerm = Number.isFinite(input.renewalMonthlyCents) ? input.renewalMonthlyCents * term : NaN;

  return (
    <div className="space-y-4" data-testid="offer-composer">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <p className="section-label">Custom offer</p>
          {d.customer ? (
            <p className="text-sm text-slate-300">
              For <span className="font-semibold text-slate-100">{d.customer.name}</span> · {d.customer.email} · wallet {money(d.customer.balanceCents)}
            </p>
          ) : (
            <p className="text-sm text-amber-300">{d.customerError}</p>
          )}
        </div>
        <div className="flex gap-1 rounded-xl border border-white/10 p-1" role="tablist" aria-label="Product">
          {(["VPS", "GAME", "DEDICATED"] as OfferKindT[]).map((k) => (
            <button
              key={k}
              type="button"
              role="tab"
              aria-selected={kind === k}
              onClick={() => {
                setKind(k);
                setBasis("");
              }}
              className={`rounded-lg px-3 py-1 text-xs font-semibold ${kind === k ? "bg-brand-500 text-white" : "text-slate-400 hover:text-slate-200"}`}
            >
              {k === "VPS" ? "VPS" : k === "GAME" ? "Game server" : "Dedicated"}
            </button>
          ))}
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-2">
        {kind === "GAME" && (
          <div>
            <label className="label">Game</label>
            <select
              className="input"
              value={game}
              onChange={(e) => {
                setGame(e.target.value);
                setBasis("");
                const g = d.games.find((x) => x.family === e.target.value);
                setVariant(g?.defaultVariant ?? "");
              }}
            >
              <option value="">Pick a game…</option>
              {d.games.map((g) => (
                <option key={g.family} value={g.family}>{g.name}</option>
              ))}
            </select>
          </div>
        )}
        {kind !== "DEDICATED" && (
          <div>
            <label className="label">Start from a catalog plan</label>
            <select className="input" value={basis} onChange={(e) => applyBasis(e.target.value)} disabled={kind === "GAME" && !gameRow}>
              <option value="">— none (blank) —</option>
              {kind === "VPS"
                ? d.vpsPlans.map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.name} · {p.cpuCores} vCPU / {p.ramMB / 1024} GB / {p.diskGB} GB · {money(p.priceCents)}/mo
                    </option>
                  ))
                : (gameRow?.plans ?? []).map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.name} · {money(p.priceCents)}/mo
                    </option>
                  ))}
            </select>
          </div>
        )}
        <div className="sm:col-span-2">
          <label className="label">Title (customer sees this)</label>
          <input className="input" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Custom 6 vCPU / 32 GB VPS" maxLength={120} />
        </div>
      </div>

      <fieldset className="grid grid-cols-2 gap-3 sm:grid-cols-5">
        <legend className="section-label mb-1">Specs</legend>
        <div>
          <label className="label">{kind === "DEDICATED" ? "Cores" : "vCPU"}</label>
          <input className="input" inputMode="numeric" value={cpu} onChange={(e) => setCpu(e.target.value)} />
        </div>
        <div>
          <label className="label">RAM (GB)</label>
          <input className="input" inputMode="decimal" value={ramGB} onChange={(e) => setRamGB(e.target.value)} />
        </div>
        <div>
          <label className="label">Disk (GB)</label>
          <input className="input" inputMode="numeric" value={disk} onChange={(e) => setDisk(e.target.value)} />
        </div>
        <div>
          <label className="label">Storage</label>
          <select className="input" value={tier} onChange={(e) => setTier(e.target.value as "nvme" | "hdd")}>
            <option value="nvme">NVMe</option>
            <option value="hdd">HDD</option>
          </select>
        </div>
        <div>
          <label className="label">Bandwidth (TB)</label>
          <input className="input" inputMode="decimal" value={bw} onChange={(e) => setBw(e.target.value)} />
        </div>
        {kind === "VPS" && (
          <div className="col-span-2">
            <label className="label">Operating system</label>
            <select className="input" value={os} onChange={(e) => setOs(e.target.value)}>
              <option value="">Ubuntu 24.04 LTS (default)</option>
              {d.osTemplates.map((o) => (
                <option key={o.id} value={o.id}>{o.name}</option>
              ))}
            </select>
          </div>
        )}
        {kind === "GAME" && gameRow && (
          <>
            {gameRow.variants.length > 0 && (
              <div className="col-span-2">
                <label className="label">Server type</label>
                <select className="input" value={variant} onChange={(e) => setVariant(e.target.value)}>
                  {gameRow.variants.map((v) => (
                    <option key={v.id} value={v.id}>{v.label}</option>
                  ))}
                </select>
              </div>
            )}
            <div>
              <label className="label">Player slots</label>
              <input className="input" inputMode="numeric" value={slots} onChange={(e) => setSlots(e.target.value)} placeholder="—" />
            </div>
          </>
        )}
        {kind !== "DEDICATED" && (
          <div className={kind === "VPS" ? "col-span-2" : "col-span-2"}>
            <label className="label">Hostname (optional)</label>
            <input className="input" value={hostname} onChange={(e) => setHostname(e.target.value.toLowerCase())} placeholder="auto" maxLength={40} />
          </div>
        )}
      </fieldset>

      <fieldset className="grid gap-3 sm:grid-cols-2">
        <legend className="section-label mb-1">Placement &amp; extras</legend>
        {kind !== "DEDICATED" && (
          <div>
            <label className="label">Node</label>
            <select className="input" value={nodeId} onChange={(e) => setNodeId(e.target.value)}>
              <option value="">Automatic (least-loaded in region)</option>
              {d.nodes.map((n) => (
                <option key={n.id} value={n.id}>
                  {n.name} · {n.region}
                  {n.monthlyCostCents ? ` · ${money(n.monthlyCostCents)}/mo` : ""}
                </option>
              ))}
            </select>
          </div>
        )}
        <div>
          <label className="label">Region preference</label>
          <select className="input" value={region} onChange={(e) => setRegion(e.target.value)}>
            <option value="">Customer&apos;s default</option>
            {d.regions.map((r) => (
              <option key={r} value={r}>{r}</option>
            ))}
          </select>
        </div>
        {kind !== "DEDICATED" && (
          <div className="flex flex-wrap gap-x-5 gap-y-2 sm:col-span-2">
            <label className="flex items-center gap-2 text-sm text-slate-300">
              <input type="checkbox" checked={cpuPinning} onChange={(e) => setCpuPinning(e.target.checked)} /> Pinned CPU cores
              <span className="text-[11px] text-amber-300/80">manual task</span>
            </label>
            <label className="flex items-center gap-2 text-sm text-slate-300">
              <input type="checkbox" checked={cpuPriority} onChange={(e) => setCpuPriority(e.target.checked)} /> CPU priority
              <span className="text-[11px] text-amber-300/80">manual task</span>
            </label>
            <label className="flex items-center gap-2 text-sm text-slate-300">
              <input type="checkbox" checked={dedicatedIp} onChange={(e) => setDedicatedIp(e.target.checked)} /> Dedicated IPv4
              <span className="text-[11px] text-slate-500">{ipLine}</span>
            </label>
          </div>
        )}
      </fieldset>

      <fieldset className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <legend className="section-label mb-1">Price (USD)</legend>
        <div>
          <label className="label">Renews at ($/mo)</label>
          <input className="input" inputMode="decimal" value={renewal} onChange={(e) => setRenewal(e.target.value)} placeholder="75.80" />
        </div>
        <div>
          <label className="label">Term</label>
          <select className="input" value={term} onChange={(e) => setTerm(Number(e.target.value))}>
            <option value={1}>Monthly</option>
            <option value={12}>Annual (12 mo)</option>
          </select>
        </div>
        <div>
          <label className="label">First-term discount %</label>
          <input
            className="input"
            inputMode="decimal"
            value={discountPct}
            onChange={(e) => {
              setDiscountPct(e.target.value);
              setFirstTermTouched(false);
            }}
            placeholder="0"
          />
        </div>
        <div>
          <label className="label">First term total ($)</label>
          <input
            className="input"
            inputMode="decimal"
            value={firstTerm}
            onChange={(e) => {
              setFirstTerm(e.target.value);
              setFirstTermTouched(true);
            }}
          />
          {Number.isFinite(regularTerm) && <p className="mt-1 text-[11px] text-slate-500">regular {money(regularTerm)}</p>}
        </div>
        <div className="col-span-2">
          <label className="label">Discount label (optional)</label>
          <input className="input" value={discountLabel} onChange={(e) => setDiscountLabel(e.target.value)} placeholder="50% off your first month" maxLength={80} />
        </div>
        <div>
          <label className="label">Setup fee ($)</label>
          <input className="input" inputMode="decimal" value={setupFee} onChange={(e) => setSetupFee(e.target.value)} />
        </div>
        <div>
          <label className="label">Valid for (days)</label>
          <input className="input" inputMode="numeric" value={expiryDays} onChange={(e) => setExpiryDays(e.target.value)} />
        </div>
      </fieldset>

      <div className="grid gap-3 sm:grid-cols-2">
        <div>
          <label className="label">Notes for the customer</label>
          <textarea className="input min-h-[72px]" value={notes} onChange={(e) => setNotes(e.target.value)} maxLength={2000} placeholder="What's included, setup timeline…" />
        </div>
        <div>
          <label className="label">Internal note (staff only)</label>
          <textarea className="input min-h-[72px]" value={internalNote} onChange={(e) => setInternalNote(e.target.value)} maxLength={2000} placeholder="Why this price, who approved it…" />
        </div>
      </div>

      {preview && (
        <div className="grid gap-3 rounded-xl border border-white/10 bg-white/[0.02] p-3 text-sm sm:grid-cols-3" data-testid="offer-preview">
          <div>
            <p className="text-[11px] uppercase tracking-wide text-slate-500">Due now (before tax)</p>
            <p className="text-lg font-bold text-slate-100">{money(preview.totals.dueNowNetCents)}</p>
            <p className="text-xs text-slate-400">
              then {money(preview.totals.renewalMonthlyAllInCents)}/mo
              {preview.totals.termPromoPercent > 0 && <> · {preview.totals.termPromoPercent}% off first term</>}
            </p>
          </div>
          <div>
            <p className="text-[11px] uppercase tracking-wide text-slate-500">{preview.catalog.label}</p>
            <p className="text-lg font-bold text-slate-100">{preview.catalog.monthlyCents != null ? `${money(preview.catalog.monthlyCents)}/mo` : "—"}</p>
            {preview.catalog.monthlyCents != null && Number.isFinite(input.renewalMonthlyCents) && (
              <p className={`text-xs ${input.renewalMonthlyCents < preview.catalog.monthlyCents ? "text-amber-300" : "text-emerald-300"}`}>
                offer is {money(Math.abs(input.renewalMonthlyCents - preview.catalog.monthlyCents))}/mo {input.renewalMonthlyCents < preview.catalog.monthlyCents ? "below" : "above"} self-serve
              </p>
            )}
            {preview.catalog.note && <p className="text-xs text-slate-500">{preview.catalog.note}</p>}
          </div>
          <div>
            <p className="text-[11px] uppercase tracking-wide text-slate-500">Margin vs node cost</p>
            {preview.margin ? (
              <>
                <p className={`text-lg font-bold ${preview.margin.marginCents < 0 ? "text-red-400" : "text-slate-100"}`}>
                  {money(preview.margin.marginCents)}/mo · {preview.margin.marginPercent}%
                </p>
                <p className="text-xs text-slate-400">
                  cost share {money(preview.margin.costShareCents)}/mo of {preview.margin.nodeName} (by RAM)
                </p>
              </>
            ) : (
              <p className="text-xs text-slate-500">No node cost on record{kind === "DEDICATED" ? " (dedicated)" : ""}.</p>
            )}
          </div>
          {preview.errors.length > 0 && (
            <ul className="space-y-0.5 text-xs text-amber-300 sm:col-span-3">
              {preview.errors.map((e) => (
                <li key={e}>• {e}</li>
              ))}
            </ul>
          )}
        </div>
      )}

      {errors.length > 0 && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {errors.map((e) => (
            <p key={e}>{e}</p>
          ))}
        </div>
      )}
      {done && <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{done}</div>}

      <div className="flex flex-wrap items-center justify-end gap-3">
        <label className="mr-auto flex items-center gap-2 text-sm text-slate-400">
          <input type="checkbox" checked={emailCustomer} onChange={(e) => setEmailCustomer(e.target.checked)} /> Also email the customer a link
        </label>
        <button type="button" className="btn-ghost" disabled={pending || !d.customer} onClick={() => submit(false)}>
          Save draft
        </button>
        <button type="button" className="btn-primary" disabled={pending || !d.customer || (preview?.errors.length ?? 0) > 0} onClick={() => submit(true)}>
          {pending ? "Sending…" : "Send offer"}
        </button>
      </div>
    </div>
  );
}

export default OfferComposer;

toolu_01EbP5fGzAJvRCg4PTRkTwFm.content:
"use client";

import { useEffect, useMemo, useRef, useState, useTransition } from "react";
import {
  getOfferComposerData,
  previewOfferAction,
  createOfferAction,
  type ComposerData,
  type OfferPreview,
} from "@/lib/actions-offers";
import {
  type OfferInput,
  type OfferKindT,
  OFFER_DEFAULT_EXPIRY_DAYS,
  firstTermFromDiscount,
  money,
} from "@/lib/offer-pricing";

/**
 * Staff composer for a CUSTOM OFFER. Two entry points share one form:
 *   <OfferComposer conversationId onSent/>   — the live-chat "Send offer" button
 *                                              (rendered by the live-chat desk)
 *   <OfferComposerForm target={{userId}} />  — the admin customer page / /admin/offers
 *
 * The composer never decides a price on its own: it pre-fills from a catalog plan,
 * shows the self-serve/custom-builder price for the same spec next to what staff are
 * offering, and the margin against the node's real monthly cost — then the server
 * (lib/actions-offers.ts) re-validates everything before anything is saved.
 */
export function OfferComposer({ conversationId, onSent }: { conversationId: string; onSent(): void }) {
  return <OfferComposerForm target={{ conversationId }} onSent={onSent} />;
}

type Ok = Extract<ComposerData, { ok: true }>;

const toCents = (s: string): number => {
  const n = Number(String(s).replace(/[$,\s]/g, ""));
  return Number.isFinite(n) ? Math.round(n * 100) : NaN;
};
const toDollars = (c: number): string => (Number.isFinite(c) ? (c / 100).toFixed(2) : "");

export function OfferComposerForm({
  target,
  onSent,
}: {
  target: { conversationId?: string; userId?: string };
  onSent?(info: { offerId: string; number: number }): void;
}) {
  const [data, setData] = useState<ComposerData | null>(null);
  const [kind, setKind] = useState<OfferKindT>("VPS");
  const [basis, setBasis] = useState("");
  const [title, setTitle] = useState("");
  const [cpu, setCpu] = useState("6");
  const [ramGB, setRamGB] = useState("32");
  const [disk, setDisk] = useState("120");
  const [tier, setTier] = useState<"nvme" | "hdd">("nvme");
  const [bw, setBw] = useState("10");
  const [os, setOs] = useState("");
  const [game, setGame] = useState("");
  const [variant, setVariant] = useState("");
  const [slots, setSlots] = useState("");
  const [nodeId, setNodeId] = useState("");
  const [region, setRegion] = useState("");
  const [cpuPriority, setCpuPriority] = useState(false);
  const [cpuPinning, setCpuPinning] = useState(false);
  const [dedicatedIp, setDedicatedIp] = useState(false);
  const [hostname, setHostname] = useState("");
  const [renewal, setRenewal] = useState("");
  const [term, setTerm] = useState(1);
  const [discountPct, setDiscountPct] = useState("");
  const [discountLabel, setDiscountLabel] = useState("");
  const [firstTerm, setFirstTerm] = useState("");
  const [firstTermTouched, setFirstTermTouched] = useState(false);
  const [setupFee, setSetupFee] = useState("0");
  const [expiryDays, setExpiryDays] = useState(String(OFFER_DEFAULT_EXPIRY_DAYS));
  const [notes, setNotes] = useState("");
  const [internalNote, setInternalNote] = useState("");
  const [emailCustomer, setEmailCustomer] = useState(true);
  const [preview, setPreview] = useState<OfferPreview | null>(null);
  const [errors, setErrors] = useState<string[]>([]);
  const [done, setDone] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const seq = useRef(0);

  useEffect(() => {
    getOfferComposerData(target).then(setData).catch(() => setData({ ok: false, error: "Could not load the composer." }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target.conversationId, target.userId]);

  const ok = data && data.ok ? (data as Ok) : null;
  const gameRow = ok?.games.find((g) => g.family === game) ?? null;

  // First-term price follows renewal x term x (1 - discount) until staff type their own.
  useEffect(() => {
    if (firstTermTouched) return;
    const r = toCents(renewal);
    if (!Number.isFinite(r)) return;
    setFirstTerm(toDollars(firstTermFromDiscount(r, term, Number(discountPct) || 0)));
  }, [renewal, term, discountPct, firstTermTouched]);

  const input: OfferInput = useMemo(
    () => ({
      kind,
      title: title.trim(),
      cpuCores: Number(cpu) | 0,
      ramMB: Math.round((Number(ramGB) || 0) * 1024),
      diskGB: Number(disk) | 0,
      storageTier: tier,
      bandwidthTB: Number(bw) || 0,
      osTemplateId: kind === "VPS" ? os || null : null,
      gameFamily: kind === "GAME" ? game || null : null,
      gameVariant: kind === "GAME" ? variant || null : null,
      gamePlanBasisId: kind === "GAME" ? basis || null : null,
      slots: kind === "GAME" && slots ? Number(slots) | 0 : null,
      basePlanId: kind === "VPS" ? basis || null : null,
      nodeId: kind !== "DEDICATED" ? nodeId || null : null,
      region: region || null,
      cpuPriority: kind !== "DEDICATED" && cpuPriority,
      cpuPinning: kind !== "DEDICATED" && cpuPinning,
      dedicatedIp: kind !== "DEDICATED" && dedicatedIp,
      hostname: hostname.trim() || null,
      notes,
      internalNote,
      firstTermCents: toCents(firstTerm),
      renewalMonthlyCents: toCents(renewal),
      termMonths: term,
      setupFeeCents: toCents(setupFee || "0"),
      discountLabel: discountLabel.trim() || null,
      discountPercent: discountPct === "" ? null : Number(discountPct),
      expiresInDays: Number(expiryDays) | 0,
    }),
    [kind, title, cpu, ramGB, disk, tier, bw, os, game, variant, basis, slots, nodeId, region, cpuPriority, cpuPinning, dedicatedIp, hostname, notes, internalNote, firstTerm, renewal, term, setupFee, discountLabel, discountPct, expiryDays],
  );

  // Debounced authoritative preview (server-side catalog compare + margin).
  useEffect(() => {
    if (!ok) return;
    const my = ++seq.current;
    const t = setTimeout(() => {
      previewOfferAction(input)
        .then((p) => my === seq.current && setPreview(p))
        .catch(() => {});
    }, 350);
    return () => clearTimeout(t);
  }, [input, ok]);

  function applyBasis(id: string) {
    setBasis(id);
    if (!ok || !id) return;
    if (kind === "VPS") {
      const p = ok.vpsPlans.find((x) => x.id === id);
      if (!p) return;
      setCpu(String(p.cpuCores));
      setRamGB(String(p.ramMB / 1024));
      setDisk(String(p.diskGB));
      setBw(String(p.bandwidthTB));
      setTier(p.storageTier === "hdd" ? "hdd" : "nvme");
      setRenewal(toDollars(p.priceCents));
      if (!title) setTitle(`Custom ${p.name} VPS`);
    } else if (kind === "GAME" && gameRow) {
      const p = gameRow.plans.find((x) => x.id === id);
      if (!p) return;
      setCpu(String(p.cpuCores));
      setRamGB(String(p.ramMB / 1024));
      setDisk(String(p.diskGB));
      setSlots(p.slots ? String(p.slots) : "");
      setRenewal(toDollars(p.priceCents));
      if (!title) setTitle(`Custom ${gameRow.name} server`);
    }
    setFirstTermTouched(false);
  }

  function submit(send: boolean) {
    setErrors([]);
    setDone(null);
    if (send && !window.confirm(`Send this offer to ${ok?.customer?.email ?? "the customer"}?\n\nOnce sent, its terms are frozen — to change anything, cancel it and send a new one.`)) return;
    start(async () => {
      const r = await createOfferAction(target, input, { send, emailCustomer: send && emailCustomer });
      if (!r.ok) {
        setErrors(r.errors);
        return;
      }
      setDone(send ? `Offer #${r.number} sent.` : `Draft #${r.number} saved.`);
      onSent?.({ offerId: r.offerId, number: r.number });
    });
  }

  if (!data) return <div className="card text-sm text-slate-400">Loading offer composer…</div>;
  if (!data.ok) return <div className="card border-amber-500/30 text-sm text-amber-300">{data.error}</div>;
  const d = data;
  const ipLine = d.ipMonthlyCents > 0 ? `+${money(d.ipMonthlyCents)}/mo (platform rate)` : "platform rate";
  const regularTerm = Number.isFinite(input.renewalMonthlyCents) ? input.renewalMonthlyCents * term : NaN;

  return (
    <div className="space-y-4" data-testid="offer-composer">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <p className="section-label">Custom offer</p>
          {d.customer ? (
            <p className="text-sm text-slate-300">
              For <span className="font-semibold text-slate-100">{d.customer.name}</span> · {d.customer.email} · wallet {money(d.customer.balanceCents)}
            </p>
          ) : (
            <p className="text-sm text-amber-300">{d.customerError}</p>
          )}
        </div>
        <div className="flex gap-1 rounded-xl border border-white/10 p-1" role="tablist" aria-label="Product">
          {(["VPS", "GAME", "DEDICATED"] as OfferKindT[]).map((k) => (
            <button
              key={k}
              type="button"
              role="tab"
              aria-selected={kind === k}
              onClick={() => {
                setKind(k);
                setBasis("");
              }}
              className={`rounded-lg px-3 py-1 text-xs font-semibold ${kind === k ? "bg-brand-500 text-white" : "text-slate-400 hover:text-slate-200"}`}
            >
              {k === "VPS" ? "VPS" : k === "GAME" ? "Game server" : "Dedicated"}
            </button>
          ))}
        </div>
      </div>

      <div className="grid gap-3 sm:grid-cols-2">
        {kind === "GAME" && (
          <div>
            <label className="label">Game</label>
            <select
              className="input"
              value={game}
              onChange={(e) => {
                setGame(e.target.value);
                setBasis("");
                const g = d.games.find((x) => x.family === e.target.value);
                setVariant(g?.defaultVariant ?? "");
              }}
            >
              <option value="">Pick a game…</option>
              {d.games.map((g) => (
                <option key={g.family} value={g.family}>{g.name}</option>
              ))}
            </select>
          </div>
        )}
        {kind !== "DEDICATED" && (
          <div>
            <label className="label">Start from a catalog plan</label>
            <select className="input" value={basis} onChange={(e) => applyBasis(e.target.value)} disabled={kind === "GAME" && !gameRow}>
              <option value="">— none (blank) —</option>
              {kind === "VPS"
                ? d.vpsPlans.map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.name} · {p.cpuCores} vCPU / {p.ramMB / 1024} GB / {p.diskGB} GB · {money(p.priceCents)}/mo
                    </option>
                  ))
                : (gameRow?.plans ?? []).map((p) => (
                    <option key={p.id} value={p.id}>
                      {p.name} · {money(p.priceCents)}/mo
                    </option>
                  ))}
            </select>
          </div>
        )}
        <div className="sm:col-span-2">
          <label className="label">Title (customer sees this)</label>
          <input className="input" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Custom 6 vCPU / 32 GB VPS" maxLength={120} />
        </div>
      </div>

      <fieldset className="grid grid-cols-2 gap-3 sm:grid-cols-5">
        <legend className="section-label mb-1">Specs</legend>
        <div>
          <label className="label">{kind === "DEDICATED" ? "Cores" : "vCPU"}</label>
          <input className="input" inputMode="numeric" value={cpu} onChange={(e) => setCpu(e.target.value)} />
        </div>
        <div>
          <label className="label">RAM (GB)</label>
          <input className="input" inputMode="decimal" value={ramGB} onChange={(e) => setRamGB(e.target.value)} />
        </div>
        <div>
          <label className="label">Disk (GB)</label>
          <input className="input" inputMode="numeric" value={disk} onChange={(e) => setDisk(e.target.value)} />
        </div>
        <div>
          <label className="label">Storage</label>
          <select className="input" value={tier} onChange={(e) => setTier(e.target.value as "nvme" | "hdd")}>
            <option value="nvme">NVMe</option>
            <option value="hdd">HDD</option>
          </select>
        </div>
        <div>
          <label className="label">Bandwidth (TB)</label>
          <input className="input" inputMode="decimal" value={bw} onChange={(e) => setBw(e.target.value)} />
        </div>
        {kind === "VPS" && (
          <div className="col-span-2">
            <label className="label">Operating system</label>
            <select className="input" value={os} onChange={(e) => setOs(e.target.value)}>
              <option value="">Ubuntu 24.04 LTS (default)</option>
              {d.osTemplates.map((o) => (
                <option key={o.id} value={o.id}>{o.name}</option>
              ))}
            </select>
          </div>
        )}
        {kind === "GAME" && gameRow && (
          <>
            {gameRow.variants.length > 0 && (
              <div className="col-span-2">
                <label className="label">Server type</label>
                <select className="input" value={variant} onChange={(e) => setVariant(e.target.value)}>
                  {gameRow.variants.map((v) => (
                    <option key={v.id} value={v.id}>{v.label}</option>
                  ))}
                </select>
              </div>
            )}
            <div>
              <label className="label">Player slots</label>
              <input className="input" inputMode="numeric" value={slots} onChange={(e) => setSlots(e.target.value)} placeholder="—" />
            </div>
          </>
        )}
        {kind !== "DEDICATED" && (
          <div className={kind === "VPS" ? "col-span-2" : "col-span-2"}>
            <label className="label">Hostname (optional)</label>
            <input className="input" value={hostname} onChange={(e) => setHostname(e.target.value.toLowerCase())} placeholder="auto" maxLength={40} />
          </div>
        )}
      </fieldset>

      <fieldset className="grid gap-3 sm:grid-cols-2">
        <legend className="section-label mb-1">Placement &amp; extras</legend>
        {kind !== "DEDICATED" && (
          <div>
            <label className="label">Node</label>
            <select className="input" value={nodeId} onChange={(e) => setNodeId(e.target.value)}>
              <option value="">Automatic (least-loaded in region)</option>
              {d.nodes.map((n) => (
                <option key={n.id} value={n.id}>
                  {n.name} · {n.region}
                  {n.monthlyCostCents ? ` · ${money(n.monthlyCostCents)}/mo` : ""}
                </option>
              ))}
            </select>
          </div>
        )}
        <div>
          <label className="label">Region preference</label>
          <select className="input" value={region} onChange={(e) => setRegion(e.target.value)}>
            <option value="">Customer&apos;s default</option>
            {d.regions.map((r) => (
              <option key={r} value={r}>{r}</option>
            ))}
          </select>
        </div>
        {kind !== "DEDICATED" && (
          <div className="flex flex-wrap gap-x-5 gap-y-2 sm:col-span-2">
            <label className="flex items-center gap-2 text-sm text-slate-300">
              <input type="checkbox" checked={cpuPinning} onChange={(e) => setCpuPinning(e.target.checked)} /> Pinned CPU cores
              <span className="text-[11px] text-amber-300/80">manual task</span>
            </label>
            <label className="flex items-center gap-2 text-sm text-slate-300">
              <input type="checkbox" checked={cpuPriority} onChange={(e) => setCpuPriority(e.target.checked)} /> CPU priority
              <span className="text-[11px] text-amber-300/80">manual task</span>
            </label>
            <label className="flex items-center gap-2 text-sm text-slate-300">
              <input type="checkbox" checked={dedicatedIp} onChange={(e) => setDedicatedIp(e.target.checked)} /> Dedicated IPv4
              <span className="text-[11px] text-slate-500">{ipLine}</span>
            </label>
          </div>
        )}
      </fieldset>

      <fieldset className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <legend className="section-label mb-1">Price (USD)</legend>
        <div>
          <label className="label">Renews at ($/mo)</label>
          <input className="input" inputMode="decimal" value={renewal} onChange={(e) => setRenewal(e.target.value)} placeholder="75.80" />
        </div>
        <div>
          <label className="label">Term</label>
          <select className="input" value={term} onChange={(e) => setTerm(Number(e.target.value))}>
            <option value={1}>Monthly</option>
            <option value={12}>Annual (12 mo)</option>
          </select>
        </div>
        <div>
          <label className="label">First-term discount %</label>
          <input
            className="input"
            inputMode="decimal"
            value={discountPct}
            onChange={(e) => {
              setDiscountPct(e.target.value);
              setFirstTermTouched(false);
            }}
            placeholder="0"
          />
        </div>
        <div>
          <label className="label">First term total ($)</label>
          <input
            className="input"
            inputMode="decimal"
            value={firstTerm}
            onChange={(e) => {
              setFirstTerm(e.target.value);
              setFirstTermTouched(true);
            }}
          />
          {Number.isFinite(regularTerm) && <p className="mt-1 text-[11px] text-slate-500">regular {money(regularTerm)}</p>}
        </div>
        <div className="col-span-2">
          <label className="label">Discount label (optional)</label>
          <input className="input" value={discountLabel} onChange={(e) => setDiscountLabel(e.target.value)} placeholder="50% off your first month" maxLength={80} />
        </div>
        <div>
          <label className="label">Setup fee ($)</label>
          <input className="input" inputMode="decimal" value={setupFee} onChange={(e) => setSetupFee(e.target.value)} />
        </div>
        <div>
          <label className="label">Valid for (days)</label>
          <input className="input" inputMode="numeric" value={expiryDays} onChange={(e) => setExpiryDays(e.target.value)} />
        </div>
      </fieldset>

      <div className="grid gap-3 sm:grid-cols-2">
        <div>
          <label className="label">Notes for the customer</label>
          <textarea className="input min-h-[72px]" value={notes} onChange={(e) => setNotes(e.target.value)} maxLength={2000} placeholder="What's included, setup timeline…" />
        </div>
        <div>
          <label className="label">Internal note (staff only)</label>
          <textarea className="input min-h-[72px]" value={internalNote} onChange={(e) => setInternalNote(e.target.value)} maxLength={2000} placeholder="Why this price, who approved it…" />
        </div>
      </div>

      {preview && (
        <div className="grid gap-3 rounded-xl border border-white/10 bg-white/[0.02] p-3 text-sm sm:grid-cols-3" data-testid="offer-preview">
          <div>
            <p className="text-[11px] uppercase tracking-wide text-slate-500">Due now (before tax)</p>
            <p className="text-lg font-bold text-slate-100">{money(preview.totals.dueNowNetCents)}</p>
            <p className="text-xs text-slate-400">
              then {money(preview.totals.renewalMonthlyAllInCents)}/mo
              {preview.totals.termPromoPercent > 0 && <> · {preview.totals.termPromoPercent}% off first term</>}
            </p>
          </div>
          <div>
            <p className="text-[11px] uppercase tracking-wide text-slate-500">{preview.catalog.label}</p>
            <p className="text-lg font-bold text-slate-100">{preview.catalog.monthlyCents != null ? `${money(preview.catalog.monthlyCents)}/mo` : "—"}</p>
            {preview.catalog.monthlyCents != null && Number.isFinite(input.renewalMonthlyCents) && (
              <p className={`text-xs ${input.renewalMonthlyCents < preview.catalog.monthlyCents ? "text-amber-300" : "text-emerald-300"}`}>
                offer is {money(Math.abs(input.renewalMonthlyCents - preview.catalog.monthlyCents))}/mo {input.renewalMonthlyCents < preview.catalog.monthlyCents ? "below" : "above"} self-serve
              </p>
            )}
            {preview.catalog.note && <p className="text-xs text-slate-500">{preview.catalog.note}</p>}
          </div>
          <div>
            <p className="text-[11px] uppercase tracking-wide text-slate-500">Margin vs node cost</p>
            {preview.margin ? (
              <>
                <p className={`text-lg font-bold ${preview.margin.marginCents < 0 ? "text-red-400" : "text-slate-100"}`}>
                  {money(preview.margin.marginCents)}/mo · {preview.margin.marginPercent}%
                </p>
                <p className="text-xs text-slate-400">
                  cost share {money(preview.margin.costShareCents)}/mo of {preview.margin.nodeName} (by RAM)
                </p>
              </>
            ) : (
              <p className="text-xs text-slate-500">No node cost on record{kind === "DEDICATED" ? " (dedicated)" : ""}.</p>
            )}
          </div>
          {preview.errors.length > 0 && (
            <ul className="space-y-0.5 text-xs text-amber-300 sm:col-span-3">
              {preview.errors.map((e) => (
                <li key={e}>• {e}</li>
              ))}
            </ul>
          )}
        </div>
      )}

      {errors.length > 0 && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
          {errors.map((e) => (
            <p key={e}>{e}</p>
          ))}
        </div>
      )}
      {done && <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{done}</div>}

      <div className="flex flex-wrap items-center justify-end gap-3">
        <label className="mr-auto flex items-center gap-2 text-sm text-slate-400">
          <input type="checkbox" checked={emailCustomer} onChange={(e) => setEmailCustomer(e.target.checked)} /> Also email the customer a link
        </label>
        <button type="button" className="btn-ghost" disabled={pending || !d.customer} onClick={() => submit(false)}>
          Save draft
        </button>
        <button type="button" className="btn-primary" disabled={pending || !d.customer || (preview?.errors.length ?? 0) > 0} onClick={() => submit(true)}>
          {pending ? "Sending…" : "Send offer"}
        </button>
      </div>
    </div>
  );
}

export default OfferComposer;

