      <FeedbackAurora />
      {/* relative z-[1]: the aurora is a fixed, z-0 layer (same reason every
          other account-page aurora needs this on its content wrapper — see
          app/dashboard/services/page.tsx's identical comment). */}
      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col gap-5">
      {/* No bespoke hero art for this page — it's a beta-rollout utility page,
          not a marquee feature, so the same eyebrow/title/tagline pattern as
          Activity's header carries it without needing a new asset. The
          eyebrow and glow tie back to the header's own neon bug icon
          (BugReportButton) so the two read as one feature, not two. */}
      <header className="relative flex flex-col gap-3.5 py-2">
        <span className="text-[12.5px] font-extrabold uppercase tracking-[0.24em]" style={{ color: "var(--color-neon-bug)" }}>
          Feedback
        </span>
        <h1 className="text-[40px] font-extrabold leading-[1.08] tracking-[-0.03em] text-white sm:text-[50px]">
          Help us fix what&apos;s{" "}
          <span className="bg-[linear-gradient(96deg,var(--color-neon-bug),var(--color-mint))] bg-clip-text text-transparent">broken.</span>
        </h1>
        <p className="max-w-[54ch] text-[14px] leading-[1.6] text-tx-mute">
