          { icon: "clock2", tone: "amber" as const, value: inProgress, label: "In progress" },
          { icon: "checkcircle", tone: "mint" as const, value: done, label: "Shipped" },
        ].map((s) => (
          <section key={s.label} className="card flex min-h-[88px] min-w-0 items-center gap-3 p-3.5">
            <Icon name={s.icon} tone={s.tone} size={24} />
            <span className="flex min-w-0 flex-col gap-0.5">
              <span className="num text-[23px] leading-none text-white">{s.value}</span>
