import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireUser, impersonating } from "@/lib/auth";
import { PageShell, Panel } from "@/components/nx/PageShell";
import { getOfferForViewer } from "@/lib/offers";
import { offerAmountDue, trustedTerms } from "@/lib/offer-fulfil";
import { money, termLabel, kindLabel, offerTotals } from "@/lib/offer-pricing";
import { OfferAcceptPanel } from "@/components/customer/offers/OfferAcceptPanel";

export const dynamic = "force-dynamic";

const STATUS: Record<string, { label: string; cls: string }> = {
  SENT: { label: "Ready for you", cls: "border-[#8a70fb]/40 bg-[#6f47f5]/15 text-[#c9bcff]" },
  VIEWED: { label: "Ready for you", cls: "border-[#8a70fb]/40 bg-[#6f47f5]/15 text-[#c9bcff]" },
  ACCEPTED: { label: "Payment pending", cls: "border-cyan-400/40 bg-cyan-400/10 text-cyan-200" },
  PAID: { label: "Paid", cls: "border-emerald-400/40 bg-emerald-400/10 text-emerald-200" },
  EXPIRED: { label: "Expired", cls: "border-white/15 bg-white/5 text-tx-dim" },
  CANCELLED: { label: "Withdrawn", cls: "border-white/15 bg-white/5 text-tx-dim" },
  DECLINED: { label: "Declined", cls: "border-white/15 bg-white/5 text-tx-dim" },
};

function fmtDate(iso: string | null): string {
  if (!iso) return "—";
  return new Date(iso).toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit", timeZone: "UTC", timeZoneName: "short" });
}

export default async function OfferPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ paid?: string }> }) {
  const user = await requireUser();
  const { id } = await params;
  const sp = await searchParams;
  // Never flip SENT -> VIEWED for an admin who is impersonating the customer.
  const imp = await impersonating();
  const view = await getOfferForViewer(id, { user, staff: false }, { markViewed: !imp });
  if (!view) notFound();

  const open = view.status === "SENT" || view.status === "VIEWED" || view.status === "ACCEPTED";
  let due: Awaited<ReturnType<typeof offerAmountDue>> | null = null;
  let renewalTermCents = view.renewalMonthlyAllInCents * view.termMonths;
  if (open) {
    const row = await db.offer.findUnique({ where: { id: view.id } });
    try {
      const terms = trustedTerms(row!);
      due = await offerAmountDue(terms, user);
      renewalTermCents = offerTotals(terms).renewalTermCents;
    } catch {
      due = null;
    }
  }
  const tone = STATUS[view.status] ?? STATUS.SENT;
  const regular = view.renewalMonthlyCents * view.termMonths;
  const discounted = view.firstTermCents < regular;

  return (
    <PageShell
      narrow
      eyebrow={`Custom offer #${view.number}`}
      title={view.title}
      sub={`A ${kindLabel(view.kind).toLowerCase()} built for you by the Nxeon team. Review the details, then accept and pay to have it set up.`}
      action={<span className={`rounded-full border px-3 py-1 text-[12px] font-bold ${tone.cls}`}>{tone.label}</span>}
    >
      {sp.paid === "1" && view.status !== "PAID" && (
        <div className="rounded-[13px] border border-cyan-400/30 bg-cyan-400/10 px-4 py-3 text-[13px] text-cyan-100">
          We received your payment and are finishing your order. This page updates once it&apos;s done — if it takes more than a few minutes, message us in chat.
        </div>
      )}
      {view.status === "PAID" && (
        <div className="rounded-[13px] border border-emerald-400/30 bg-emerald-400/10 px-4 py-3 text-[13px] text-emerald-100">
          Paid {fmtDate(view.paidAt)}.{" "}
          {view.serverId ? (
            <>
              Your server is being set up —{" "}
              <Link className="font-bold underline" href={`/dashboard/servers/${view.serverId}`}>
                open it
              </Link>
              .
            </>
          ) : (
            <>Our team is preparing your dedicated server and will be in touch shortly.</>
          )}{" "}
          {view.invoiceId && (
            <Link className="underline" href={`/dashboard/invoices/${view.invoiceId}`}>
              View invoice
            </Link>
          )}
        </div>
      )}

      <div className="grid gap-4 lg:grid-cols-[1fr_380px]">
        <div className="flex min-w-0 flex-col gap-4">
          <Panel title="What's included" sub={kindLabel(view.kind)}>
            <ul className="flex flex-col gap-2">
              {view.specLines.map((l, i) => (
                <li key={i} className="flex items-start gap-2.5 text-[14px] text-tx-body">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="mt-0.5 flex-none text-[#22d3ee]" aria-hidden>
                    <path d="M20 6 9 17l-5-5" />
                  </svg>
                  <span>{l}</span>
                </li>
              ))}
            </ul>
            {view.notes && (
              <div className="mt-3 whitespace-pre-line rounded-[11px] border border-white/[0.07] bg-white/[0.03] px-3.5 py-3 text-[13px] leading-relaxed text-tx-mute">
                {view.notes}
              </div>
            )}
          </Panel>

          <Panel title="Pricing" sub="Billed in USD">
            <dl className="flex flex-col divide-y divide-white/[0.06] text-[13.5px]">
              <div className="flex items-baseline justify-between gap-3 py-2">
                <dt className="text-tx-mute">First {view.termMonths === 1 ? "month" : "year"}</dt>
                <dd className="text-right">
                  {discounted && <span className="mr-2 text-tx-faint line-through">{money(regular)}</span>}
                  <span className="num font-bold text-white">{money(view.firstTermCents)}</span>
                  {discounted && view.discountLabel && <span className="ml-2 text-[11.5px] font-semibold text-[#22d3ee]">{view.discountLabel}</span>}
                </dd>
              </div>
              {view.setupFeeCents > 0 && (
                <div className="flex justify-between gap-3 py-2">
                  <dt className="text-tx-mute">One-time setup</dt>
                  <dd className="num font-semibold text-white">{money(view.setupFeeCents)}</dd>
                </div>
              )}
              {view.ipTermCents > 0 && (
                <div className="flex justify-between gap-3 py-2">
                  <dt className="text-tx-mute">Dedicated IPv4 ({termLabel(view.termMonths).toLowerCase()})</dt>
                  <dd className="num font-semibold text-white">{money(view.ipTermCents)}</dd>
                </div>
              )}
              <div className="flex justify-between gap-3 py-2">
                <dt className="text-tx-mute">Then renews at</dt>
                <dd className="num font-semibold text-white">
                  {money(view.renewalMonthlyAllInCents)}/mo
                  {view.termMonths === 12 && <span className="ml-1 text-[11.5px] font-normal text-tx-faint">({money(renewalTermCents)} billed yearly)</span>}
                </dd>
              </div>
            </dl>
            <p className="mt-2 text-[11.5px] leading-relaxed text-tx-faint">
              Renewals are charged automatically from your wallet, then your saved card, at the price above. You can turn auto-renew off at any time from the server page.
            </p>
          </Panel>
        </div>

        <div className="flex min-w-0 flex-col gap-4">
          <Panel title={open ? "Accept & pay" : "Offer status"} sub={open ? `Valid until ${fmtDate(view.expiresAt)}` : undefined}>
            {open && due ? (
              <OfferAcceptPanel
                offerId={view.id}
                netCents={due.netCents}
                taxCents={due.taxCents}
                taxRatePercent={due.taxRatePercent}
                grossCents={due.grossCents}
                walletBalanceCents={user.balanceCents}
                impersonating={!!imp}
              />
            ) : open ? (
              <p className="text-[13px] text-amber-200">This offer needs a quick update from our team before it can be paid. Message us in chat and we&apos;ll sort it out.</p>
            ) : view.status === "PAID" ? (
              <p className="text-[13px] text-tx-mute">This offer is paid — thank you.</p>
            ) : (
              <p className="text-[13px] text-tx-mute">
                This offer is {view.status === "CANCELLED" ? "no longer available" : view.status.toLowerCase()}. Message us in chat if you&apos;d like a new one.
              </p>
            )}
            {view.fulfilError && view.status !== "PAID" && (
              <p className="mt-2 rounded-[10px] border border-amber-400/30 bg-amber-400/10 px-3 py-2 text-[12px] text-amber-100">{view.fulfilError}</p>
            )}
          </Panel>
          <p className="px-1 text-[11.5px] leading-relaxed text-tx-faint">
            Questions about this offer? Reply in the chat it was sent from, or open a ticket from{" "}
            <Link href="/dashboard/support" className="underline">
              Support
            </Link>
            .
          </p>
        </div>
      </div>
    </PageShell>
  );
}

