"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { acceptOfferAction, declineOfferAction } from "@/lib/actions-offers";
import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
import { walletSplit, STRIPE_MIN_CENTS } from "@/lib/wallet-split";
import { money } from "@/lib/offer-pricing";

/**
 * Accept & Pay for a custom offer. The wallet/card split shown here is the SAME
 * walletSplit the server action runs on the same gross, so the figures shown are
 * the figures charged; the server re-derives everything from the frozen terms
 * before taking anything.
 */
export function OfferAcceptPanel({
  offerId,
  netCents,
  taxCents,
  taxRatePercent,
  grossCents,
  walletBalanceCents,
  impersonating,
}: {
  offerId: string;
  netCents: number;
  taxCents: number;
  taxRatePercent: number;
  grossCents: number;
  walletBalanceCents: number;
  impersonating: boolean;
}) {
  const router = useRouter();
  const [useWallet, setUseWallet] = useState(walletBalanceCents > 0);
  const [error, setError] = useState<string | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
  const [declining, setDeclining] = useState(false);
  const [reason, setReason] = useState("");
  const [pending, start] = useTransition();

  const split = walletSplit({ dueCents: grossCents, balanceCents: walletBalanceCents, useWallet });

  return (
    <div className="flex flex-col gap-3" data-testid="offer-accept">
      <dl className="flex flex-col gap-1.5 text-[13px]">
        <div className="flex justify-between">
          <dt className="text-tx-mute">Subtotal</dt>
          <dd className="num text-white">{money(netCents)}</dd>
        </div>
        {taxCents > 0 && (
          <div className="flex justify-between">
            <dt className="text-tx-mute">Tax ({taxRatePercent}%)</dt>
            <dd className="num text-white">{money(taxCents)}</dd>
          </div>
        )}
        <div className="flex justify-between border-t border-white/[0.07] pt-1.5 text-[15px]">
          <dt className="font-bold text-white">Due today</dt>
          <dd className="num font-extrabold text-white">{money(grossCents)}</dd>
        </div>
      </dl>

      {walletBalanceCents > 0 && (
        <label className="flex items-center justify-between gap-3 rounded-[11px] border border-white/[0.07] bg-white/[0.03] px-3 py-2 text-[12.5px] text-tx-dim">
          <span className="flex items-center gap-2">
            <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
            Use wallet balance ({money(walletBalanceCents)})
          </span>
          <span className="num text-tx-faint">{useWallet ? `−${money(split.walletApplied)}` : "off"}</span>
        </label>
      )}
      <p className="text-[12px] leading-relaxed text-tx-faint">
        {split.cardCents > 0 ? (
          <>
            {split.walletApplied > 0 && <>{money(split.walletApplied)} from your wallet, </>}
            {money(split.cardCents)} by secure card checkout. Your card is saved for renewals.
            {split.clampedForStripeMin && <> Card payments have a {money(STRIPE_MIN_CENTS)} minimum.</>}
          </>
        ) : split.belowStripeMin && walletBalanceCents < grossCents ? (
          <>This is under the {money(STRIPE_MIN_CENTS)} card minimum, so it can only be paid from your wallet — top up first.</>
        ) : (
          <>Paid in full from your wallet.</>
        )}
      </p>

      {error && <p className="rounded-[10px] border border-red-500/30 bg-red-500/10 px-3 py-2 text-[12.5px] text-red-200">{error}</p>}
      {impersonating && <p className="text-[12px] text-amber-200">Payments are disabled while impersonating.</p>}

      <button
        type="button"
        className="nx-cta w-full px-4 py-3 text-[14px] disabled:opacity-60"
        disabled={pending || impersonating}
        onClick={() =>
          start(async () => {
            setError(null);
            try {
              const r = await acceptOfferAction(offerId, useWallet);
              if (r.checkout) return setCheckout(r.checkout);
              if (r.error) return setError(r.error);
              if (r.paid) {
                if (r.paid.serverId) router.push(`/dashboard/servers/${r.paid.serverId}?purchase=1`);
                else router.refresh();
              }
            } catch (e) {
              setError(String((e as Error)?.message ?? "Something went wrong."));
            }
          })
        }
      >
        {pending ? "Working…" : split.cardCents > 0 ? `Accept & pay ${money(split.cardCents)}` : `Accept & pay ${money(grossCents)}`}
      </button>

      {!declining ? (
        <button type="button" className="text-[12px] text-tx-faint underline-offset-2 hover:underline" onClick={() => setDeclining(true)} disabled={pending}>
          Not for me — decline this offer
        </button>
      ) : (
        <div className="flex flex-col gap-2 rounded-[11px] border border-white/[0.07] p-3">
          <textarea
            className="input min-h-[64px] text-[13px]"
            placeholder="Optional: what would make it work for you?"
            value={reason}
            onChange={(e) => setReason(e.target.value)}
            maxLength={500}
          />
          <div className="flex justify-end gap-2">
            <button type="button" className="btn-ghost py-1.5 text-[12px]" onClick={() => setDeclining(false)}>
              Keep it
            </button>
            <button
              type="button"
              className="btn-ghost py-1.5 text-[12px] text-red-300"
              disabled={pending || impersonating}
              onClick={() =>
                start(async () => {
                  const r = await declineOfferAction(offerId, reason);
                  if (r.error) setError(r.error);
                  else router.refresh();
                })
              }
            >
              Decline offer
            </button>
          </div>
        </div>
      )}

      {checkout && (
        <StripeCheckoutModal
          clientSecret={checkout.clientSecret}
          publishableKey={checkout.publishableKey}
          title="Complete your offer payment"
          onClose={() => {
            setCheckout(null);
            router.refresh();
          }}
        />
      )}
    </div>
  );
}

