import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageShell, Panel } from "@/components/nx/PageShell";
import { toView } from "@/lib/offers";
import { effectiveOfferStatus, money, type OfferStatusT } from "@/lib/offer-pricing";

export const dynamic = "force-dynamic";

const LABEL: Record<string, string> = {
  SENT: "Ready for you",
  VIEWED: "Ready for you",
  ACCEPTED: "Payment pending",
  PAID: "Paid",
  EXPIRED: "Expired",
  CANCELLED: "Withdrawn",
  DECLINED: "Declined",
};

export default async function OffersPage() {
  const user = await requireUser();
  const rows = await db.offer.findMany({
    where: { userId: user.id, status: { not: "DRAFT" } },
    orderBy: { createdAt: "desc" },
    take: 100,
  });
  const views = rows.map((o) => toView(o, effectiveOfferStatus({ status: o.status as OfferStatusT, expiresAt: o.expiresAt }), false));

  return (
    <PageShell narrow eyebrow="Offers" title="Your custom offers" sub="Builds and prices our team has prepared for you. Open one to review and accept it.">
      <Panel>
        {views.length === 0 ? (
          <p className="py-6 text-center text-[13px] text-tx-dim">No offers yet. Ask us in chat if you need something the deploy page doesn&apos;t offer.</p>
        ) : (
          <ul className="flex flex-col divide-y divide-white/[0.06]">
            {views.map((v) => (
              <li key={v.id}>
                <Link href={`/dashboard/offers/${v.id}`} className="flex flex-wrap items-center gap-x-4 gap-y-1 py-3 hover:opacity-90">
                  <span className="text-[11px] font-bold text-tx-faint">#{v.number}</span>
                  <span className="min-w-0 flex-1 truncate text-[14px] font-semibold text-white">{v.title}</span>
                  <span className="num text-[13px] text-tx-mute">
                    {money(v.firstTermCents)} then {money(v.renewalMonthlyAllInCents)}/mo
                  </span>
                  <span className="text-[12px] font-semibold text-[#c9bcff]">{LABEL[v.status] ?? v.status}</span>
                </Link>
              </li>
            ))}
          </ul>
        )}
      </Panel>
    </PageShell>
  );
}

