"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { cancelOfferAction, sendOfferAction, completeOfferTaskAction } from "@/lib/actions-offers";
import { OfferComposerForm } from "@/components/admin/chat/OfferComposer";

export function NewOfferPanel({ userId }: { userId: string }) {
  const router = useRouter();
  return (
    <div className="card">
      <OfferComposerForm
        target={{ userId }}
        onSent={({ offerId }) => {
          router.push(`/admin/offers?userId=${userId}&offer=${offerId}`);
          router.refresh();
        }}
      />
    </div>
  );
}

export function CancelOfferButton({ offerId }: { offerId: string }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <span className="inline-flex flex-col items-end">
      <button
        type="button"
        className="btn-ghost py-1 text-xs text-red-300"
        disabled={pending}
        onClick={() => {
          const reason = window.prompt("Cancel this offer? Optional reason (internal):", "");
          if (reason === null) return;
          start(async () => {
            const r = await cancelOfferAction(offerId, reason);
            if (r.error) setErr(r.error);
            else router.refresh();
          });
        }}
      >
        {pending ? "Cancelling…" : "Cancel"}
      </button>
      {err && <span className="text-[11px] text-red-400">{err}</span>}
    </span>
  );
}

export function SendDraftButton({ offerId }: { offerId: string }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <span className="inline-flex flex-col items-end">
      <button
        type="button"
        className="btn-primary py-1 text-xs"
        disabled={pending}
        onClick={() => {
          if (!window.confirm("Send this draft? Its terms are frozen once sent.")) return;
          const email = window.confirm("Also email the customer a link?");
          start(async () => {
            const r = await sendOfferAction(offerId, email);
            if (r.error) setErr(r.error);
            else router.refresh();
          });
        }}
      >
        {pending ? "Sending…" : "Send"}
      </button>
      {err && <span className="text-[11px] text-red-400">{err}</span>}
    </span>
  );
}

export function CompleteTaskButton({ taskId }: { taskId: string }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  return (
    <button
      type="button"
      className="btn-ghost py-1 text-xs"
      disabled={pending}
      onClick={() =>
        start(async () => {
          await completeOfferTaskAction(taskId);
          router.refresh();
        })
      }
    >
      {pending ? "…" : "Mark done"}
    </button>
  );
}

