import Link from "next/link";
import { db } from "@/lib/db";
import { requireAreaOrGrant } from "@/lib/staff-grants";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { toView } from "@/lib/offers";
import { effectiveOfferStatus, money, type OfferStatusT } from "@/lib/offer-pricing";
import { NewOfferPanel, CancelOfferButton, SendDraftButton, CompleteTaskButton } from "@/components/admin/offers/OfferAdminControls";
import OfferCard from "@/components/chat/cards/OfferCard";

export const dynamic = "force-dynamic";

const TONE: Record<string, "brand" | "green" | "red" | "amber" | "slate"> = {
  DRAFT: "slate",
  SENT: "brand",
  VIEWED: "brand",
  ACCEPTED: "amber",
  PAID: "green",
  EXPIRED: "slate",
  CANCELLED: "slate",
  DECLINED: "red",
};

const STATUSES = ["ALL", "DRAFT", "SENT", "VIEWED", "ACCEPTED", "PAID", "EXPIRED", "CANCELLED", "DECLINED"] as const;

/**
 * Custom offers — every offer staff have built, per customer or platform-wide, plus
 * the manual follow-ups fulfilment could not automate (CPU pinning/priority,
 * dedicated builds, failed fulfilments). Billing area (ADMIN/BILLING or a granted
 * EMPLOYEE): offers are priced money commitments.
 */
export default async function AdminOffers({
  searchParams,
}: {
  searchParams: Promise<{ userId?: string; status?: string; offer?: string; new?: string }>;
}) {
  await requireAreaOrGrant("billing");
  const sp = await searchParams;
  const status = STATUSES.includes((sp.status ?? "ALL") as (typeof STATUSES)[number]) ? sp.status ?? "ALL" : "ALL";
  const customer = sp.userId ? await db.user.findUnique({ where: { id: sp.userId }, select: { id: true, email: true, name: true } }) : null;

  const [offers, tasks, selected] = await Promise.all([
    db.offer.findMany({
      where: { ...(customer ? { userId: customer.id } : {}), ...(status !== "ALL" ? { status: status as OfferStatusT } : {}) },
      orderBy: { createdAt: "desc" },
      take: 200,
    }),
    db.offerTask.findMany({ where: { status: "OPEN" }, orderBy: { createdAt: "asc" }, include: { offer: { select: { number: true, userId: true } } }, take: 100 }),
    sp.offer ? db.offer.findUnique({ where: { id: sp.offer }, include: { events: { orderBy: { createdAt: "asc" } }, tasks: { orderBy: { createdAt: "asc" } } } }) : null,
  ]);
  const userIds = Array.from(new Set([...offers.map((o) => o.userId), ...tasks.map((t) => t.offer.userId), ...(selected ? [selected.userId, selected.createdById] : [])]));
  const users = new Map((await db.user.findMany({ where: { id: { in: userIds } }, select: { id: true, email: true, name: true } })).map((u) => [u.id, u]));
  const base = customer ? `/admin/offers?userId=${customer.id}` : "/admin/offers";
  const sep = customer ? "&" : "?";

  return (
    <div className="space-y-6">
      <PageHeader
        title={customer ? `Offers · ${customer.name}` : "Custom offers"}
        sub={customer ? customer.email : "Priced, frozen quotes staff send from live chat or a customer page. Customers accept and pay from their portal."}
      >
        {customer && (
          <div className="flex gap-2">
            <Link href={`/admin/users/${customer.id}`} className="btn-ghost py-1.5 text-sm">Customer →</Link>
            {!sp.new && <Link href={`${base}&new=1`} className="btn-primary py-1.5 text-sm">New offer</Link>}
          </div>
        )}
      </PageHeader>

      {customer && sp.new && <NewOfferPanel userId={customer.id} />}

      {tasks.length > 0 && (
        <div className="card border-amber-500/30">
          <p className="section-label mb-3 text-amber-300">Manual follow-ups ({tasks.length})</p>
          <ul className="divide-y divide-white/[0.06]">
            {tasks.map((t) => (
              <li key={t.id} className="flex flex-wrap items-start gap-3 py-2.5">
                <Badge tone={t.kind === "FULFIL_FAILED" ? "red" : "amber"}>{t.kind.replace(/_/g, " ").toLowerCase()}</Badge>
                <div className="min-w-0 flex-1">
                  <p className="text-sm font-semibold text-slate-100">{t.title}</p>
                  <p className="text-xs text-slate-400">{t.detail}</p>
                  <p className="mt-0.5 text-[11px] text-slate-500">
                    <Link className="hover:text-brand-300" href={`/admin/offers?offer=${t.offerId}`}>Offer #{t.offer.number}</Link>
                    {" · "}
                    {users.get(t.offer.userId)?.email ?? t.offer.userId}
                    {t.serverId && (
                      <>
                        {" · "}
                        <Link className="hover:text-brand-300" href={`/admin/servers/${t.serverId}`}>server</Link>
                      </>
                    )}
                    {" · "}
                    {t.createdAt.toISOString().slice(0, 16).replace("T", " ")} UTC
                  </p>
                </div>
                <CompleteTaskButton taskId={t.id} />
              </li>
            ))}
          </ul>
        </div>
      )}

      {selected && (
        <div className="grid gap-4 lg:grid-cols-[minmax(0,420px)_1fr]">
          <div className="card">
            <p className="section-label mb-2">Offer #{selected.number} — as the customer sees it</p>
            <OfferCard offerId={selected.id} viewer="admin" />
            {selected.internalNote && <p className="mt-3 whitespace-pre-line text-xs text-slate-400"><span className="font-semibold text-slate-300">Internal:</span> {selected.internalNote}</p>}
            <p className="mt-2 text-[11px] text-slate-500">
              For {users.get(selected.userId)?.email ?? selected.userId} · by {users.get(selected.createdById)?.email ?? selected.createdById}
              {selected.termsHash && <> · terms {selected.termsHash.slice(0, 12)}</>}
            </p>
            <div className="mt-3 flex flex-wrap gap-2">
              {selected.serverId && <Link className="btn-ghost py-1 text-xs" href={`/admin/servers/${selected.serverId}`}>Server →</Link>}
              {selected.invoiceId && <Link className="btn-ghost py-1 text-xs" href={`/admin/invoices?q=${selected.invoiceId}`}>Invoice →</Link>}
              {selected.conversationId && <Link className="btn-ghost py-1 text-xs" href={`/admin/chat?c=${selected.conversationId}`}>Chat →</Link>}
            </div>
          </div>
          <div className="card overflow-x-auto">
            <p className="section-label mb-2">Audit trail</p>
            <table className="table-shell min-w-[520px]">
              <tbody>
                {selected.events.map((e) => (
                  <tr key={e.id}>
                    <td className="whitespace-nowrap text-xs text-slate-500">{e.createdAt.toISOString().slice(0, 19).replace("T", " ")}</td>
                    <td className="font-mono text-xs">{e.action}</td>
                    <td className="text-xs text-slate-400">{e.detail}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            {selected.tasks.length > 0 && (
              <>
                <p className="section-label mb-2 mt-4">Follow-ups</p>
                <ul className="space-y-1 text-xs">
                  {selected.tasks.map((t) => (
                    <li key={t.id} className="text-slate-300">
                      <Badge tone={t.status === "DONE" ? "green" : "amber"}>{t.status.toLowerCase()}</Badge> {t.title}
                    </li>
                  ))}
                </ul>
              </>
            )}
          </div>
        </div>
      )}

      <div className="flex flex-wrap gap-1.5">
        {STATUSES.map((s) => (
          <Link
            key={s}
            href={s === "ALL" ? base : `${base}${sep}status=${s}`}
            className={`rounded-full border px-3 py-1 text-xs ${status === s ? "border-brand-400 bg-brand-500/20 text-brand-200" : "border-white/10 text-slate-400 hover:text-slate-200"}`}
          >
            {s.toLowerCase()}
          </Link>
        ))}
      </div>

      <div className="card overflow-x-auto p-0">
        {offers.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">
            No offers{status !== "ALL" ? ` with status ${status.toLowerCase()}` : ""}.{" "}
            {customer ? "Use “New offer” above." : "Send one from a live chat, or from a customer's page."}
          </p>
        ) : (
          <table className="table-shell min-w-[900px]">
            <thead>
              <tr>
                <th>#</th>
                <th>Customer</th>
                <th>Offer</th>
                <th className="text-right">First term</th>
                <th className="text-right">Renews</th>
                <th>Status</th>
                <th>Expires</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {offers.map((o) => {
                const eff = effectiveOfferStatus({ status: o.status as OfferStatusT, expiresAt: o.expiresAt });
                const v = toView(o, eff, true);
                const u = users.get(o.userId);
                return (
                  <tr key={o.id}>
                    <td className="font-mono text-xs text-slate-400">
                      <Link className="hover:text-brand-300" href={`${base}${sep}offer=${o.id}`}>#{o.number}</Link>
                    </td>
                    <td className="text-sm">
                      <Link className="hover:text-brand-300" href={`/admin/offers?userId=${o.userId}`}>{u?.email ?? o.userId}</Link>
                    </td>
                    <td>
                      <Link className="text-sm font-semibold text-slate-100 hover:text-brand-300" href={`${base}${sep}offer=${o.id}`}>{v.title}</Link>
                      <p className="text-xs text-slate-500">{v.specLines[0]}</p>
                      {o.fulfilError && <p className="text-xs text-red-400">{o.fulfilError}</p>}
                    </td>
                    <td className="text-right font-mono text-sm">{money(v.firstTermCents)}</td>
                    <td className="text-right font-mono text-sm">{money(v.renewalMonthlyAllInCents)}/mo</td>
                    <td>
                      <Badge tone={TONE[eff] ?? "slate"}>{eff.toLowerCase()}</Badge>
                    </td>
                    <td className="text-xs text-slate-400">{o.expiresAt ? o.expiresAt.toISOString().slice(0, 10) : "—"}</td>
                    <td className="text-right">
                      <div className="flex justify-end gap-2">
                        {eff === "DRAFT" && <SendDraftButton offerId={o.id} />}
                        {["DRAFT", "SENT", "VIEWED", "ACCEPTED"].includes(eff) && <CancelOfferButton offerId={o.id} />}
                        {o.serverId && <Link className="btn-ghost py-1 text-xs" href={`/admin/servers/${o.serverId}`}>Server</Link>}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

