export async function capacityCheckRamMB(ramMB: number): Promise<{ ok: boolean; reason?: string }> {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) {
    // No Node rows configured — fall back to the original flat, env-configured
    // single-host ceiling (matches pre-multi-node behavior/tests).
    const snap = await capacitySnapshot();
    if (ramProjectionExceedsCeiling(snap.committedRamMB, snap.ceilingRamMB, ramMB)) {
      return {
        ok: false,
        reason:
          "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
          "Please try a smaller plan or contact support.",
      };
    }
    return { ok: true };
  }

  const primary = nodes.find((n) => n.isPrimary) ?? nodes[0];
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const servers = await db.server.findMany({
        where: {
          status: { not: "DELETING" },
          OR: n.id === primary.id ? [{ nodeId: n.id }, { nodeId: null }] : [{ nodeId: n.id }],
        },
        select: { plan: { select: { ramMB: true } }, gamePlan: { select: { ramMB: true } } },
      });
      const committed = servers.reduce((sum, s) => sum + (s.gamePlan?.ramMB ?? s.plan.ramMB), 0);
      const ceiling = n.capacityRamMB * RAM_OVERSELL_FACTOR;
      return { committed, ceiling };
    })
  );

  const hasRoom = loads.some((l) => !ramProjectionExceedsCeiling(l.committed, l.ceiling, ramMB));
  if (!hasRoom) {
    return {
      ok: false,
      reason:
        "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
        "Please try a smaller plan or contact support.",
    };
  }
  return { ok: true };
}

/**
 * Would deploying `planId` push committed RAM past the oversell ceiling?
 * Returns { ok:false, reason } when the host cannot take the new server.
export async function diskCapacityCheck(
  nodeId: string | null | undefined,
  addDiskGB: number
): Promise<{ ok: boolean; reason?: string }> {
  const servers = await db.server.findMany({
    where: { status: { not: "DELETING" }, ...(nodeId ? { nodeId } : {}) },
    select: { extraDiskGB: true, plan: { select: { diskGB: true } }, gamePlan: { select: { diskGB: true } } },
  });
  // Committed disk counts the EFFECTIVE size of every server (plan + purchased
  // extra), otherwise expansions would silently oversubscribe the pool. A
  // game server's real commitment is its game plan's, not the (larger) base
  // VPS plan it rides on.
  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(baseDiskGBFor(s), s.extraDiskGB), 0);

  // Resolve usable pool size + REAL usage — prefer the live Proxmox NVMe pool.
  let usableGB = HOST_DISK_GB;
  let freeGB: number | null = null; // real free space (total − used), when known
  try {
    const n = nodeId
      ? await db.node.findUnique({ where: { id: nodeId } })
      : await db.node.findFirst({ where: { isPrimary: true } });
    if (n) {
      const client = pveFor({
        apiUrl: n.apiUrl,
        pveNode: n.pveNode,
        tokenId: n.tokenId,
        tokenSecret: n.tokenSecret,
      });
      const st = await client.get(`/nodes/${n.pveNode}/storage/${n.storageNvme}/status`);
      const totalGB = Number(st?.total ?? 0) / 1024 ** 3;
      const usedGB = Number(st?.used ?? 0) / 1024 ** 3;
      if (totalGB > 0) usableGB = totalGB;
      if (totalGB > 0 && usedGB >= 0) freeGB = Math.max(0, totalGB - usedGB);
    }
  } catch {
    // Proxmox unreachable — fall back to the configured HOST_DISK_GB (no live free).
  }

  // Guard 1 (the real one): never provision into a genuinely near-full pool.

