import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { stripComments } from "./_source-tools.ts";
import {
  type OfferInput,
  type OfferTerms,
  OFFER_PAYMENT_GRACE_MS,
  canFulfilPayment,
  canStartPayment,
  canTransition,
  effectiveOfferStatus,
  firstTermFromDiscount,
  offerChatCard,
  offerInvoiceLines,
  offerMargin,
  offerSpecLines,
  offerTotals,
  parseOfferTerms,
  stableStringify,
  termPromoPercentFor,
  validateOfferInput,
} from "../lib/offer-pricing.ts";
import { renewalCharge } from "../lib/renewal-charge.ts";
import { classifyCheckoutSession, isPurchaseLegSession } from "../lib/stripe.ts";

/**
 * CUSTOM OFFERS — the pure half: pricing, the frozen snapshot, the status machine,
 * the invoice lines, and the promise that what an offer says it renews at is what
 * lib/renewal-charge.ts will actually bill. The DB-backed half (idempotent
 * fulfilment, auth, expiry against a real transaction) is test/offers-db.test.ts.
 */

const base: OfferInput = {
  kind: "VPS",
  title: "Custom 6 vCPU / 32 GB VPS",
  cpuCores: 6,
  ramMB: 32 * 1024,
  diskGB: 120,
  storageTier: "nvme",
  bandwidthTB: 10,
  cpuPriority: true,
  cpuPinning: true,
  dedicatedIp: false,
  notes: "",
  internalNote: "",
  firstTermCents: 3790,
  renewalMonthlyCents: 7580,
  termMonths: 1,
  setupFeeCents: 0,
  discountLabel: "50% off your first month",
  discountPercent: 50,
  expiresInDays: 7,
};

function terms(over: Partial<OfferTerms["pricing"]> = {}, extras: Partial<OfferTerms["extras"]> = {}, kind: OfferTerms["kind"] = "VPS"): OfferTerms {
  return {
    v: 1,
    offerId: "off_1",
    number: 7,
    kind,
    title: "Custom 6 vCPU / 32 GB VPS",
    spec: {
      cpuCores: 6, ramMB: 32768, diskGB: 120, storageTier: "nvme", bandwidthTB: 10,
      osTemplateId: null, osName: "Ubuntu 24.04 LTS", gameFamily: null, gameFamilyName: null, gameVariant: null,
      gamePlanBasisId: null, slots: null, nodeId: "node6", region: "sgp1", hostname: null,
    },
    extras: { cpuPriority: true, cpuPinning: true, dedicatedIp: false, ...extras },
    notes: "",
    pricing: {
      currency: "USD", termMonths: 1, firstTermCents: 3790, renewalMonthlyCents: 7580, setupFeeCents: 0,
      discountLabel: "50% off your first month", discountPercent: 50, ipMonthlyCents: 0, ...over,
    },
    sentAt: "2026-10-06T00:00:00.000Z",
    expiresAt: "2026-10-13T00:00:00.000Z",
  };
}

/* ---------------- pricing ---------------- */

test("the real 2026-10-06 case: 50% off the first month of $75.80/mo", () => {
  assert.equal(firstTermFromDiscount(7580, 1, 50), 3790);
  const t = offerTotals(terms());
  assert.equal(t.dueNowNetCents, 3790);
  assert.equal(t.renewalTermCents, 7580);
  assert.equal(t.renewalMonthlyAllInCents, 7580);
  assert.equal(t.termPromoPercent, 50);
});

test("setup fee and dedicated IP are added to due-now; IP also rides every renewal", () => {
  const t = offerTotals(terms({ setupFeeCents: 2500, ipMonthlyCents: 300, termMonths: 12, firstTermCents: 80000, renewalMonthlyCents: 7580 }, { dedicatedIp: true }));
  assert.equal(t.ipTermCents, 3600);
  assert.equal(t.dueNowNetCents, 80000 + 2500 + 3600);
  assert.equal(t.renewalTermCents, 7580 * 12 + 3600);
  assert.equal(t.renewalMonthlyAllInCents, 7880);
});

test("a dedicated-server offer never bills a dedicated-IP line", () => {
  const t = offerTotals(terms({ ipMonthlyCents: 300 }, { dedicatedIp: true }, "DEDICATED"));
  assert.equal(t.ipTermCents, 0);
});

test("termPromoPercent is the honest proration basis, clamped 0..100", () => {
  assert.equal(termPromoPercentFor(7580, 7580, 1), 0);
  assert.equal(termPromoPercentFor(0, 7580, 1), 100);
  assert.equal(termPromoPercentFor(60000, 7580, 12), 34.04);
  assert.equal(termPromoPercentFor(100, 0, 1), 0);
});

test("displayed renewal === what lib/renewal-charge.ts bills for the server fulfilment creates", () => {
  // Fulfilment writes grandfatheredRenewalCents = R and annualDiscountPct = 0.
  for (const months of [1, 12]) {
    for (const ip of [false, true]) {
      const t = terms({ termMonths: months, ipMonthlyCents: 250, firstTermCents: 1000 }, { dedicatedIp: ip });
      const charge = renewalCharge(
        {
          termMonths: months,
          extraDiskGB: 0,
          plan: { name: "x", priceCents: 7580 },
          gamePlan: null,
          dedicatedIp: ip ? { id: "ip" } : null,
          wantsDedicatedIp: ip,
          backupTier: "FREE",
          annualDiscountPct: 0,
          grandfatheredRenewalCents: 7580,
        },
        { ipMonthlyCents: 250, extraDiskPerGbCents: 10, backupPlusCents: 100, annualDiscountPct: 20 },
      );
      assert.equal(charge.netCents, offerTotals(t).renewalTermCents, `VPS months=${months} ip=${ip}`);
    }
  }
  // Game server: GamePlan.termMonths = 1, priceCents = R.
  for (const months of [1, 12]) {
    const charge = renewalCharge(
      {
        termMonths: months,
        extraDiskGB: 0,
        plan: { name: "base", priceCents: 7580 },
        gamePlan: { name: "g", priceCents: 4200, termMonths: 1 },
        dedicatedIp: null,
        wantsDedicatedIp: false,
        backupTier: "FREE",
        annualDiscountPct: 0,
        grandfatheredRenewalCents: 4200,
      },
      { ipMonthlyCents: 250, extraDiskPerGbCents: 10, backupPlusCents: 100, annualDiscountPct: 20 },
    );
    assert.equal(charge.netCents, 4200 * months, `game months=${months}`);
  }
});

test("margin vs node cost is apportioned by RAM; null without cost data", () => {
  // node-6: $41/mo, 56,084 MB.
  const m = offerMargin(7580, 32768, { monthlyCostCents: 4100, capacityRamMB: 56084 });
  assert.ok(m);
  assert.equal(m!.costShareCents, Math.round((4100 * 32768) / 56084));
  assert.equal(m!.marginCents, 7580 - m!.costShareCents);
  assert.equal(offerMargin(7580, 32768, { monthlyCostCents: null, capacityRamMB: 56000 }), null);
  assert.equal(offerMargin(7580, 32768, null), null);
});

/* ---------------- validation ---------------- */

test("valid input passes; each guard rejects with a readable message", () => {
  assert.deepEqual(validateOfferInput(base), []);
  const bad = (p: Partial<OfferInput>) => validateOfferInput({ ...base, ...p });
  assert.ok(bad({ termMonths: 24 }).some((e) => /monthly or annual/.test(e)), "24/36 carry fixed discounts renewalCharge would apply on top");
  assert.ok(bad({ firstTermCents: 7581 }).some((e) => /higher than the regular/.test(e)));
  assert.ok(bad({ renewalMonthlyCents: 50 }).some((e) => /at least \$1/.test(e)));
  assert.ok(bad({ firstTermCents: -1 }).length > 0);
  assert.ok(bad({ firstTermCents: 12.5 }).length > 0, "cents must be integers");
  assert.ok(bad({ cpuCores: 0 }).length > 0);
  assert.ok(bad({ expiresInDays: 31 }).length > 0);
  assert.ok(bad({ kind: "GAME", gameFamily: "" }).some((e) => /game/.test(e)));
  assert.ok(bad({ hostname: "-bad-" }).length > 0);
  assert.deepEqual(bad({ kind: "DEDICATED", cpuCores: 16, ramMB: 65536, diskGB: 2000 }), []);
});

/* ---------------- snapshot ---------------- */

test("stableStringify is key-order independent (the terms hash can't drift on object order)", () => {
  assert.equal(stableStringify({ b: 1, a: { d: 2, c: [3, { f: 1, e: 2 }] } }), stableStringify({ a: { c: [3, { e: 2, f: 1 }], d: 2 }, b: 1 }));
  assert.notEqual(stableStringify({ a: 1 }), stableStringify({ a: 2 }));
});

test("parseOfferTerms refuses a snapshot that can't be billed safely", () => {
  assert.ok(parseOfferTerms(terms()));
  assert.equal(parseOfferTerms(null), null);
  assert.equal(parseOfferTerms({ ...terms(), v: 2 }), null);
  assert.equal(parseOfferTerms(terms({ termMonths: 24 })), null);
  assert.equal(parseOfferTerms(terms({ firstTermCents: 999999 })), null);
  assert.equal(parseOfferTerms(terms({ setupFeeCents: -5 })), null);
});

/* ---------------- invoice ---------------- */

test("invoice lines: multi-line description (title, then spec sub-lines) and they sum to due-now", () => {
  const t = terms({ setupFeeCents: 1500, ipMonthlyCents: 300 }, { dedicatedIp: true });
  const lines = offerInvoiceLines(t, "vps-abc1");
  assert.equal(lines.reduce((s, l) => s + l.amountCents, 0), offerTotals(t).dueNowNetCents);
  const first = lines[0].description.split("\n");
  assert.match(first[0], /^Custom 6 vCPU \/ 32 GB VPS \(vps-abc1\) — Monthly$/);
  assert.ok(first.includes("6 vCPU · 32 GB RAM · 120 GB NVMe"));
  assert.ok(first.includes("Dedicated (pinned) CPU cores"));
  assert.ok(first.includes("CPU priority scheduling"));
  assert.ok(first.some((l) => /50% off your first month: \$37\.90 instead of \$75\.80/.test(l)));
  assert.ok(first.some((l) => /Renews at \$75\.80\/mo · Offer #7/.test(l)));
  assert.ok(lines.some((l) => /^Dedicated IP — Monthly/.test(l.description)));
  assert.ok(lines.some((l) => l.description === "One-time setup fee" && l.amountCents === 1500));
});

test("spec lines name the game for a game offer and never leak the node name", () => {
  const t = terms();
  const g = { ...t, kind: "GAME" as const, spec: { ...t.spec, gameFamily: "valheim", gameFamilyName: "Valheim", gameVariant: "bepinex", slots: 16 } };
  const lines = offerSpecLines(g);
  assert.ok(lines.includes("Valheim (bepinex) · 16 player slots"));
  assert.ok(!lines.join(" ").includes("node6"));
});

/* ---------------- status machine + expiry ---------------- */

test("status transitions: terminal states are terminal, PAID only from an open offer", () => {
  assert.ok(canTransition("DRAFT", "SENT"));
  assert.ok(canTransition("SENT", "PAID"));
  assert.ok(canTransition("ACCEPTED", "PAID"));
  assert.ok(!canTransition("DRAFT", "PAID"), "a draft was never shown to the customer");
  for (const s of ["PAID", "EXPIRED", "CANCELLED", "DECLINED"] as const) {
    for (const to of ["SENT", "VIEWED", "ACCEPTED", "PAID", "CANCELLED"] as const) assert.ok(!canTransition(s, to), `${s} -> ${to}`);
  }
});

test("expiry is applied lazily; an accepted offer gets the payment grace", () => {
  const exp = new Date("2026-10-13T00:00:00Z");
  const before = new Date(exp.getTime() - 1);
  const after = new Date(exp.getTime() + 1);
  assert.equal(effectiveOfferStatus({ status: "SENT", expiresAt: exp }, before), "SENT");
  assert.equal(effectiveOfferStatus({ status: "VIEWED", expiresAt: exp }, after), "EXPIRED");
  assert.equal(effectiveOfferStatus({ status: "ACCEPTED", expiresAt: exp }, after), "ACCEPTED");
  assert.equal(effectiveOfferStatus({ status: "ACCEPTED", expiresAt: exp }, new Date(exp.getTime() + OFFER_PAYMENT_GRACE_MS)), "EXPIRED");
  assert.equal(effectiveOfferStatus({ status: "PAID", expiresAt: exp }, after), "PAID");

  assert.ok(canStartPayment({ status: "VIEWED", expiresAt: exp }, before));
  assert.ok(!canStartPayment({ status: "VIEWED", expiresAt: exp }, after));
  assert.ok(!canStartPayment({ status: "CANCELLED", expiresAt: exp }, before));

  // Card leg: honoured after expiry ONLY if accepted before expiry, within the grace.
  const acc = new Date(exp.getTime() - 60_000);
  assert.ok(canFulfilPayment({ status: "ACCEPTED", expiresAt: exp, acceptedAt: acc }, "card", after));
  assert.ok(!canFulfilPayment({ status: "ACCEPTED", expiresAt: exp, acceptedAt: acc }, "card", new Date(exp.getTime() + OFFER_PAYMENT_GRACE_MS)));
  assert.ok(!canFulfilPayment({ status: "ACCEPTED", expiresAt: exp, acceptedAt: after }, "card", after), "accepted after expiry");
  assert.ok(!canFulfilPayment({ status: "SENT", expiresAt: exp, acceptedAt: null }, "card", before), "a card payment always follows an accept");
  assert.ok(!canFulfilPayment({ status: "ACCEPTED", expiresAt: exp, acceptedAt: acc }, "wallet", after), "wallet path never gets grace");
  assert.ok(!canFulfilPayment({ status: "CANCELLED", expiresAt: exp, acceptedAt: acc }, "card", before), "a withdrawn offer is never fulfilled");
});

/* ---------------- Stripe routing ---------------- */

test("an offer checkout classifies as an offer purchase leg — never a top-up", () => {
  const md = { nxeonUserId: "u1", nxeonOffer: JSON.stringify({ offerId: "off_1", grossCents: 4170, taxCents: 380 }) };
  assert.ok(isPurchaseLegSession(md), "no 'Wallet top-up' invoice for the card leg");
  assert.deepEqual(classifyCheckoutSession({ metadata: md, payment_status: "paid" } as never), { kind: "offer", userId: "u1", offerId: "off_1", grossCents: 4170, taxCents: 380 });
  assert.equal(classifyCheckoutSession({ metadata: { ...md, nxeonOffer: "{bad" }, payment_status: "paid" } as never).kind, "unreadable");
  assert.equal(classifyCheckoutSession({ metadata: { ...md, nxeonOffer: JSON.stringify({ offerId: "x" }) }, payment_status: "paid" } as never).kind, "unreadable");
  assert.equal(classifyCheckoutSession({ metadata: md, payment_status: "unpaid" } as never).kind, "unpaid");
});

test("chat card payload is the typed card the live-chat renderer dispatches on", () => {
  assert.deepEqual(offerChatCard("abc"), { type: "offer", key: "offer:abc", offerId: "abc" });
});

/* ---------------- source guards ---------------- */

const FULFIL = stripComments(readFileSync(new URL("../lib/offer-fulfil.ts", import.meta.url), "utf8"));
const ACTIONS = stripComments(readFileSync(new URL("../lib/actions-offers.ts", import.meta.url), "utf8"));

test("fulfilment claims the offer (status CAS) INSIDE the same transaction as the wallet debit", () => {
  const tx = FULFIL.slice(FULFIL.indexOf("db.$transaction(async (tx)"));
  const cas = tx.indexOf("tx.offer.updateMany");
  const debit = tx.indexOf("debitWallet(tx");
  assert.ok(cas > 0 && debit > 0 && cas < debit, "the claim must precede the debit in one tx");
  assert.match(tx, /claimed\.count !== 1/);
  assert.match(tx, /termsHash: offer\.termsHash/, "CAS also pins the snapshot hash");
});

test("every staff action is billing-gated; customer spend path refuses impersonation", () => {
  for (const name of ["previewOfferAction", "createOfferAction", "sendOfferAction", "cancelOfferAction", "completeOfferTaskAction"]) {
    const i = ACTIONS.indexOf(`export async function ${name}(`);
    assert.ok(i > 0, name);
    const body = ACTIONS.slice(i, i + 400);
    assert.match(body, /requireGrant\("billing"\)/, `${name} must requireGrant("billing")`);
  }
  const acc = ACTIONS.slice(ACTIONS.indexOf("export async function acceptOfferAction("));
  assert.match(acc.slice(0, 300), /assertNotImpersonating\(\)/);
  assert.match(acc, /offer\.userId !== user\.id/, "ownership check");
});

