import { test, before, after } from "node:test";
import assert from "node:assert/strict";

/**
 * CUSTOM OFFERS — DB-backed half. Runs the REAL lib/offers.ts + lib/offer-fulfil.ts +
 * lib/fulfil-checkout.ts against a THROWAWAY Postgres with FAKE Stripe session objects
 * (fulfilRetrievedCheckoutSession) — no Stripe call is needed for the money logic.
 *
 * Opt-in and fail-closed, same guard as test/local-order-fulfilment.test.ts: runs only
 * when OFFERS_TEST_DATABASE_URL is set AND identical to DATABASE_URL AND points at
 * 127.0.0.1 on a non-default port with a database named `offers`. Otherwise skipped.
 *
 *   initdb a scratch cluster on e.g. :55471, createdb offers, then
 *   DATABASE_URL=postgresql://postgres@127.0.0.1:55471/offers OFFERS_TEST_DATABASE_URL=$DATABASE_URL \
 *     npx prisma db push --skip-generate && npx tsx --test test/offers-db.test.ts
 *
 * Proves: snapshot immutability, customer can only see their own (non-draft) offers,
 * idempotent fulfilment under concurrent wallet calls AND concurrent webhook+return
 * card calls (one server, one debit, one credit), a duplicate second payment is kept
 * as wallet credit + flagged, expiry (wallet refused; card honoured within grace only
 * if accepted in time), withdraw-during-checkout keeps the money safe, tampered terms
 * are refused, dedicated = invoice + task only, game offers, pinned node.
 */
const url = process.env.OFFERS_TEST_DATABASE_URL;
const safe = !!url && url === process.env.DATABASE_URL && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:(?!5432\b)\d+\/offers$/.test(url);
const skip = safe ? false : "set OFFERS_TEST_DATABASE_URL (throwaway 127.0.0.1 /offers db) to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let offers: typeof import("../lib/offers.ts");
let fulfil: typeof import("../lib/offer-fulfil.ts");
let checkout: typeof import("../lib/fulfil-checkout.ts");
let renewalCharge: typeof import("../lib/renewal-charge.ts")["renewalCharge"];
let staffId = "";
const RUN = Date.now().toString(36);

before(async () => {
  if (!safe) return;
  process.env.STRIPE_SECRET_KEY = "sk_test_fake_never_called";
  process.env.NXEON_HOST_RAM_MB = "100000000";
  delete process.env.SMTP_HOST;
  db = (await import("../lib/db.ts")).db;
  offers = await import("../lib/offers.ts");
  fulfil = await import("../lib/offer-fulfil.ts");
  checkout = await import("../lib/fulfil-checkout.ts");
  renewalCharge = (await import("../lib/renewal-charge.ts")).renewalCharge;
  // Never let a test mail go anywhere.
  await db.setting.upsert({ where: { key: "smtp_host" }, update: { value: "" }, create: { key: "smtp_host", value: "" } });
  const staff = await db.user.create({ data: { email: `staff-${RUN}@example.test`, passwordHash: "x", name: "Staff", role: "BILLING" } });
  staffId = staff.id;
  await db.osTemplate.upsert({ where: { slug: "ubuntu-24-04" }, update: { active: true }, create: { slug: "ubuntu-24-04", name: "Ubuntu 24.04 LTS", vmid: 9000, minRamMB: 512, minDiskGB: 10 } });
  await db.osTemplate.upsert({
    where: { slug: "valheim" },
    update: { active: true },
    create: { slug: "valheim", name: "Valheim", family: "valheim", category: "APPLICATION", vmid: 9101, minRamMB: 512, minDiskGB: 10 },
  });
});
after(async () => {
  if (safe) await db.$disconnect();
});

async function customer(balanceCents = 0, tag = "") {
  return db.user.create({ data: { email: `c-${tag}-${RUN}-${Math.random().toString(36).slice(2, 7)}@example.test`, passwordHash: "x", name: "Cust", balanceCents } });
}

function input(p: Partial<import("../lib/offer-pricing.ts").OfferInput> = {}): import("../lib/offer-pricing.ts").OfferInput {
  return {
    kind: "VPS",
    title: "Custom 2 vCPU / 4 GB VPS",
    cpuCores: 2,
    ramMB: 4096,
    diskGB: 40,
    storageTier: "nvme",
    bandwidthTB: 2,
    cpuPriority: true,
    cpuPinning: true,
    dedicatedIp: false,
    notes: "Includes a hand-held setup.",
    internalNote: "approved by owner",
    firstTermCents: 3790,
    renewalMonthlyCents: 7580,
    termMonths: 1,
    setupFeeCents: 0,
    discountLabel: "50% off your first month",
    discountPercent: 50,
    expiresInDays: 7,
    ...p,
  };
}

async function sentOffer(userId: string, p: Partial<import("../lib/offer-pricing.ts").OfferInput> = {}) {
  const c = await offers.createOfferDraft({ id: staffId }, input(p), { userId });
  assert.ok(c.ok, JSON.stringify(!c.ok && c.errors));
  const s = await offers.sendOffer({ id: staffId }, c.offer.id, { emailCustomer: false });
  assert.ok(s.ok);
  return db.offer.findUniqueOrThrow({ where: { id: c.offer.id } });
}

function fakeSession(id: string, userId: string, offerId: string, cardCents: number, grossCents: number, taxCents = 0) {
  return {
    id,
    metadata: { nxeonUserId: userId, nxeonOffer: JSON.stringify({ offerId, grossCents, taxCents }) },
    payment_status: "paid",
    amount_total: cardCents,
    currency: "usd",
    payment_intent: null,
    customer: null,
  } as never;
}

test("send freezes the terms; later edits to the row cannot change what is billed or shown", { skip }, async () => {
  const u = await customer(0, "snap");
  const o = await sentOffer(u.id);
  assert.equal(o.status, "SENT");
  assert.ok(o.termsHash && o.terms);
  await db.offer.update({ where: { id: o.id }, data: { title: "EDITED", firstTermCents: 1, renewalMonthlyCents: 100 } });
  const v = await offers.getOfferForViewer(o.id, { user: u, staff: false });
  assert.equal(v?.title, "Custom 2 vCPU / 4 GB VPS");
  assert.equal(v?.firstTermCents, 3790);
  assert.equal(v?.renewalMonthlyCents, 7580);
  // A second send is refused (CAS on DRAFT).
  assert.equal((await offers.sendOffer({ id: staffId }, o.id, { emailCustomer: false })).ok, false);
});

test("auth: a customer sees only their own, non-draft offers; staff see drafts", { skip }, async () => {
  const owner = await customer(0, "own");
  const other = await customer(0, "oth");
  const o = await sentOffer(owner.id);
  assert.equal(await offers.getOfferForViewer(o.id, { user: other, staff: false }), null);
  assert.ok(await offers.getOfferForViewer(o.id, { user: owner, staff: false }));
  const d = await offers.createOfferDraft({ id: staffId }, input(), { userId: owner.id });
  assert.ok(d.ok);
  assert.equal(await offers.getOfferForViewer(d.offer.id, { user: owner, staff: false }), null, "drafts are invisible to customers");
  assert.ok((await offers.getOfferForViewer(d.offer.id, { user: { id: staffId }, staff: true }))?.staff, "staff block present");
  assert.equal((await offers.getOfferForViewer(o.id, { user: owner, staff: false }))?.staff, null, "no staff block for customers");
  // Fulfilment refuses a different account.
  const r = await fulfil.fulfilOffer({ offerId: o.id, userId: other.id, via: "wallet" });
  assert.equal(r.ok, false);
  // Viewing marks VIEWED once.
  await offers.getOfferForViewer(o.id, { user: owner, staff: false }, { markViewed: true });
  assert.equal((await db.offer.findUniqueOrThrow({ where: { id: o.id } })).status, "VIEWED");
});

test("wallet: three concurrent accepts provision exactly once and debit exactly once", { skip }, async () => {
  const u = await customer(3790, "wal");
  const o = await sentOffer(u.id);
  const results = await Promise.all([1, 2, 3].map(() => fulfil.fulfilOffer({ offerId: o.id, userId: u.id, via: "wallet" })));
  assert.equal(results.filter((r) => r.ok && !r.already).length, 1, JSON.stringify(results));
  const servers = await db.server.findMany({ where: { userId: u.id }, include: { plan: true, jobs: true } });
  assert.equal(servers.length, 1);
  const s = servers[0];
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, 0);
  assert.equal(await db.invoice.count({ where: { userId: u.id } }), 1);
  const after = await db.offer.findUniqueOrThrow({ where: { id: o.id }, include: { tasks: true } });
  assert.equal(after.status, "PAID");
  assert.equal(after.serverId, s.id);
  // Billing fields.
  assert.equal(s.grandfatheredRenewalCents, 7580);
  assert.equal(s.annualDiscountPct, 0);
  assert.equal(s.termPromoPercent, 50);
  assert.equal(s.refundableTermCents, 3790);
  assert.equal(s.termMonths, 1);
  assert.equal(s.autoRenew, true);
  assert.equal(s.plan.active, false);
  assert.equal(s.plan.priceCents, 7580);
  assert.ok(s.jobs.some((j) => j.type === "PROVISION"));
  assert.ok(s.expiresAt && s.expiresAt.getTime() > Date.now() + 27 * 86_400_000);
  // Extras the platform can't apply are never dropped.
  assert.deepEqual(after.tasks.map((t) => t.kind).sort(), ["CPU_PINNING", "CPU_PRIORITY"]);
  // Invoice: multi-line, PAID, sums.
  const inv = await db.invoice.findUniqueOrThrow({ where: { id: after.invoiceId! } });
  assert.equal(inv.status, "PAID");
  assert.equal(inv.amountCents, 3790);
  const li = inv.lineItems as { description: string }[];
  assert.ok(li[0].description.includes("\n2 vCPU · 4 GB RAM · 40 GB NVMe"));
  // The created server renews at exactly the offer's renewal price.
  const ch = renewalCharge(
    { ...s, dedicatedIp: null, plan: { name: s.plan.name, priceCents: s.plan.priceCents }, gamePlan: null },
    { ipMonthlyCents: 300, extraDiskPerGbCents: 10, backupPlusCents: 100, annualDiscountPct: 20 },
  );
  assert.equal(ch.netCents, 7580);
});

test("card: webhook + return redirect racing, then a late redirect — one credit, one debit, one server", { skip }, async () => {
  const u = await customer(0, "card");
  const o = await sentOffer(u.id);
  await db.offer.update({ where: { id: o.id }, data: { status: "ACCEPTED", acceptedAt: new Date() } });
  const sess = fakeSession(`cs_test_offer_${RUN}_a`, u.id, o.id, 3790, 3790);
  const [a, b] = await Promise.all([checkout.fulfilRetrievedCheckoutSession(sess), checkout.fulfilRetrievedCheckoutSession(sess)]);
  const late = await checkout.fulfilRetrievedCheckoutSession(sess);
  assert.equal([a, b, late].filter((r) => r.fulfilled).length, 1, JSON.stringify([a, b, late]));
  assert.equal(a.kind, "offer");
  assert.equal(await db.server.count({ where: { userId: u.id } }), 1);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, 0);
