  assert.equal(r.fulfilled, false);
  assert.equal(await db.server.count({ where: { userId: u.id } }), 0);
  assert.equal((await db.user.findUniqueOrThrow({ where: { id: u.id } })).balanceCents, 3790);
  assert.ok(await db.offerTask.findFirst({ where: { offerId: o.id, kind: "FULFIL_FAILED" } }));
  assert.ok(await db.notification.findFirst({ where: { userId: u.id, href: `/dashboard/offers/${o.id}` } }));
  assert.equal((await db.offer.findUniqueOrThrow({ where: { id: o.id } })).status, "CANCELLED");
});

test("tampered terms are refused before any money moves", { skip }, async () => {
  const u = await customer(100_000, "tamper");
  const o = await sentOffer(u.id);
  const t = o.terms as Record<string, unknown>;
  await db.offer.update({ where: { id: o.id }, data: { terms: { ...t, pricing: { ...(t.pricing as object), firstTermCents: 1 } } } });
  const r = await fulfil.fulfilOffer({ offerId: o.id, userId: u.id, via: "wallet" });
