test("dedicated: invoice + staff build task, nothing provisioned", { skip }, async () => {
  const u = await customer(50_000, "ded");
  const o = await sentOffer(u.id, { kind: "DEDICATED", title: "Dedicated Ryzen 9 box", cpuCores: 16, ramMB: 65536, diskGB: 2000, cpuPriority: false, cpuPinning: false, firstTermCents: 20_000, renewalMonthlyCents: 20_000, discountPercent: null, discountLabel: null, setupFeeCents: 5000 });
