test("game offer: GamePlan + server with the family's default variant/config, renews at R", { skip }, async () => {
  const u = await customer(4200, "game");
  const o = await sentOffer(u.id, { kind: "GAME", title: "Valheim 16-slot", gameFamily: "valheim", slots: 16, cpuPinning: false, cpuPriority: false, firstTermCents: 4200, renewalMonthlyCents: 4200, discountPercent: null, discountLabel: null, ramMB: 8192, diskGB: 60 });
  const r = await fulfil.fulfilOffer({ offerId: o.id, userId: u.id, via: "wallet" });
  assert.ok(r.ok, JSON.stringify(r));
  const s = await db.server.findUniqueOrThrow({ where: { id: r.ok ? r.serverId! : "" }, include: { plan: true, gamePlan: true } });
  assert.equal(s.gamePlan?.gameFamily, "valheim");
  assert.equal(s.gamePlan?.active, false);
  assert.ok(s.gameVariant);
  const ch = renewalCharge(
    { ...s, dedicatedIp: null, plan: { name: s.plan.name, priceCents: s.plan.priceCents }, gamePlan: { name: s.gamePlan!.name, priceCents: s.gamePlan!.priceCents, termMonths: s.gamePlan!.termMonths } },
