});

test("a chat offer needs a signed-in customer; the chat gets the typed offer card", { skip }, async () => {
  const anon = await db.chatConversation.create({ data: { visitorId: `v-${RUN}`, name: "Anon", email: "anon@example.test" } });
  const bad = await offers.createOfferDraft({ id: staffId }, input(), { conversationId: anon.id });
  assert.equal(bad.ok, false);
  const u = await customer(0, "chat");
  const convo = await db.chatConversation.create({ data: { visitorId: `v2-${RUN}`, userId: u.id } });
  const c = await offers.createOfferDraft({ id: staffId }, input(), { conversationId: convo.id });
