});

test("staff-pinned node is honoured exactly", { skip }, async () => {
  const node = await db.node.create({
    data: { name: `node-test-${RUN}`, pveNode: "x", apiUrl: "https://127.0.0.1:1", tokenId: "t", tokenSecret: "s", publicIp: "127.0.0.1", region: "sgp1", monthlyCostCents: 4100, capacityRamMB: 56084 },
  });
  try {
    const u = await customer(3790, "pin");
