cd /tank/nxeon-wt-offers; python3 - <<'EOF'
p='lib/actions-offers.ts'
s=open(p).read()
a='''        const q = await customPlanQuote(spec);
        catalog = q.ok
          ? { label: "Custom-builder price", monthlyCents: q.priceCents, note: q.introPriceCents ? `builder intro ${(q.introPriceCents / 100).toFixed(2)}/mo first term` : null }
          : { label: "Custom-builder price", monthlyCents: null, note: q.reason };'''
b='''        const q = await customPlanQuote(spec);
        if (q.ok) {
          catalog = { label: "Custom-builder price", monthlyCents: q.priceCents, note: q.introPriceCents ? `builder intro ${(q.introPriceCents / 100).toFixed(2)}/mo first term` : null };
        } else {
          // Below the builder's floor: compare against the cheapest catalog plan that
          // covers the spec on every dimension, if one exists.
          const cover = await db.plan.findFirst({
            where: { active: true, sortOrder: { lt: 900 }, cpuCores: { gte: spec.cpuCores }, ramMB: { gte: spec.ramMB }, diskGB: { gte: spec.diskGB } },
            orderBy: { priceCents: "asc" },
          });
          catalog = cover
            ? { label: `Smallest catalog plan covering it: ${cover.name}`, monthlyCents: cover.priceCents, note: `${cover.cpuCores} vCPU / ${cover.ramMB / 1024} GB / ${cover.diskGB} GB` }
            : { label: "Self-serve price", monthlyCents: null, note: `No self-serve option covers this spec (${q.reason})` };
        }'''
assert a in s
s=s.replace(a,b,1)
open(p,'w').write(s)
EOF
timeout 600 npx tsc --noEmit 2>&1 | head -5

